src/access/audit-deny.ts.source:
/**
 * Audit logging for access-control denies.
 *
 * Every `engine.can()` deny that flows through `requiresAccess` (page guard)
 * or `withAdminFormAction` (form action handler) writes a row to
 * `audit_events` so admins can review access denials post-mortem. The
 * resource_id is the requested action id; the summary is the engine's
 * matched-policy reason string.
 */

import { withLocalStoreFallback } from "../admin-store-dispatch";
import { recordD1Audit } from "../d1-audit";
import type { EvaluationResult } from "./types";

export interface LogAccessDenyInput {
	subjectEmail: string;
	action: string;
	decision: EvaluationResult;
}

/**
 * Records an `access:deny` audit row. Best-effort: failures are swallowed so
 * the deny path itself never throws.
 */
export async function logAccessDeny(
	locals: App.Locals | null | undefined,
	input: LogAccessDenyInput,
): Promise<void> {
	const summary = input.decision.reason || "Access denied";
	try {
		await withLocalStoreFallback<void>(
			locals,
			async () =>
				recordD1Audit(
					locals,
					// buildAuditEntry only reads actor.email; role/name satisfy the
					// Actor type but are not persisted.
					{ email: input.subjectEmail } as never,
					"access:deny",
					"access",
					input.action,
					summary,
				),
			async (store) => {
				await store.recordAuditEvent({
					userEmail: input.subjectEmail,
					action: "access:deny",
					resourceType: "access",
					resourceId: input.action,
					summary,
				});
			},
		);
	} catch {
		// Audit logging is best-effort — never block a deny on a logging failure.
	}
}

src/access/engine.ts.source:
/**
 * Default JSON-condition policy engine.
 *
 * Construction:
 *   const engine = createPolicyEngine({ resolvePoliciesForSubject: ... });
 *
 * The engine is intentionally synchronous on the can() call — policies must
 * already be resolved for the subject (typically by a per-request middleware
 * that loads role + direct policies once and caches them on Astro.locals).
 *
 * Swap in a Rego or other implementation by writing your own object that
 * satisfies PolicyEngine; nothing in the call sites cares which engine it is.
 */

import { evaluate } from "./evaluator";
import type { Env, EvaluationResult, Policy, PolicyEngine, Resource, Subject } from "./types";

export interface JsonPolicyEngineOptions {
	/**
	 * Synchronous lookup — given a subject, return all policies the engine
	 * should consider. Typically the union of role policies + direct grants.
	 * The middleware that produces this list is the integration point with
	 * the access repository.
	 */
	resolvePoliciesForSubject: (subject: Subject) => readonly Policy[];
}

export function createPolicyEngine(options: JsonPolicyEngineOptions): PolicyEngine {
	return {
		can(subject: Subject, action: string, resource?: Resource, env?: Env): EvaluationResult {
			const policies = options.resolvePoliciesForSubject(subject);
			return evaluate(subject, action, policies, resource, env);
		},
		policiesFor(subject: Subject): readonly Policy[] {
			return options.resolvePoliciesForSubject(subject);
		},
	};
}

src/access/middleware.ts.source:
/**
 * Optional Astro middleware factory that eagerly resolves the per-request
 * access context. Most call sites can use `getAccessContext(astro)` lazily
 * from page frontmatter or action handlers; mounting this middleware just
 * shifts the resolution to the start of the request so downstream code
 * can read `Astro.locals.access` directly without an `await`.
 */

import { getAccessContext } from "./request-context";

type MiddlewareInput = {
	locals: App.Locals;
};

export function createAccessMiddleware() {
	return async (ctx: MiddlewareInput, next: () => Promise<Response>): Promise<Response> => {
		await getAccessContext(ctx);
		return next();
	};
}

