src/adapters/supabase.ts.source:
import {
	type AstropressHostedApiAdapterOptions,
	createAstropressHostedApiAdapter,
} from "../hosted-api-adapter";
import { createAstropressHostedPlatformAdapter } from "../hosted-platform-adapter";
import type { AstropressInMemoryPlatformAdapterOptions } from "../in-memory-platform-adapter";
import { stripTrailingSlashes } from "../path-helpers";
import type { AstropressPlatformAdapter } from "../platform-contracts";
import { FULL_STACK_CAPABILITIES } from "./adapter-record-helpers";

export interface AstropressSupabaseHostedConfig {
	url: string;
	serviceRoleKey: string;
	apiBaseUrl: string;
}

export type AstropressSupabaseAdapterOptions = Omit<
	AstropressInMemoryPlatformAdapterOptions,
	"capabilities"
> & {
	backingAdapter?: AstropressPlatformAdapter;
};

export function createAstropressSupabaseAdapter(options: AstropressSupabaseAdapterOptions = {}) {
	// Reject the misconfiguration that previously routed silently to the
	// in-memory fallback. Callers must supply a real backingAdapter, or at
	// least one of the granular stores (auth/content/media/revisions); the
	// in-memory fallback is a footgun in production and was only catchable
	// by asserting on the seed user id.
	if (
		!options.backingAdapter &&
		!options.auth &&
		!options.content &&
		!options.media &&
		!options.revisions
	) {
		throw new Error(
			"createAstropressSupabaseAdapter requires backingAdapter or one of auth/content/media/revisions. Pass a real adapter (e.g. createAstropressSqliteAdapter) or use createAstropressSupabaseSqliteAdapter.",
		);
	}
	return createAstropressHostedPlatformAdapter({
		...options,
		providerName: "supabase",
	});
}

export interface AstropressSupabaseHostedAdapterOptions extends AstropressSupabaseAdapterOptions {
	config?: AstropressSupabaseHostedConfig;
	env?: Record<string, string | undefined>;
	fetchImpl?: AstropressHostedApiAdapterOptions["fetchImpl"];
}

export function readAstropressSupabaseHostedConfig(
	env: Record<string, string | undefined> = process.env,
): AstropressSupabaseHostedConfig {
	const url = env.SUPABASE_URL?.trim();
	const serviceRoleKey = env.SUPABASE_SERVICE_ROLE_KEY?.trim();

	if (!url || !serviceRoleKey) {
		throw new Error("Supabase hosted config requires SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY.");
	}

	return {
		url,
		serviceRoleKey,
		apiBaseUrl: `${stripTrailingSlashes(url)}/functions/v1/astropress`,
	};
}

export function createAstropressSupabaseHostedAdapter(
	options: AstropressSupabaseHostedAdapterOptions = {},
) {
	const config = options.config ?? readAstropressSupabaseHostedConfig(options.env);
	if (
		!options.backingAdapter &&
		!options.content &&
		!options.media &&
		!options.revisions &&
		!options.auth
	) {
		return createAstropressHostedApiAdapter({
			providerName: "supabase",
			apiBaseUrl: config.apiBaseUrl,
			accessToken: config.serviceRoleKey,
			previewBaseUrl: `${stripTrailingSlashes(config.url)}/preview`,
			fetchImpl: options.fetchImpl,
			defaultCapabilities: {
				...options.defaultCapabilities,
				...FULL_STACK_CAPABILITIES,
			},
		});
	}
	return createAstropressHostedPlatformAdapter({
		...options,
		providerName: "supabase",
		defaultCapabilities: {
			...options.defaultCapabilities,
			...FULL_STACK_CAPABILITIES,
		},
		preview: options.preview ?? {
			async create() {
				return {
					url: `${stripTrailingSlashes(config.url)}/preview`,
				};
			},
		},
	});
}

src/admin-action-user-purge.ts.source:
/**
 * User data purge action (GDPR right of erasure).
 *
 * Admin-only. Accepts a JSON body `{ "email": "..." }` and:
 * - Revokes all active sessions for the user
 * - Anonymises audit log entries (replaces actor email with "[deleted]")
 * - Deletes comments by that email
 * - Deletes contact form submissions by that email
 * - Suspends the admin user account (or deletes it if requested)
 *
 * Returns a JSON export of all deleted/anonymised records for the operator's
 * own data-subject-request records.
 */

import { withLocalStoreFallback } from "./admin-store-dispatch";
import { createD1PurgeOps } from "./d1-purge";

export interface UserPurgeResult {
	ok: boolean;
	email: string;
	revokedSessions: number;
	anonymisedAuditEvents: number;
	deletedComments: number;
	deletedContactSubmissions: number;
	adminUserAction: "suspended" | "deleted" | "not_found";
	error?: string;
}

/**
 * Purge all personal data for a given email address.
 *
 * Dispatches to D1 (Cloudflare) or SQLite (local) based on the request context.
 *
 * @param email   The email address of the data subject.
 * @param locals  Astro App.Locals (used to access the database binding).
 * @param options Optional flags: `{ deleteAccount: true }` to permanently
 *                delete the admin user record instead of suspending it.
 */
export async function purgeUserData(
	email: string,
	locals: App.Locals,
	options: { deleteAccount?: boolean } = {},
): Promise<UserPurgeResult> {
	if (!email?.includes("@")) {
		return {
			ok: false,
			email,
			revokedSessions: 0,
			anonymisedAuditEvents: 0,
			deletedComments: 0,
			deletedContactSubmissions: 0,
			adminUserAction: "not_found",
			error: "Invalid email address",
		};
	}

	return withLocalStoreFallback(
		locals,
		async (db) => createD1PurgeOps(db).purgeUserData(email, options),
		async (store) => {
			if (store.purgeUserData) {
				return store.purgeUserData(email, options);
			}
			// Fallback: return zero counts if local store doesn't wire purge ops
			return {
				ok: true,
				email,
				revokedSessions: 0,
				anonymisedAuditEvents: 0,
				deletedComments: 0,
				deletedContactSubmissions: 0,
				adminUserAction: (options.deleteAccount
					? "deleted"
					: "suspended") as UserPurgeResult["adminUserAction"],
			};
		},
	);
}

src/admin-app-integration.ts.source:
import { createReadStream } from "node:fs";
import { copyFile, mkdir } from "node:fs/promises";
import { basename, join } from "node:path";
import { fileURLToPath } from "node:url";
import type { AstroIntegration } from "astro";

import {
	ADMIN_APP_ASSET_PATHS,
	ADMIN_APP_DEV_SERVE_ROUTES,
	ADMIN_APP_INJECTED_ROUTES,
	ADMIN_APP_INTEGRATION_NAME,
	ADMIN_APP_PAGES_DIRECTORY,
	ADMIN_APP_SECURITY_MIDDLEWARE_ENTRYPOINT,
	ADMIN_APP_SESSION_MIDDLEWARE_ENTRYPOINT,
} from "./admin-app-integration-data";
import { injectAstropressAdminRoutes } from "./admin-routes";
import { peekCmsConfig } from "./config";
import { astropressHostViteConfig, resolvePackageRoot } from "./integration-host-config";

const packageRoot = resolvePackageRoot(import.meta.url);

const packageResource = (relativePath: string) => join(packageRoot, relativePath);

const assetSources: Record<keyof typeof ADMIN_APP_ASSET_PATHS, string> = {
	adminCss: packageResource(ADMIN_APP_ASSET_PATHS.adminCss),
	sectionsCss: packageResource(ADMIN_APP_ASSET_PATHS.sectionsCss),
};

export function createAstropressAdminAppIntegration(): AstroIntegration {
	return {
		name: ADMIN_APP_INTEGRATION_NAME,
		hooks: {
			// Serve admin.css and sections.css from the package public directory
			// during development. sections.css is loaded by the section-editor
			// live-preview iframe (see web-components/page-preview.ts).
			"astro:server:setup": ({ server }) => {
				for (const { url, asset } of ADMIN_APP_DEV_SERVE_ROUTES) {
					server.middlewares.use(url, (_req, res) => {
						res.setHeader("Content-Type", "text/css; charset=utf-8");
						res.setHeader("Cache-Control", "no-cache");
						createReadStream(assetSources[asset]).pipe(res);
					});
				}
			},
			// Copy stylesheets into the build output for production deployments.
			"astro:build:done": async ({ dir }) => {
				const outDir = fileURLToPath(dir);
				await mkdir(outDir, { recursive: true });
				for (const asset of Object.values(assetSources)) {
					await copyFile(asset, join(outDir, basename(asset)));
				}
			},
			"astro:config:setup": ({ injectRoute, addMiddleware, updateConfig }) => {
				// Vite settings so a scaffolded project resolves the package with zero
				// hand-editing. Shared with the public-site integration so the two
				// can't drift (the copy-paste that caused #185).
				updateConfig({ vite: astropressHostViteConfig(packageRoot) });
				const pagesDirectory = packageResource(ADMIN_APP_PAGES_DIRECTORY);
				injectAstropressAdminRoutes(pagesDirectory, injectRoute);
				for (const { pattern, entrypoint } of ADMIN_APP_INJECTED_ROUTES) {
					injectRoute({ pattern, entrypoint: packageResource(entrypoint) });
				}

				// Inject plugin-declared admin routes
				const config = peekCmsConfig();
				if (config?.plugins) {
					for (const plugin of config.plugins) {
						if (plugin.adminRoutes) {
							for (const route of plugin.adminRoutes) {
								injectRoute({
									pattern: route.pattern,
									entrypoint: route.entrypoint,
								});
							}
						}
					}
				}

				// Resolve the signed-in admin from the session cookie into
				// `locals.adminUser` before the security middleware and the page
				// guards run. Without this a host could log in yet 403 on every
				// admin page (the guards read `locals.adminUser`, which nothing
				// else populates outside the e2e harness).
				addMiddleware({
					order: "pre",
					entrypoint: new URL(ADMIN_APP_SESSION_MIDDLEWARE_ENTRYPOINT, import.meta.url),
				});
				addMiddleware({
					order: "pre",
					entrypoint: new URL(ADMIN_APP_SECURITY_MIDDLEWARE_ENTRYPOINT, import.meta.url),
				});
			},
		},
	};
}

