src/cloudflare-vite-integration.ts.source:
export type AstropressCloudflareViteIntegration = {
	aliases: Array<{ find: string | RegExp; replacement: string }>;
	plugin: {
		name: string;
		enforce: "pre";
		resolveId: (id: string) => string | null;
	};
};

export type AstropressCloudflareViteIntegrationOptions = {
	cloudflareLocalRuntimeStubsPath?: string;
	cloudflareLocalImageStorageStubPath?: string;
	cloudflareLocalMediaStorageStubPath?: string;
	cloudflareSqliteAdapterStubPath?: string;
	cloudflareSqliteAdminRuntimeStubPath?: string;
	cloudflareSqliteBootstrapStubPath?: string;
};

type ResolvedStubPaths = {
	localImageStorage: string;
	localMediaStorage: string;
	sqliteAdapter: string;
	sqliteAdminRuntime: string;
	sqliteBootstrap: string;
	localRuntimeStubs: string;
};

type ResolveIdEntry = {
	check: (id: string, localRuntimeModulesPath: string) => boolean;
	stubKey: keyof ResolvedStubPaths;
};

const aliasPatterns: Array<{
	find: string | RegExp;
	stubKey: keyof ResolvedStubPaths;
}> = [
	{ find: "astropress/local-image-storage", stubKey: "localImageStorage" },
	{
		find: /^.*\/local-image-storage(?:\.[cm]?[jt]s)?$/,
		stubKey: "localImageStorage",
	},
	{ find: "astropress/local-media-storage", stubKey: "localMediaStorage" },
	{
		find: /^.*\/local-media-storage(?:\.[cm]?[jt]s)?$/,
		stubKey: "localMediaStorage",
	},
	{ find: "astropress/adapters/sqlite", stubKey: "sqliteAdapter" },
	{ find: /^.*\/adapters\/sqlite(?:\.[cm]?[jt]s)?$/, stubKey: "sqliteAdapter" },
	{ find: "astropress/sqlite-admin-runtime", stubKey: "sqliteAdminRuntime" },
	{
		find: /^.*\/sqlite-admin-runtime(?:\.[cm]?[jt]s)?$/,
		stubKey: "sqliteAdminRuntime",
	},
	{ find: "astropress/sqlite-bootstrap", stubKey: "sqliteBootstrap" },
	{
		find: /^.*\/sqlite-bootstrap(?:\.[cm]?[jt]s)?$/,
		stubKey: "sqliteBootstrap",
	},
	{
		find: /^\.\/local-runtime-modules(?:\.ts)?$/,
		stubKey: "localRuntimeStubs",
	},
	{
		find: /^.*\/local-runtime-modules(?:\.ts)?$/,
		stubKey: "localRuntimeStubs",
	},
];

const resolveIdEntries: ResolveIdEntry[] = [
	{
		check: (id) => isPackageStorageModuleRequest(id, "local-image-storage"),
		stubKey: "localImageStorage",
	},
	{
		check: (id) => isPackageStorageModuleRequest(id, "local-media-storage"),
		stubKey: "localMediaStorage",
	},
	{ check: (id) => isSqliteAdapterRequest(id), stubKey: "sqliteAdapter" },
	{
		check: (id) => isSqliteAdminRuntimeRequest(id),
		stubKey: "sqliteAdminRuntime",
	},
	{ check: (id) => isSqliteBootstrapRequest(id), stubKey: "sqliteBootstrap" },
	{
		check: (id, lrm) => isLocalRuntimeModuleRequest(id, lrm),
		stubKey: "localRuntimeStubs",
	},
];

function isLocalRuntimeModuleRequest(id: string, localRuntimeModulesPath: string): boolean {
	if (
		id === "./local-runtime-modules" ||
		id === "./local-runtime-modules.ts" ||
		id === "local-runtime-modules" ||
		id === "local-runtime-modules.ts"
	) {
		return true;
	}

	return (
		id === localRuntimeModulesPath ||
		id.endsWith("/local-runtime-modules") ||
		id.endsWith("/local-runtime-modules.ts")
	);
}

function isPackageStorageModuleRequest(
	id: string,
	moduleName: "local-image-storage" | "local-media-storage",
): boolean {
	return (
		id === `astropress/${moduleName}` ||
		id.endsWith(`/${moduleName}`) ||
		id.endsWith(`/${moduleName}.ts`) ||
		id.endsWith(`/${moduleName}.js`)
	);
}

function isSqliteAdminRuntimeRequest(id: string): boolean {
	return (
		id === "astropress/sqlite-admin-runtime" ||
		id.endsWith("/sqlite-admin-runtime") ||
		id.endsWith("/sqlite-admin-runtime.ts") ||
		id.endsWith("/sqlite-admin-runtime.js")
	);
}

function isSqliteAdapterRequest(id: string): boolean {
	return (
		id === "astropress/adapters/sqlite" ||
		id.endsWith("/adapters/sqlite") ||
		id.endsWith("/adapters/sqlite.ts") ||
		id.endsWith("/adapters/sqlite.js")
	);
}

function isSqliteBootstrapRequest(id: string): boolean {
	return (
		id === "astropress/sqlite-bootstrap" ||
		id.endsWith("/sqlite-bootstrap") ||
		id.endsWith("/sqlite-bootstrap.ts") ||
		id.endsWith("/sqlite-bootstrap.js")
	);
}

function normalizeImportId(id: string): string {
	let normalized = id.replaceAll("\\", "/");
	if (normalized.startsWith("file://")) {
		normalized = decodeURIComponent(normalized.replace(/^file:\/\/\/?/, "/"));
	}

	if (/^\/[a-zA-Z]:\//.test(normalized)) {
		return normalized.slice(1);
	}

	return normalized;
}

function resolveStubPaths(options: AstropressCloudflareViteIntegrationOptions): ResolvedStubPaths {
	return {
		localImageStorage:
			options.cloudflareLocalImageStorageStubPath ??
			"astropress/cloudflare-local-image-storage-stub",
		localMediaStorage:
			options.cloudflareLocalMediaStorageStubPath ??
			"astropress/cloudflare-local-media-storage-stub",
		sqliteAdapter:
			options.cloudflareSqliteAdapterStubPath ?? "astropress/cloudflare-sqlite-adapter-stub",
		sqliteAdminRuntime:
			options.cloudflareSqliteAdminRuntimeStubPath ??
			"astropress/cloudflare-sqlite-admin-runtime-stub",
		sqliteBootstrap:
			options.cloudflareSqliteBootstrapStubPath ?? "astropress/cloudflare-sqlite-bootstrap-stub",
		localRuntimeStubs:
			options.cloudflareLocalRuntimeStubsPath ?? "astropress/cloudflare-local-runtime-stubs",
	};
}

function resolvePluginId(
	normalizedId: string,
	localRuntimeModulesPath: string,
	stubs: ResolvedStubPaths,
): string | null {
	const match = resolveIdEntries.find((entry) =>
		entry.check(normalizedId, localRuntimeModulesPath),
	);
	return match ? stubs[match.stubKey] : null;
}

function buildAliases(
	stubs: ResolvedStubPaths,
	localRuntimeModulesPath: string,
): Array<{ find: string | RegExp; replacement: string }> {
	const aliases = aliasPatterns.map((entry) => ({
		find: entry.find,
		replacement: stubs[entry.stubKey],
	}));
	aliases.push({
		find: localRuntimeModulesPath,
		replacement: stubs.localRuntimeStubs,
	});
	return aliases;
}

export function createAstropressCloudflareViteIntegration(
	localRuntimeModulesPath: string,
	options: AstropressCloudflareViteIntegrationOptions = {},
): AstropressCloudflareViteIntegration {
	const stubs = resolveStubPaths(options);

	return {
		aliases: buildAliases(stubs, localRuntimeModulesPath),
		plugin: {
			name: "astropress-cloudflare-local-runtime-stubs",
			enforce: "pre",
			resolveId(id) {
				return resolvePluginId(normalizeImportId(id), localRuntimeModulesPath, stubs);
			},
		},
	};
}

src/cms-route-registry-helpers.ts.source:
import type { Actor } from "./persistence-types";
import type { RuntimeSystemRouteRecord } from "./runtime-route-registry";

export type { AstropressCmsRouteRegistryFactoryInput } from "./cms-route-registry-types";

import type { AstropressCmsRouteRegistryFactoryInput } from "./cms-route-registry-types";

interface RouteActor extends Actor {}

export type StructuredPageInput = {
	title: string;
	summary?: string;
	seoTitle?: string;
	metaDescription?: string;
	canonicalUrlOverride?: string;
	robotsDirective?: string;
	ogImage?: string;
	templateKey: string;
	alternateLinks?: Array<{ hreflang: string; href: string }>;
	// audit-boundary: opaque-passthrough -- user CMS route-registry config; narrowed at consumer
	sections?: Record<string, unknown> | null;
	revisionNote?: string;
};

export type ArchiveRouteInput = {
	title: string;
	summary?: string;
	seoTitle?: string;
	metaDescription?: string;
	canonicalUrlOverride?: string;
	robotsDirective?: string;
	revisionNote?: string;
};

/** Normalize structured page input fields, centralising branchy fallback logic. */
export function normalizeStructuredInput(rawInput: {
	title: string;
	summary?: string;
	seoTitle?: string;
	metaDescription?: string;
	canonicalUrlOverride?: string;
	robotsDirective?: string;
	ogImage?: string;
	templateKey: string;
	alternateLinks?: Array<{ hreflang: string; href: string }>;
	// audit-boundary: opaque-passthrough -- user CMS route-registry config; narrowed at consumer
	sections?: Record<string, unknown> | null;
}) {
	const title = rawInput.title.trim();
	const summary = rawInput.summary?.trim() || null;
	const seoTitle = rawInput.seoTitle?.trim() || title;
	const metaDescription = rawInput.metaDescription?.trim() || summary || title;
	const canonicalUrlOverride = rawInput.canonicalUrlOverride?.trim() || null;
	const robotsDirective = rawInput.robotsDirective?.trim() || null;
	const ogImage = rawInput.ogImage?.trim() || null;
	const alternateLinks = rawInput.alternateLinks ?? [];
	const sections = rawInput.sections ?? null;
	return {
		title,
		summary,
		seoTitle,
		metaDescription,
		canonicalUrlOverride,
		robotsDirective,
		ogImage,
		alternateLinks,
		sections,
	};
}

/** Normalize archive route input fields. */
export function normalizeArchiveInput(rawInput: {
	title: string;
	summary?: string;
	seoTitle?: string;
	metaDescription?: string;
	canonicalUrlOverride?: string;
	robotsDirective?: string;
}) {
	const title = rawInput.title.trim();
	const summary = rawInput.summary?.trim() || null;
	const seoTitle = rawInput.seoTitle?.trim() || title;
	const metaDescription = rawInput.metaDescription?.trim() || summary || "";
	const canonicalUrlOverride = rawInput.canonicalUrlOverride?.trim() || null;
	const robotsDirective = rawInput.robotsDirective?.trim() || null;
	return {
		title,
		summary,
		seoTitle,
		metaDescription,
		canonicalUrlOverride,
		robotsDirective,
	};
}

export function doSaveSystemRoute(
	ctx: AstropressCmsRouteRegistryFactoryInput,
	pathname: string,
	rawInput: {
		title: string;
		summary?: string;
		bodyHtml?: string;
		// audit-boundary: opaque-passthrough -- user CMS route-registry config; narrowed at consumer
		settings?: Record<string, unknown> | null;
		revisionNote?: string;
	},
	actor: RouteActor,
) {
	const normalizedPath = ctx.normalizePath(pathname);
	if (!normalizedPath) {
		return { ok: false as const, error: "A system route path is required." };
	}
	const route = ctx.findSystemRouteForUpdate(normalizedPath);
	if (!route) {
		return {
			ok: false as const,
			error: "The selected system route could not be found.",
		};
	}
	const title = rawInput.title.trim();
	if (!title) {
		return { ok: false as const, error: "A title is required." };
	}
	const summary = rawInput.summary?.trim() || null;
	const bodyHtml = rawInput.bodyHtml?.trim() || null;
	const settings = rawInput.settings ?? null;
	ctx.persistSystemRoute({
		routeId: route.id,
		title,
		summary,
		bodyHtml,
		settingsJson: settings ? JSON.stringify(settings) : null,
		actor,
	});
	ctx.appendSystemRouteRevision({
		routeId: route.id,
		pathname: normalizedPath,
		locale: ctx.localeFromPath(normalizedPath),
		title,
		summary,
		bodyHtml,
		settings,
		renderStrategy: route.renderStrategy,
		revisionNote: rawInput.revisionNote?.trim() || null,
		actor,
	});
	ctx.recordRouteAudit({
		actor,
		action: "system.update",
		summary: `Updated system route ${normalizedPath}.`,
		targetId: normalizedPath,
	});
	return {
		ok: true as const,
		route: {
			path: normalizedPath,
			title,
			summary: summary ?? undefined,
			bodyHtml: bodyHtml ?? undefined,
			settings,
			renderStrategy: route.renderStrategy,
		} satisfies RuntimeSystemRouteRecord,
	};
}

export function doCreateStructuredPageRoute(
	ctx: AstropressCmsRouteRegistryFactoryInput,
	pathname: string,
	rawInput: StructuredPageInput,
	actor: RouteActor,
) {
	const normalizedPath = ctx.normalizePath(pathname);
	if (!normalizedPath || normalizedPath === "/") {
		return { ok: false as const, error: "A public path is required." };
	}
	if (ctx.isRoutePathTaken(normalizedPath)) {
		return { ok: false as const, error: "That public path is already in use." };
	}
	const f = normalizeStructuredInput(rawInput);
	if (!f.title) {
		return { ok: false as const, error: "A title is required." };
	}
	const locale = ctx.localeFromPath(normalizedPath);
	const shared = {
		pathname: normalizedPath,
		locale,
		templateKey: rawInput.templateKey,
		actor,
		...f,
	};
	ctx.insertStructuredRoute(shared);
	const created = ctx.getStructuredPageRoute(normalizedPath);
	const routeId = ctx.findStructuredRouteForUpdate(normalizedPath);
	if (!created || !routeId) {
		return {
			ok: false as const,
			error: "The route page could not be created.",
		};
	}
	ctx.appendStructuredRouteRevision({
		routeId: routeId.id,
		...shared,
		revisionNote: rawInput.revisionNote?.trim() || "Created route page.",
	});
	ctx.recordRouteAudit({
		actor,
		action: "route_page.create",
		summary: `Created route page ${normalizedPath}.`,
		targetId: normalizedPath,
	});
	return { ok: true as const, route: created };
}

export function doSaveStructuredPageRoute(
	ctx: AstropressCmsRouteRegistryFactoryInput,
	pathname: string,
	rawInput: StructuredPageInput,
	actor: RouteActor,
) {
	const normalizedPath = ctx.normalizePath(pathname);
	const route = ctx.findStructuredRouteForUpdate(normalizedPath);
	if (!route) {
		return {
			ok: false as const,
			error: "The selected route page could not be found.",
		};
	}
	const f = normalizeStructuredInput(rawInput);
	if (!f.title) {
		return { ok: false as const, error: "A title is required." };
	}
	const shared = {
		pathname: normalizedPath,
		templateKey: rawInput.templateKey,
		actor,
		...f,
	};
	ctx.persistStructuredRoute({ routeId: route.id, ...shared });
	ctx.appendStructuredRouteRevision({
		routeId: route.id,
		locale: ctx.localeFromPath(normalizedPath),
		...shared,
		revisionNote: rawInput.revisionNote?.trim() || null,
	});
	ctx.recordRouteAudit({
		actor,
		action: "route_page.update",
		summary: `Updated route page ${normalizedPath}.`,
		targetId: normalizedPath,
	});
	const saved = ctx.getStructuredPageRoute(normalizedPath);
	if (!saved) throw new Error(`Route ${normalizedPath} not found after save`);
	return { ok: true as const, route: saved };
}

export function doSaveArchiveRoute(
	ctx: AstropressCmsRouteRegistryFactoryInput,
	pathname: string,
	rawInput: ArchiveRouteInput,
	actor: RouteActor,
) {
	const normalizedPath = ctx.normalizePath(pathname);
	const route = ctx.findArchiveRouteForUpdate(normalizedPath);
	if (!route) {
		return {
			ok: false as const,
			error: "The selected archive route could not be found.",
		};
	}
	const f = normalizeArchiveInput(rawInput);
	if (!f.title) {
		return { ok: false as const, error: "A title is required." };
	}
	ctx.persistArchiveRoute({
		routeId: route.id,
		pathname: normalizedPath,
		actor,
		...f,
	});
	ctx.appendArchiveRouteRevision({
		routeId: route.id,
		pathname: normalizedPath,
		...f,
		revisionNote: rawInput.revisionNote?.trim() || null,
		actor,
	});
	ctx.recordRouteAudit({
		actor,
		action: "archive.update",
		summary: `Updated archive route ${normalizedPath}.`,
		targetId: normalizedPath,
	});
	const savedArchive = ctx.getArchiveRoute(normalizedPath);
	if (!savedArchive) throw new Error(`Archive route ${normalizedPath} not found after save`);
	return { ok: true as const, route: savedArchive };
}

src/contact-endpoint.ts.source:
import type { APIRoute } from "astro";
import {
	EMAIL_RATE_LIMIT_MAX,
	EMAIL_RATE_LIMIT_WINDOW_MS,
	IP_RATE_LIMIT_MAX,
	IP_RATE_LIMIT_WINDOW_MS,
	JSON_HEADERS,
	MESSAGE_MAX_LENGTH,
	NAME_MAX_LENGTH,
	SIMPLE_EMAIL_PATTERN,
} from "./contact-endpoint-data.js";
import { recordD1Audit } from "./d1-audit.js";
import { checkRuntimeRateLimit, submitRuntimeContact } from "./runtime-mutation-store.js";
import { verifyTurnstileToken } from "./turnstile.js";

function getClientIp(request: Request): string {
	return (
		request.headers.get("CF-Connecting-IP") ??
		request.headers.get("X-Forwarded-For")?.split(",")[0].trim() ??
		"unknown"
	);
}

interface ContactFields {
	name?: string;
	email?: string;
	message?: string;
	website?: string;
	turnstileToken?: string;
}

// The wire shape: every field arrives untrusted and is narrowed one-by-one in
// fieldsFromRecord. Form-encoded bodies (Record<string, FormDataEntryValue>)
// are assignable to it too.
interface ContactRequestBody {
	name?: unknown;
	email?: unknown;
	message?: unknown;
	website?: unknown;
	turnstileToken?: unknown;
	"cf-turnstile-response"?: unknown;
}

function fieldsFromRecord(body: ContactRequestBody): ContactFields {
	const str = (v: unknown): string | undefined => (typeof v === "string" ? v.trim() : undefined);
	const rawToken = body["cf-turnstile-response"] ?? body.turnstileToken;
	return {
		name: str(body.name),
		email: str(body.email),
		message: str(body.message),
		website: str(body.website),
		turnstileToken: typeof rawToken === "string" ? rawToken : undefined,
	};
}

function badRequest(error: string): Response {
	return new Response(JSON.stringify({ ok: false, error }), {
		status: 400,
		headers: JSON_HEADERS,
	});
}

/**
 * POST /ap/contact
 *
 * Public contact-form intake (#193). Accepts a JSON or form-encoded body with
 * `name`, `email`, and `message` fields and stores the submission in the
 * runtime contact-submissions store, where it appears under /ap-admin/forms.
 *
 * `website` is a honeypot: real visitors never see or fill it, so a non-empty
 * value marks a bot and the request is acknowledged without being stored.
 *
 * Response:
 *   200 { ok: true }                    — submission stored (or honeypot-dropped)
 *   400 { ok: false, error: "..." }     — missing/invalid fields
 *   403 { ok: false, error: "..." }     — Turnstile challenge failed
 *   429 { ok: false, error: "..." }     — rate limited
 */
export const POST: APIRoute = async ({ request, locals }) => {
	let fields: ContactFields;

	const contentType = request.headers.get("content-type");
	if (contentType?.includes("application/json")) {
		try {
			fields = fieldsFromRecord((await request.json()) as ContactRequestBody);
		} catch {
			return badRequest("Invalid JSON body.");
		}
	} else {
		const formData = await request.formData().catch(() => null);
		if (formData === null) {
			return badRequest("Invalid form body.");
		}
		fields = fieldsFromRecord(Object.fromEntries(formData.entries()));
	}

	const { name, email, message, website, turnstileToken } = fields;

	if (!name || name.length > NAME_MAX_LENGTH) {
		return badRequest("A name is required (200 characters max).");
	}
	if (!email || !SIMPLE_EMAIL_PATTERN.test(email)) {
		return badRequest("A valid email address is required.");
	}
	if (!message || message.length > MESSAGE_MAX_LENGTH) {
		return badRequest("A message is required (5000 characters max).");
	}

	// Honeypot tripped: acknowledge without storing so the bot learns nothing.
	if (website) {
		return new Response(JSON.stringify({ ok: true }), { status: 200, headers: JSON_HEADERS });
	}

	// Per-IP + per-email rate limit before any store write. Both windows must
	// pass; either tripping returns 429.
	const ip = getClientIp(request);
	const ipAllowed = await checkRuntimeRateLimit(
		`contact:ip:${ip}`,
		IP_RATE_LIMIT_MAX,
		IP_RATE_LIMIT_WINDOW_MS,
		locals,
	);
	const emailAllowed = await checkRuntimeRateLimit(
		`contact:email:${email.toLowerCase()}`,
		EMAIL_RATE_LIMIT_MAX,
		EMAIL_RATE_LIMIT_WINDOW_MS,
		locals,
	);
	if (!ipAllowed || !emailAllowed) {
		return new Response(
			JSON.stringify({ ok: false, error: "Too many requests. Please try again later." }),
			{ status: 429, headers: JSON_HEADERS },
		);
	}

	// Require a Turnstile challenge when one is configured. When Turnstile is
	// unconfigured, verifyTurnstileToken resolves ok — the endpoint stays usable
	// in dev/self-host setups that don't run a challenge.
	const challenge = await verifyTurnstileToken({ token: turnstileToken, ipAddress: ip, locals });
	if (!challenge.ok) {
		return new Response(
			JSON.stringify({ ok: false, error: challenge.error ?? "Security challenge failed." }),
			{ status: 403, headers: JSON_HEADERS },
		);
	}

	const result = await submitRuntimeContact(
		{ name, email, message, submittedAt: new Date().toISOString() },
		locals,
	);

	await recordD1Audit(
		locals,
		{ email: "public", role: "editor" as const, name: "Public visitor" },
		"contact.submit",
		"forms",
		result.submission.id,
		`Contact submission from ${email}`,
	).catch(() => {
		// Non-fatal: audit failure must not break the submission response
	});

	return new Response(JSON.stringify({ ok: true }), {
		status: 200,
		headers: JSON_HEADERS,
	});
};

src/content-repository-helpers.ts.source:
import type {
	AstropressContentAssignments,
	AstropressContentOverride,
} from "./content-repository-factory";
import type { ContentRecord } from "./persistence-types";

export function normalizeAssignments(values?: number[]): number[] {
	return [...new Set((values ?? []).filter((entry) => Number.isInteger(entry) && entry > 0))];
}

export function mapContentState(
	record: ContentRecord,
	override: AstropressContentOverride | null | undefined,
	assignments: AstropressContentAssignments,
): ContentRecord {
	return {
		...record,
		title: override?.title ?? record.title,
		status: override?.status ?? record.status,
		scheduledAt: override?.scheduledAt,
		body: override?.body ?? record.body,
		authorIds: assignments.authorIds,
		categoryIds: assignments.categoryIds,
		tagIds: assignments.tagIds,
		seoTitle: override?.seoTitle ?? record.seoTitle,
		metaDescription: override?.metaDescription ?? record.metaDescription,
		excerpt: override?.excerpt ?? record.excerpt,
		ogTitle: override?.ogTitle,
		ogDescription: override?.ogDescription,
		ogImage: override?.ogImage,
		canonicalUrlOverride: override?.canonicalUrlOverride,
		robotsDirective: override?.robotsDirective,
	};
}

src/d1-admin-store.ts.source:
import type { D1DatabaseLike } from "./d1-database";
import { createD1ContentReadPart } from "./d1-store-content";
import { createD1OperationsMutationPart, createD1OperationsReadPart } from "./d1-store-operations";
import {
	createD1AuthorsMutationPart,
	createD1AuthorsReadPart,
	createD1TaxonomiesMutationPart,
	createD1TaxonomiesReadPart,
} from "./d1-store-taxonomies";
import type {
	AuditEvent,
	AuthorRecord,
	CommentRecord,
	CommentStatus,
	ContactSubmission,
	ContentOverride,
	ContentRecord,
	ContentRevision,
	ManagedAdminUser,
	MediaAsset,
	RecordAuditEventInput,
	RedirectRule,
	TaxonomyTerm,
	TestimonialStatus,
	TestimonialSubmission,
	TestimonialSubmissionInput,
} from "./persistence-types";
import type { SiteSettings } from "./site-settings";

// Re-export types so existing consumers don't need to change imports
export type {
	AuditEvent,
	AuthorRecord,
	CommentRecord,
	CommentStatus,
	ContactSubmission,
	ContentOverride,
	ContentRecord,
	ContentRevision,
	ManagedAdminUser,
	MediaAsset,
	RedirectRule,
	SiteSettings,
	TaxonomyTerm,
	TestimonialStatus,
	TestimonialSubmission,
	TestimonialSubmissionInput,
};

export interface D1AdminReadStore {
	audit: {
		getAuditEvents(): Promise<AuditEvent[]>;
		recordAuditEvent(input: RecordAuditEventInput): Promise<void>;
	};
	users: {
		listAdminUsers(): Promise<ManagedAdminUser[]>;
	};
	authors: {
		listAuthors(): Promise<AuthorRecord[]>;
	};
	taxonomies: {
		listCategories(): Promise<TaxonomyTerm[]>;
		listTags(): Promise<TaxonomyTerm[]>;
	};
	redirects: {
		getRedirectRules(): Promise<RedirectRule[]>;
	};
	comments: {
		getComments(): Promise<CommentRecord[]>;
		getApprovedCommentsForRoute(route: string): Promise<CommentRecord[]>;
	};
	// Read-only content surface. Scheduling (schedulePublish / listScheduled /
	// cancelScheduledPublish / runScheduledPublishes) is a write operation and
	// lives in createD1SchedulingPart / the admin scheduling repository — no
	// read-store consumer invokes it through here.
	content: {
		listContentStates(): Promise<ContentRecord[]>;
		getContentState(slug: string): Promise<ContentRecord | null>;
		getContentRevisions(slug: string): Promise<ContentRevision[] | null>;
	};
	submissions: {
		getContactSubmissions(): Promise<ContactSubmission[]>;
		getTestimonials(status?: TestimonialStatus): Promise<TestimonialSubmission[]>;
	};
	translations: {
		getEffectiveTranslationState(route: string, fallback?: string): Promise<string>;
	};
	settings: {
		getSettings(): Promise<SiteSettings>;
	};
	rateLimits: {
		checkRateLimit(key: string, max: number, windowMs: number): Promise<boolean>;
		peekRateLimit(key: string, max: number, windowMs: number): Promise<boolean>;
		recordFailedAttempt(key: string, max: number, windowMs: number): Promise<void>;
	};
	media: {
		listMediaAssets(): Promise<MediaAsset[]>;
	};
}

export interface D1AdminMutationStore {
	authors: {
		createAuthor(input: {
			name: string;
			slug?: string;
			bio?: string;
		}): Promise<{ ok: true } | { ok: false; error: string }>;
		updateAuthor(input: {
			id: number;
			name: string;
			slug?: string;
			bio?: string;
		}): Promise<{ ok: true } | { ok: false; error: string }>;
		deleteAuthor(id: number): Promise<{ ok: true } | { ok: false; error: string }>;
	};
	taxonomies: {
		createCategory(input: {
			name: string;
			slug?: string;
			description?: string;
		}): Promise<{ ok: true } | { ok: false; error: string }>;
		updateCategory(input: {
			id: number;
			name: string;
			slug?: string;
			description?: string;
		}): Promise<{ ok: true } | { ok: false; error: string }>;
		deleteCategory(id: number): Promise<{ ok: true } | { ok: false; error: string }>;
		createTag(input: {
			name: string;
			slug?: string;
			description?: string;
		}): Promise<{ ok: true } | { ok: false; error: string }>;
		updateTag(input: {
			id: number;
			name: string;
			slug?: string;
			description?: string;
		}): Promise<{ ok: true } | { ok: false; error: string }>;
		deleteTag(id: number): Promise<{ ok: true } | { ok: false; error: string }>;
	};
	submissions: {
		submitContact(input: {
			name: string;
			email: string;
			message: string;
			submittedAt: string;
		}): Promise<{
			ok: true;
			submission: ContactSubmission;
		}>;
		submitTestimonial(input: TestimonialSubmissionInput): Promise<{ ok: true; id: string }>;
		moderateTestimonial(
			id: string,
			status: TestimonialStatus,
			actorEmail: string,
		): Promise<{ ok: true } | { ok: false; error: string }>;
	};
	comments: {
		submitPublicComment(input: {
			author: string;
			email: string;
			body: string;
			route: string;
			submittedAt: string;
		}): Promise<{
			ok: true;
			comment: CommentRecord;
		}>;
	};
	rateLimits: {
		checkRateLimit(key: string, max: number, windowMs: number): Promise<boolean>;
		peekRateLimit(key: string, max: number, windowMs: number): Promise<boolean>;
		recordFailedAttempt(key: string, max: number, windowMs: number): Promise<void>;
	};
}

export function createD1AdminReadStore(db: D1DatabaseLike): D1AdminReadStore {
	return {
		...createD1OperationsReadPart(db),
		authors: createD1AuthorsReadPart(db),
		taxonomies: createD1TaxonomiesReadPart(db),
		content: createD1ContentReadPart(db),
	};
}

export function createD1AdminMutationStore(db: D1DatabaseLike): D1AdminMutationStore {
	return {
		authors: createD1AuthorsMutationPart(db),
		taxonomies: createD1TaxonomiesMutationPart(db),
		...createD1OperationsMutationPart(db),
	};
}

src/d1-migrate-ops.ts.source:
import { existsSync, readdirSync, readFileSync } from "node:fs";
import path from "node:path";
import type { D1DatabaseLike } from "./d1-database.js";

export interface D1MigrateInput {
	db: D1DatabaseLike;
	migrationsDir: string;
	dryRun?: boolean;
}

export interface D1MigrateReport {
	migrationsDir: string;
	applied: string[];
	skipped: string[];
	dryRun: boolean;
}

export type D1RollbackStatus = "rolled_back" | "no_rollback_sql" | "no_migrations" | "dry_run";

export interface D1RollbackReport {
	migrationName: string | null;
	status: D1RollbackStatus;
	dryRun: boolean;
}

/**
 * Split a SQL string into individual statements by top-level semicolons.
 * Skips empty segments and SQL comment-only segments.
 */
function splitSqlStatements(sql: string): string[] {
	return sql
		.split(";")
		.map((s) => s.trim())
		.filter((s) => s.length > 0 && !s.startsWith("--") && !/^\/\*/.test(s));
}

/**
 * Ensures the `schema_migrations` table exists in D1 and returns the set of
 * already-applied migration names.
 */
async function bootstrapD1MigrationsTable(db: D1DatabaseLike): Promise<Set<string>> {
	await db.batch([
		db.prepare(`CREATE TABLE IF NOT EXISTS schema_migrations (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL UNIQUE,
      applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
      rollback_sql TEXT
    )`),
	]);

	const result = await db.prepare("SELECT name FROM schema_migrations").all<{ name: string }>();
	return new Set(result.results.map((r) => r.name));
}

/**
 * Applies pending schema migrations to a Cloudflare D1 database.
 *
 * Migration files must be named with a numeric prefix (e.g. `0001_add_column.sql`).
 * They are applied in lexicographic order. Applied migrations are recorded in
 * `schema_migrations` so they are never re-run.
 *
 * Companion `.down.sql` files are read alongside each migration and stored as
 * `rollback_sql` in `schema_migrations`, enabling `rollbackD1LastMigration`.
 *
 * In `dryRun` mode no writes are performed — the function returns what would have
 * been applied.
 */
export async function runD1Migrations(input: D1MigrateInput): Promise<D1MigrateReport> {
	const { db, migrationsDir, dryRun = false } = input;
	const applied: string[] = [];
	const skipped: string[] = [];

	if (!existsSync(migrationsDir)) {
		return { migrationsDir, applied, skipped, dryRun };
	}

	const migrationFiles = readdirSync(migrationsDir)
		.filter((f) => f.endsWith(".sql") && !f.endsWith(".down.sql"))
		.sort();

	if (migrationFiles.length === 0) {
		return { migrationsDir, applied, skipped, dryRun };
	}

	const alreadyApplied = await bootstrapD1MigrationsTable(db);

	for (const file of migrationFiles) {
		if (alreadyApplied.has(file)) {
			skipped.push(file);
			continue;
		}

		const sql = readFileSync(path.join(migrationsDir, file), "utf8");
		const statements = splitSqlStatements(sql);

		const downFilePath = path.join(migrationsDir, file.replace(/\.sql$/, ".down.sql"));
		const rollbackSql = existsSync(downFilePath) ? readFileSync(downFilePath, "utf8") : null;

		if (!dryRun) {
			const batch = [
				...statements.map((stmt) => db.prepare(stmt)),
				db
					.prepare("INSERT INTO schema_migrations (name, rollback_sql) VALUES (?, ?)")
					.bind(file, rollbackSql),
			];
			await db.batch(batch);
		}

		applied.push(file);
	}

	return { migrationsDir, applied, skipped, dryRun };
}

/**
 * Rolls back the most recently applied D1 migration using its stored `rollback_sql`.
 *
 * Executes the rollback SQL as a batch and removes the migration record. If the
 * last migration has no rollback SQL, returns `status: "no_rollback_sql"` without
 * modifying the database.
 */
export async function rollbackD1LastMigration(
	db: D1DatabaseLike,
	{ dryRun = false }: { dryRun?: boolean } = {},
): Promise<D1RollbackReport> {
	let last: { name: string; rollback_sql: string | null } | null = null;

	try {
		last = await db
			.prepare("SELECT name, rollback_sql FROM schema_migrations ORDER BY id DESC LIMIT 1")
			.first<{ name: string; rollback_sql: string | null }>();
	} catch {
		return { migrationName: null, status: "no_migrations", dryRun };
	}

	if (!last) return { migrationName: null, status: "no_migrations", dryRun };
	if (!last.rollback_sql) return { migrationName: last.name, status: "no_rollback_sql", dryRun };

	if (dryRun) return { migrationName: last.name, status: "dry_run", dryRun: true };

	const rollbackStatements = splitSqlStatements(last.rollback_sql);
	await db.batch([
		...rollbackStatements.map((stmt) => db.prepare(stmt)),
		db.prepare("DELETE FROM schema_migrations WHERE name = ?").bind(last.name),
	]);

	return { migrationName: last.name, status: "rolled_back", dryRun: false };
}

