src/integrations/providers/plausible.ts.source:
/**
 * Plausible analytics provider — push-button registration for the
 * analytics domain.
 *
 * verify() runs a GET against `${host}/api/v1/sites/${siteId}` with a
 * Bearer token. Plausible's stats API responds:
 *
 *   200          → token valid for this site → connected
 *   401          → token invalid          → INTEGRATION_AUTH_REJECTED
 *   403          → token valid but lacks scope for this site
 *                   → INTEGRATION_AUTH_REJECTED (provider-level
 *                   defaultErrorCode keeps this as the verify
 *                   default for unknown shapes too)
 *   404          → siteId does not exist  → INTEGRATION_NOT_FOUND
 *   429          → rate-limited           → INTEGRATION_RATE_LIMITED
 *   other ¬ok    → INTEGRATION_VERIFY_FAILED
 *
 * Self-hosted Plausible runs on a different host (we accept any
 * https origin); the SaaS default is documented in the connect form
 * but not encoded here so the schema stays tight.
 */

import { z } from "zod";

import type { IntegrationErrorCode } from "../../integration-error-sanitizer.js";
import { registerAnalytics } from "../domains.js";
import type { RegisteredProvider } from "../registry.js";

export const PLAUSIBLE_FIELDS = z.object({
	host: z.string().url(),
	siteId: z.string().min(1),
	apiKey: z.string().min(1),
});

export type PlausibleFields = z.infer<typeof PLAUSIBLE_FIELDS>;

const SITES_PATH = "/api/v1/sites/";

export class PlausibleVerifyError extends Error {
	constructor(public readonly code: IntegrationErrorCode) {
		super(code);
		this.name = "PlausibleVerifyError";
	}
}

export interface PlausibleVerifyDeps {
	readonly fetch?: typeof fetch;
}

export function buildPlausibleSiteUrl(host: string, siteId: string): string {
	return new URL(SITES_PATH + encodeURIComponent(siteId), host).toString();
}

export function buildPlausibleAuthHeader(apiKey: string): string {
	return `Bearer ${apiKey}`;
}

export async function verifyPlausible(
	fields: PlausibleFields,
	ctx: { signal: AbortSignal },
	deps: PlausibleVerifyDeps = {},
): Promise<void> {
	const fetchImpl = deps.fetch ?? fetch;
	const url = buildPlausibleSiteUrl(fields.host, fields.siteId);
	const auth = buildPlausibleAuthHeader(fields.apiKey);
	const res = await fetchImpl(url, {
		method: "GET",
		headers: { Authorization: auth },
		signal: ctx.signal,
	});
	if (res.status === 401 || res.status === 403) {
		throw new PlausibleVerifyError("INTEGRATION_AUTH_REJECTED");
	}
	if (res.status === 404) {
		throw new PlausibleVerifyError("INTEGRATION_NOT_FOUND");
	}
	if (res.status === 429) {
		throw new PlausibleVerifyError("INTEGRATION_RATE_LIMITED");
	}
	if (!res.ok) {
		throw new PlausibleVerifyError("INTEGRATION_VERIFY_FAILED");
	}
}

export function registerPlausible(): RegisteredProvider<PlausibleFields> {
	return registerAnalytics<PlausibleFields>({
		id: "plausible",
		label: "Plausible",
		fields: PLAUSIBLE_FIELDS,
		verify: verifyPlausible,
		defaultErrorCode: "INTEGRATION_AUTH_REJECTED",
	});
}

src/integrations/resolvers/cdn-purge-res.source:
/**
 * Resolve a CDN-purge configuration from the available sources.
 *
 * The runtime can find CDN-purge config in three places, listed in
 * descending priority:
 *
 *   1. **Registry** — admin connected a Cloudflare provider via the
 *      Phase 3/4 connect flow. Phase 2 unsealed the API token + zone
 *      id from `connected_integrations`.
 *   2. **Process env** — legacy `CLOUDFLARE_API_TOKEN` +
 *      `CLOUDFLARE_ZONE_ID` pair. Both must be set; partial config is
 *      treated as absent.
 *   3. **Static CmsConfig** — legacy generic `cdnPurgeWebhook` URL
 *      that hosts wired in their `registerCms()` call.
 *
 * The resolver is pure: it consumes a snapshot of all three sources
 * and emits a tagged `ResolvedCdnPurge` value (or `{ kind: "none" }`
 * when no source has data). The cache-purge runtime adapter then
 * branches on `kind` to decide what call to make.
 *
 * The architectural intent is single-source-of-truth: the imperative
 * purge function only takes a resolved value, so its tests can pin
 * the runtime branches without re-coupling to env/config plumbing.
 */

export type CdnPurgeSource = "registry" | "env" | "config";

export type ResolvedCdnPurge =
	| {
			readonly kind: "cloudflare";
			readonly apiToken: string;
			readonly zoneId: string;
			readonly source: CdnPurgeSource;
	  }
	| {
			readonly kind: "webhook";
			readonly url: string;
			readonly source: "config";
	  }
	| { readonly kind: "none" };

export interface ResolveCdnPurgeInput {
	readonly registry?: {
		readonly apiToken: string;
		readonly zoneId: string;
	} | null;
	readonly env?: {
		readonly CLOUDFLARE_API_TOKEN?: string;
		readonly CLOUDFLARE_ZONE_ID?: string;
	} | null;
	readonly config?: { readonly cdnPurgeWebhook?: string | null } | null;
}

function nonEmptyString(value: string | undefined | null): value is string {
	return typeof value === "string" && value.length > 0;
}

export function resolveCdnPurge(input: ResolveCdnPurgeInput): ResolvedCdnPurge {
	const registry = input.registry;
	if (registry) {
		return {
			kind: "cloudflare",
			apiToken: registry.apiToken,
			zoneId: registry.zoneId,
			source: "registry",
		};
	}
	const env = input.env ?? {};
	if (nonEmptyString(env.CLOUDFLARE_API_TOKEN) && nonEmptyString(env.CLOUDFLARE_ZONE_ID)) {
		return {
			kind: "cloudflare",
			apiToken: env.CLOUDFLARE_API_TOKEN,
			zoneId: env.CLOUDFLARE_ZONE_ID,
			source: "env",
		};
	}
	const config = input.config ?? {};
	if (nonEmptyString(config.cdnPurgeWebhook)) {
		return {
			kind: "webhook",
			url: config.cdnPurgeWebhook,
			source: "config",
		};
	}
	return { kind: "none" };
}

src/integrations/webhooks/receiver.ts.source:
/**
 * Pure helper that turns a raw inbound webhook request (body bytes +
 * header lookup + provider id) into a typed result the Astro route
 * layer can consume:
 *
 *   - `RECEIVER_UNKNOWN_PROVIDER` — no provider registered under the
 *     URL slug. Route returns 404.
 *   - `RECEIVER_MISSING_SIGNATURE` — provider exists but the inbound
 *     headers carry no signature header. Route returns 401.
 *   - `RECEIVER_INVALID_SIGNATURE` — signature didn't verify under
 *     the secret. Route returns 401.
 *   - `RECEIVER_OK` — signature verified. The result carries the
 *     decoded event name (or `null` if the provider has no
 *     `eventHeader`) so the route can dispatch to a handler.
 *
 * Splitting this from the Astro route keeps the verifier pure — the
 * route just owns body-stream reading, secret loading, and HTTP
 * response construction.
 */

import { verifyInboundWebhookSignature } from "./inbound.js";
import { getInboundWebhookProvider, type InboundWebhookProviderDefinition } from "./registry.js";

export interface InboundWebhookReceiveArgs {
	readonly providerId: string;
	readonly bodyBytes: Uint8Array;
	readonly secret: string;
	readonly headers: (name: string) => string | null;
}

export type InboundWebhookReceiveResult =
	| {
			readonly ok: true;
			readonly provider: InboundWebhookProviderDefinition;
			readonly eventName: string | null;
	  }
	| {
			readonly ok: false;
			readonly code:
				| "RECEIVER_UNKNOWN_PROVIDER"
				| "RECEIVER_MISSING_SIGNATURE"
				| "RECEIVER_INVALID_SIGNATURE";
	  };

export async function receiveInboundWebhook(
	args: InboundWebhookReceiveArgs,
): Promise<InboundWebhookReceiveResult> {
	const provider = getInboundWebhookProvider(args.providerId);
	if (!provider) {
		return { ok: false, code: "RECEIVER_UNKNOWN_PROVIDER" };
	}
	const signature = args.headers(provider.signatureHeader);
	if (signature === null || signature.length === 0) {
		return { ok: false, code: "RECEIVER_MISSING_SIGNATURE" };
	}
	const ok = await verifyInboundWebhookSignature({
		algo: provider.algorithm,
		header: signature,
		body: args.bodyBytes,
		secret: args.secret,
	});
	if (!ok) {
		return { ok: false, code: "RECEIVER_INVALID_SIGNATURE" };
	}
	const eventName = provider.eventHeader ? args.headers(provider.eventHeader) : null;
	return { ok: true, provider, eventName };
}

