import type { LocalMediaDescriptor } from "./local-media-storage";
import { createLocalMediaUpload, deleteLocalMediaUpload } from "./local-media-storage";
import type { MediaRepository, SessionUser } from "./persistence-types";

export type AstropressLocalMediaRepositoryOptions = {
	listMediaAssets: MediaRepository["listMediaAssets"];
	updateMediaAsset: MediaRepository["updateMediaAsset"];
	insertStoredMediaAsset(input: { asset: LocalMediaDescriptor; actor: SessionUser }): void;
	getStoredMediaDeletionCandidate(id: string): { localPath: string } | null | undefined;
	markStoredMediaDeleted(id: string): boolean;
	recordMediaAudit(input: {
		actor: SessionUser;
		action: "media.upload" | "media.delete";
		summary: string;
		targetId: string;
	}): void;
};

export function createAstropressLocalMediaRepository(
	options: AstropressLocalMediaRepositoryOptions,
): MediaRepository {
	return {
		listMediaAssets: (...args) => options.listMediaAssets(...args),
		updateMediaAsset: (...args) => options.updateMediaAsset(...args),
		createMediaAsset(input, actor) {
			const stored = createLocalMediaUpload(input);
			if (!stored.ok) {
				return stored;
			}

			options.insertStoredMediaAsset({ asset: stored.asset, actor });
			options.recordMediaAudit({
				actor,
				action: "media.upload",
				summary: `Uploaded media asset ${stored.asset.storedFilename}.`,
				targetId: stored.asset.id,
			});

			return { ok: true as const, id: stored.asset.id };
		},
		deleteMediaAsset(id, actor) {
			const assetId = id.trim();
			if (!assetId) {
				return { ok: false as const, error: "Media asset id is required." };
			}

			const row = options.getStoredMediaDeletionCandidate(assetId);
			if (!row) {
				return {
					ok: false as const,
					error: "The selected media asset could not be deleted.",
				};
			}

			const deleted = options.markStoredMediaDeleted(assetId);
			if (!deleted) {
				return {
					ok: false as const,
					error: "The selected media asset could not be deleted.",
				};
			}

			deleteLocalMediaUpload(row.localPath);
			options.recordMediaAudit({
				actor,
				action: "media.delete",
				summary: `Deleted media asset ${assetId}.`,
				targetId: assetId,
			});

			return { ok: true as const };
		},
	};
}

src/locale-links.ts.source:
import { getCmsConfig } from "./config";
import { ensureTrailingSlash, stripTrailingSlashes } from "./path-helpers";
import { isPublishedTranslationState } from "./translation-state";

interface TranslationStatusRecord {
	route: string;
	locale: string;
	englishSourceUrl: string;
	translationState: string;
}

interface AlternateLink {
	href: string;
	hreflang: string;
}

export function getAlternateLinksForEnglishRoute(legacyUrl: string) {
	const translationStatus = getCmsConfig().translationStatus as TranslationStatusRecord[];
	const translation = translationStatus.find(
		(entry) =>
			entry.locale === "es" &&
			isPublishedTranslationState(entry.translationState) &&
			entry.englishSourceUrl === legacyUrl,
	);

	if (!translation) {
		return [];
	}

	return [
		{ hreflang: "en", href: canonicalUrlForRoute(legacyUrl) },
		{ hreflang: "es", href: canonicalUrlForRoute(translation.route) },
	];
}

export function canonicalUrlForRoute(route: string) {
	const siteUrl = stripTrailingSlashes(getCmsConfig().siteUrl);
	return `${siteUrl}${route === "/" ? "/" : `${route}/`}`;
}

export function sanitizeCanonicalUrl(value: string | undefined, fallbackRoute: string) {
	if (!value) {
		return canonicalUrlForRoute(fallbackRoute);
	}

	const parsed = new URL(value);
	parsed.search = "";
	parsed.hash = "";

	parsed.pathname = ensureTrailingSlash(parsed.pathname);

	return parsed.toString();
}

function pathFromHref(value: string) {
	try {
		const parsed = new URL(value);
		return `${parsed.pathname}${parsed.search}${parsed.hash}`;
	} catch {
		return value;
	}
}

function isLocalePath(path: string, locale: "en" | "es") {
	if (locale === "es") {
		return path === "/es" || path.startsWith("/es/");
	}

	return !path.startsWith("/es/");
}

export function getLocaleSwitchTargets(input: {
	lang: "en" | "es";
	currentPath?: string;
	alternateLinks?: AlternateLink[];
}) {
	const targets = {
		en: "/en",
		es: "/es",
	};

	if (input.currentPath && isLocalePath(input.currentPath, input.lang)) {
		targets[input.lang] = input.currentPath;
	}

	for (const link of input.alternateLinks ?? []) {
		if (link.hreflang !== "en" && link.hreflang !== "es") {
			continue;
		}

		const path = pathFromHref(link.href);
		targets[link.hreflang] =
			link.hreflang === "en" && path === "/" && input.lang === "es" ? "/en" : path;
	}

	return targets;
}

