import type { AstropressAppHost } from "./app-host-targets";
import type { AstropressDataServices } from "./data-service-targets";
import {
	getAstropressDeploymentMatrixEntry,
	resolveAstropressDeploymentSupportLevel,
} from "./deployment-matrix";
import { createCiFiles, createDeployDoc, createPackageScripts } from "./project-scaffold-ci";
import {
	appHostToDeployTarget,
	baseEnvExample,
	baseLocalEnv,
	buildAbTestingEnvExample,
	buildAnalyticsEnvExample,
	buildApiEnvExample,
	buildDataServiceExample,
	buildDonationsEnvExample,
	buildHeatmapEnvExample,
	deriveLegacyProvider,
} from "./project-scaffold-env";

export type AstropressScaffoldProvider = "sqlite" | "supabase";

export type AstropressAnalyticsProvider = "umami" | "plausible" | "matomo" | "posthog" | "custom";
export type AstropressAbTestingProvider = "growthbook" | "unleash" | "flagsmith" | "custom";
export type AstropressHeatmapProvider = "openreplay" | "posthog" | "custom";

export interface AstropressDonationsProviders {
	giveLively?: boolean;
	liberapay?: boolean;
	pledgeCrypto?: boolean;
}

export interface AstropressProjectScaffoldInput {
	appHost?: AstropressAppHost;
	dataServices?: AstropressDataServices;
	legacyProvider?: AstropressScaffoldProvider;
	analytics?: AstropressAnalyticsProvider;
	abTesting?: AstropressAbTestingProvider;
	heatmap?: AstropressHeatmapProvider;
	enableApi?: boolean;
	donations?: AstropressDonationsProviders;
}

export interface AstropressProjectScaffold {
	provider: AstropressScaffoldProvider;
	appHost: AstropressAppHost;
	dataServices: AstropressDataServices;
	contentServices: AstropressDataServices;
	recommendedDeployTarget: string;
	recommendationRationale: string;
	supportLevel: string;
	localEnv: Record<string, string>;
	envExample: Record<string, string>;
	packageScripts: Record<string, string>;
	ciFiles: Record<string, string>;
	deployDoc: string;
	requiredEnvKeys: string[];
}

function resolveProfile(input: AstropressProjectScaffoldInput | AstropressScaffoldProvider): {
	appHost: AstropressAppHost;
	dataServices: AstropressDataServices;
	provider: AstropressScaffoldProvider;
} {
	if (typeof input === "string") {
		if (input === "supabase")
			return {
				appHost: "vercel",
				dataServices: "supabase",
				provider: "supabase",
			};
		return {
			appHost: "github-pages",
			dataServices: "none",
			provider: "sqlite",
		};
	}

	const dataServices =
		input.dataServices ?? (input.legacyProvider === "supabase" ? "supabase" : "none");
	return {
		appHost:
			input.appHost ??
			(dataServices === "cloudflare"
				? "cloudflare-pages"
				: dataServices === "supabase"
					? "vercel"
					: dataServices === "appwrite" ||
							dataServices === "pocketbase" ||
							dataServices === "nhost" ||
							dataServices === "neon" ||
							dataServices === "turso"
						? "render-web"
						: "github-pages"),
		dataServices,
		provider: input.legacyProvider ?? deriveLegacyProvider(dataServices),
	};
}

/**
 * Generate a complete project scaffold configuration for the given deployment
 * profile, including environment variables, package scripts, CI files, and
 * deployment documentation.
 *
 * @example
 * ```ts
 * import { createAstropressProjectScaffold } from "@astropress-diy/astropress";
 *
 * const scaffold = createAstropressProjectScaffold({ appHost: "vercel", dataServices: "supabase" });
 * // scaffold.localEnv  — object of env vars to write to .env
 * // scaffold.envExample — object of env vars to write to .env.example
 * // scaffold.packageScripts — scripts to merge into package.json
 * ```
 */
export function createAstropressProjectScaffold(
	input: AstropressProjectScaffoldInput | AstropressScaffoldProvider = "sqlite",
): AstropressProjectScaffold {
	const profile = resolveProfile(input);
	const supportLevel = resolveAstropressDeploymentSupportLevel({
		appHost: profile.appHost,
		dataServices: profile.dataServices,
	});
	const matrixEntry = getAstropressDeploymentMatrixEntry({
		appHost: profile.appHost,
		dataServices: profile.dataServices,
	});
	const recommendationRationale =
		matrixEntry?.notes ??
		`Astropress does not yet mark ${profile.appHost} + ${profile.dataServices} as a first-class pair. Keep this combination in preview until you validate the missing runtime and operational pieces yourself.`;
	const requiredEnvKeys = matrixEntry?.requiredEnvKeys ?? [];

	const analyticsOpt = typeof input === "string" ? undefined : input.analytics;
	const abTestingOpt = typeof input === "string" ? undefined : input.abTesting;
	const heatmapOpt = typeof input === "string" ? undefined : input.heatmap;
	const enableApi = typeof input === "string" ? false : (input.enableApi ?? false);
	const donationsOpt = typeof input === "string" ? undefined : input.donations;

	const localEnv: Record<string, string> = baseLocalEnv(
		profile.provider,
		profile.appHost,
		profile.dataServices,
	);
	if (enableApi) localEnv.ASTROPRESS_API_ENABLED = "true";

	return {
		provider: profile.provider,
		appHost: profile.appHost,
		dataServices: profile.dataServices,
		contentServices: profile.dataServices,
		recommendedDeployTarget: appHostToDeployTarget(profile.appHost),
		recommendationRationale,
		supportLevel,
		localEnv,
		envExample: {
			...baseEnvExample(profile.provider, profile.appHost, profile.dataServices),
			...buildDataServiceExample(profile.dataServices),
			...buildAnalyticsEnvExample(analyticsOpt),
			...buildAbTestingEnvExample(abTestingOpt),
			...buildHeatmapEnvExample(heatmapOpt),
			...(enableApi ? buildApiEnvExample() : {}),
			...buildDonationsEnvExample(donationsOpt),
		},
		packageScripts: createPackageScripts(profile.appHost),
		ciFiles: createCiFiles(profile.appHost, requiredEnvKeys, donationsOpt),
		deployDoc: createDeployDoc(
			profile.appHost,
			profile.dataServices,
			supportLevel,
			requiredEnvKeys,
		),
		requiredEnvKeys,
	};
}

src/public-preview-link.ts.source:
export interface PublicPreviewLink {
	/** Same-origin or absolute href to open the published page, or null. */
	href: string | null;
	/** True when the target is expected to resolve; false → render disabled. */
	available: boolean;
}

/**
 * Resolve an admin listing's "Open page/route" preview link (#181).
 *
 * The public site is a *separate origin* from the admin by design — the
 * production admin carries zero admin surface — so a bare same-origin `path`
 * only resolves when the public renderer is actually served by the running app.
 * Three cases:
 *   1. the public renderer is present in this app (scaffold `astro dev`, which
 *      composes createAstropressPublicSiteIntegration) → same-origin path;
 *   2. no renderer here, but a public site is configured at a *different* origin
 *      (production admin) → absolute `siteUrl` + path;
 *   3. otherwise — no renderer here and no distinct public origin (the admin
 *      harness, whose siteUrl is its own origin) → unavailable, so the caller
 *      renders a disabled affordance instead of a link that silently 404s.
 */
export function resolvePublicPreviewLink(params: {
	baseUrl: URL;
	path: string | null | undefined;
	siteUrl: string | null | undefined;
	publicRendererPresent: boolean;
}): PublicPreviewLink {
	const { baseUrl, path, siteUrl, publicRendererPresent } = params;
	if (!path) return { href: null, available: false };
	const rel = path.startsWith("/") ? path : `/${path}`;

	// (1) This app serves the public renderer → a same-origin link resolves.
	if (publicRendererPresent) return { href: rel, available: true };

	// (2) A public site at a genuinely different origin → link there absolutely.
	// URL.parse returns null for unparseable input (no throw); a relative/own-origin
	// siteUrl resolves to baseUrl.origin and is rejected by the origin check below.
	const site = siteUrl ? URL.parse(siteUrl, baseUrl.href) : null;
	if (site && site.origin !== baseUrl.origin) {
		return { href: `${site.origin}${rel}`, available: true };
	}

	// (3) No renderer here and no distinct public origin → honest disabled state.
	return { href: null, available: false };
}

src/rate-limit-repository-factory.ts.source:
import type { RateLimitRepository } from "./persistence-types";

export interface AstropressRateLimitWindowRecord {
	count: number;
	windowStartMs: number;
	windowMs?: number;
}

export interface AstropressRateLimitRepositoryInput {
	now(): number;
	readRateLimitWindow(key: string): AstropressRateLimitWindowRecord | null | undefined;
	resetRateLimitWindow(key: string, now: number, windowMs: number): void;
	incrementRateLimitWindow(key: string): void;
}

export function createAstropressRateLimitRepository(
	input: AstropressRateLimitRepositoryInput,
): RateLimitRepository {
	return {
		checkRateLimit(key, max, windowMs) {
			const now = input.now();
			const row = input.readRateLimitWindow(key);

			if (!row || now - row.windowStartMs > windowMs) {
				input.resetRateLimitWindow(key, now, windowMs);
				return true;
			}

			if (row.count < max) {
				input.incrementRateLimitWindow(key);
				return true;
			}

			return false;
		},
		peekRateLimit(key, max, windowMs) {
			const now = input.now();
			const row = input.readRateLimitWindow(key);

			if (!row || now - row.windowStartMs > windowMs) {
				return true;
			}

			return row.count < max;
		},
		recordFailedAttempt(key, _max, windowMs) {
			const now = input.now();
			const row = input.readRateLimitWindow(key);

			if (!row || now - row.windowStartMs > windowMs) {
				input.resetRateLimitWindow(key, now, windowMs);
				return;
			}

			input.incrementRateLimitWindow(key);
		},
	};
}

src/runtime-actions-access.ts.source:
/**
 * Runtime helpers backing the /ap-admin/access form actions.
 *
 * Each helper dispatches via `withLocalStoreFallback` to either raw async D1
 * SQL (production) or the sync local sqlite store (dev/test). All writes
 * return `ActionResult<T>` so callers can short-circuit through the
 * `withAdminFormAction` redirect-on-failure flow.
 *
 * Last-admin safeguard: any operation that could lower the active admin
 * count must call `assertNotLastActiveAdmin(locals, targetEmail)` first.
 * The helper inspects `admin_users.is_admin AND active` on the target row
 * and refuses when removing them would leave zero break-glass admins.
 */

import { randomUUID } from "node:crypto";
import type {
	Condition,
	Effect,
	RolePolicyRecord,
	RoleRecord,
	UserPolicyRecord,
} from "./access/index";
import { getAdminDb, withLocalStoreFallback } from "./admin-store-dispatch";
import type { D1DatabaseLike } from "./d1-database";
import type { ActionResult } from "./platform-contracts";

interface AssignRoleInput {
	userId: number;
	roleId: string;
	grantedBy?: string;
}

interface DirectGrantInput {
	userId: number;
	effect: Effect;
	action: string;
	condition?: Condition | null;
	priority?: number;
	grantedBy?: string;
}

export async function assignRuntimeUserRole(
	locals: App.Locals | null | undefined,
	input: AssignRoleInput,
): Promise<ActionResult<{ userId: number; roleId: string }>> {
	return withLocalStoreFallback<ActionResult<{ userId: number; roleId: string }>>(
		locals,
		async (db) => {
			await db
				.prepare(
					"INSERT OR IGNORE INTO access_user_roles (user_id, role_id, granted_by) VALUES (?, ?, ?)",
				)
				.bind(input.userId, input.roleId, input.grantedBy ?? null)
				.run();
			return {
				ok: true as const,
				data: { userId: input.userId, roleId: input.roleId },
			};
		},
		async () => ({
			ok: false as const,
			error:
				"Local admin store does not yet expose access role assignment. Wire the access surface to enable role management in dev.",
		}),
	);
}

export async function revokeRuntimeUserRole(
	locals: App.Locals | null | undefined,
	input: { userId: number; roleId: string },
): Promise<ActionResult<{ userId: number; roleId: string }>> {
	return withLocalStoreFallback<ActionResult<{ userId: number; roleId: string }>>(
		locals,
		async (db) => {
			await db
				.prepare("DELETE FROM access_user_roles WHERE user_id = ? AND role_id = ?")
				.bind(input.userId, input.roleId)
				.run();
			return {
				ok: true as const,
				data: { userId: input.userId, roleId: input.roleId },
			};
		},
		async () => ({
			ok: false as const,
			error:
				"Local admin store does not yet expose access role assignment. Wire the access surface to enable role management in dev.",
		}),
	);
}

export async function addRuntimeUserDirectGrant(
	locals: App.Locals | null | undefined,
	input: DirectGrantInput,
): Promise<ActionResult<UserPolicyRecord>> {
	const id = randomUUID();
	const conditionJson = input.condition ? JSON.stringify(input.condition) : null;
	const priority = input.priority ?? 0;
	return withLocalStoreFallback<ActionResult<UserPolicyRecord>>(
		locals,
		async (db) => {
			await db
				.prepare(
					"INSERT INTO access_user_policies (id, user_id, effect, action, condition_json, priority, granted_by) VALUES (?, ?, ?, ?, ?, ?, ?)",
				)
				.bind(
					id,
					input.userId,
					input.effect,
					input.action,
					conditionJson,
					priority,
					input.grantedBy ?? null,
				)
				.run();
			return {
				ok: true as const,
				data: {
					id,
					userId: input.userId,
					effect: input.effect,
					action: input.action,
					condition: input.condition ?? null,
					priority,
					grantedBy: input.grantedBy ?? null,
				},
			};
		},
		async () => ({
			ok: false as const,
			error: "Local admin store does not yet expose direct user grants.",
		}),
	);
}

export async function removeRuntimeUserDirectGrant(
	locals: App.Locals | null | undefined,
	input: { grantId: string },
): Promise<ActionResult<{ id: string }>> {
	return withLocalStoreFallback<ActionResult<{ id: string }>>(
		locals,
		async (db) => {
			await db.prepare("DELETE FROM access_user_policies WHERE id = ?").bind(input.grantId).run();
			return { ok: true as const, data: { id: input.grantId } };
		},
		async () => ({
			ok: false as const,
			error: "Local admin store does not yet expose direct user grants.",
		}),
	);
}

/**
 * Refuses any operation that would leave zero active admins. Inspects the
 * target user's is_admin flag and the system-wide active admin count.
 *
 * Returns ok when the operation is safe (target is not an admin, or there
 * is at least one other active admin).
 */
export async function assertNotLastActiveAdmin(
	locals: App.Locals | null | undefined,
	targetEmail: string,
): Promise<ActionResult<void>> {
	const db = getAdminDb(locals);
	if (!db) {
		return {
			ok: false as const,
			error: "Cannot evaluate the last-admin safeguard without a database binding.",
		};
	}
	return checkLastAdminAgainstD1(db, targetEmail);
}

async function checkLastAdminAgainstD1(
	db: D1DatabaseLike,
	targetEmail: string,
): Promise<ActionResult<void>> {
	const targetRow = await db
		.prepare("SELECT is_admin, active FROM admin_users WHERE email = ? LIMIT 1")
		.bind(targetEmail)
		.first<{ is_admin: number; active: number }>();
	if (!targetRow) return { ok: true as const, data: undefined };
	if (targetRow.is_admin !== 1) return { ok: true as const, data: undefined };

	const countRow = await db
		.prepare("SELECT COUNT(*) AS n FROM admin_users WHERE active = 1 AND is_admin = 1")
		.first<{ n: number }>();
	const count = countRow?.n ?? 0;
	if (count <= 1) {
		return {
			ok: false as const,
			error: "Cannot remove the last active admin — at least one break-glass admin must remain.",
		};
	}
	return { ok: true as const, data: undefined };
}

// ─── Role CRUD ───────────────────────────────────────────────────────────────

export async function createRuntimeRole(
	locals: App.Locals | null | undefined,
	input: { name: string; description?: string },
): Promise<ActionResult<RoleRecord>> {
	const trimmedName = input.name.trim();
	if (!trimmedName) {
		return { ok: false as const, error: "Role name is required." };
	}
	const id = randomUUID();
	const description = (input.description ?? "").trim();
	const now = new Date().toISOString();
	return withLocalStoreFallback<ActionResult<RoleRecord>>(
		locals,
		async (db) => {
			await db
				.prepare(
					"INSERT INTO access_roles (id, name, description, is_system, created_at, updated_at) VALUES (?, ?, ?, 0, ?, ?)",
				)
				.bind(id, trimmedName, description, now, now)
				.run();
			return {
				ok: true as const,
				data: {
					id,
					name: trimmedName,
					description,
					isSystem: false,
					createdAt: now,
					updatedAt: now,
				},
			};
		},
		async () => ({
			ok: false as const,
			error: "Local admin store does not yet expose role management.",
		}),
	);
}

export async function updateRuntimeRole(
	locals: App.Locals | null | undefined,
	input: { id: string; name?: string; description?: string },
): Promise<ActionResult<{ id: string }>> {
	const trimmedName = input.name?.trim();
	const description = input.description?.trim();
	if (trimmedName !== undefined && trimmedName === "") {
		return { ok: false as const, error: "Role name cannot be empty." };
	}
	const now = new Date().toISOString();
	return withLocalStoreFallback<ActionResult<{ id: string }>>(
		locals,
		async (db) => {
			if (trimmedName !== undefined) {
				await db
					.prepare(
						"UPDATE access_roles SET name = ?, updated_at = ? WHERE id = ? AND is_system = 0",
					)
					.bind(trimmedName, now, input.id)
					.run();
			}
			if (description !== undefined) {
				await db
					.prepare("UPDATE access_roles SET description = ?, updated_at = ? WHERE id = ?")
					.bind(description, now, input.id)
					.run();
			}
			return { ok: true as const, data: { id: input.id } };
		},
		async () => ({
			ok: false as const,
			error: "Local admin store does not yet expose role management.",
		}),
	);
}

export async function deleteRuntimeRole(
	locals: App.Locals | null | undefined,
	input: { id: string },
): Promise<ActionResult<{ id: string }>> {
	return withLocalStoreFallback<ActionResult<{ id: string }>>(
		locals,
		async (db) => {
			const row = await db
				.prepare("SELECT is_system FROM access_roles WHERE id = ?")
				.bind(input.id)
				.first<{ is_system: number }>();
			if (row && row.is_system === 1) {
				return {
					ok: false as const,
					error: "System roles cannot be deleted.",
				};
			}
			await db
				.prepare("DELETE FROM access_roles WHERE id = ? AND is_system = 0")
				.bind(input.id)
				.run();
			return { ok: true as const, data: { id: input.id } };
		},
		async () => ({
			ok: false as const,
			error: "Local admin store does not yet expose role management.",
		}),
	);
}

export async function addRuntimeRolePolicy(
	locals: App.Locals | null | undefined,
	input: {
		roleId: string;
		effect: Effect;
		action: string;
		condition?: Condition | null;
		priority?: number;
	},
): Promise<ActionResult<RolePolicyRecord>> {
	const id = randomUUID();
	const conditionJson = input.condition ? JSON.stringify(input.condition) : null;
	const priority = input.priority ?? 0;
	return withLocalStoreFallback<ActionResult<RolePolicyRecord>>(
		locals,
		async (db) => {
			await db
				.prepare(
					"INSERT INTO access_role_policies (id, role_id, effect, action, condition_json, priority) VALUES (?, ?, ?, ?, ?, ?)",
				)
				.bind(id, input.roleId, input.effect, input.action, conditionJson, priority)
				.run();
			return {
				ok: true as const,
				data: {
					id,
					roleId: input.roleId,
					effect: input.effect,
					action: input.action,
					condition: input.condition ?? null,
					priority,
				},
			};
		},
		async () => ({
			ok: false as const,
			error: "Local admin store does not yet expose role management.",
		}),
	);
}

export async function removeRuntimeRolePolicy(
	locals: App.Locals | null | undefined,
	input: { policyId: string },
): Promise<ActionResult<{ id: string }>> {
	return withLocalStoreFallback<ActionResult<{ id: string }>>(
		locals,
		async (db) => {
			await db.prepare("DELETE FROM access_role_policies WHERE id = ?").bind(input.policyId).run();
			return { ok: true as const, data: { id: input.policyId } };
		},
		async () => ({
			ok: false as const,
			error: "Local admin store does not yet expose role management.",
		}),
	);
}

