import { withLocalStoreFallback } from "./admin-store-dispatch";
import { parseUtcTimestamp } from "./auth-repository-helpers";
import { createSessionTokenDigest, verifyPassword } from "./crypto-utils";
import type { D1DatabaseLike } from "./d1-database";
import { loadLocalAdminAuth } from "./local-runtime-modules";
import type { SessionUser } from "./persistence-types";
import {
	getAdminBootstrapConfig,
	getAstropressRootSecretCandidates,
	getCloudflareBindings,
} from "./runtime-env";

export const SESSION_TTL_MS = 12 * 60 * 60 * 1000;

function getD1(locals?: App.Locals | null): D1DatabaseLike | undefined {
	return getCloudflareBindings(locals).DB;
}

async function cleanupExpiredSessions(db: D1DatabaseLike): Promise<void> {
	// Fire-and-forget cleanup; the revoked-row count is not consumed by callers.
	await db
		.prepare(
			`
        UPDATE admin_sessions
        SET revoked_at = CURRENT_TIMESTAMP
        WHERE revoked_at IS NULL
          AND last_active_at < datetime('now', '-12 hours')
      `,
		)
		.run();
}

async function getLiveD1SessionRow(
	db: D1DatabaseLike,
	sessionToken: string | null | undefined,
	locals?: App.Locals | null,
) {
	if (!sessionToken) {
		return null;
	}

	await cleanupExpiredSessions(db);

	const sessionCandidates = [sessionToken];
	for (const sessionSecret of getAstropressRootSecretCandidates(locals)) {
		sessionCandidates.unshift(await createSessionTokenDigest(sessionToken, sessionSecret));
	}

	let row: {
		id: string;
		csrf_token: string;
		last_active_at: string;
		email: string;
		role: SessionUser["role"];
		name: string;
	} | null = null;

	for (const sessionId of sessionCandidates) {
		row = await db
			.prepare(
				`
          SELECT s.id, s.csrf_token, s.last_active_at, u.email,
                 CASE WHEN u.is_admin = 1 THEN 'admin' ELSE 'editor' END AS role,
                 u.name
          FROM admin_sessions s
          JOIN admin_users u ON u.id = s.user_id
          WHERE s.id = ?
            AND s.revoked_at IS NULL
            AND u.active = 1
          LIMIT 1
        `,
			)
			.bind(sessionId)
			.first<{
				id: string;
				csrf_token: string;
				last_active_at: string;
				email: string;
				role: SessionUser["role"];
				name: string;
			}>();

		if (row) {
			break;
		}
	}

	if (!row) {
		return null;
	}

	const lastActiveAt = parseUtcTimestamp(row.last_active_at);
	if (!Number.isFinite(lastActiveAt) || Date.now() - lastActiveAt > SESSION_TTL_MS) {
		await db
			.prepare(
				`
          UPDATE admin_sessions
          SET revoked_at = CURRENT_TIMESTAMP
          WHERE id = ?
            AND revoked_at IS NULL
        `,
			)
			.bind(row.id)
			.run();
		return null;
	}

	await db
		.prepare("UPDATE admin_sessions SET last_active_at = CURRENT_TIMESTAMP WHERE id = ?")
		.bind(row.id)
		.run();
	return row;
}

export async function authenticateRuntimeAdminUser(
	email: string,
	password: string,
	locals?: App.Locals | null,
): Promise<SessionUser | null> {
	const db = getD1(locals);
	if (!db) {
		const localAdminAuth = await loadLocalAdminAuth();
		return localAdminAuth.authenticateAdminUser(email, password);
	}

	const normalizedEmail = email.trim().toLowerCase();
	if (!normalizedEmail || !password) {
		return null;
	}

	const row = await db
		.prepare(
			`
        SELECT email, password_hash,
               CASE WHEN is_admin = 1 THEN 'admin' ELSE 'editor' END AS role,
               name
        FROM admin_users
        WHERE email = ?
          AND active = 1
        LIMIT 1
      `,
		)
		.bind(normalizedEmail)
		.first<{
			email: string;
			password_hash: string;
			role: SessionUser["role"];
			name: string;
		}>();

	if (!row || !(await verifyPassword(password, row.password_hash))) {
		return null;
	}

	return {
		email: row.email,
		role: row.role,
		name: row.name,
	};
}

export async function createRuntimeSession(
	user: SessionUser,
	metadata?: { ipAddress?: string | null; userAgent?: string | null },
	locals?: App.Locals | null,
) {
	return withLocalStoreFallback(
		locals,
		async (db) => {
			const userRow = await db
				.prepare("SELECT id FROM admin_users WHERE email = ? AND active = 1 LIMIT 1")
				.bind(user.email.toLowerCase())
				.first<{ id: number }>();

			if (!userRow) {
				throw new Error(`Cannot create a session for unknown admin user ${user.email}.`);
			}

			const sessionToken = crypto.randomUUID();
			const csrfToken = crypto.randomUUID();
			const sessionSecret = getAdminBootstrapConfig(locals).rootSecret;
			const storedSessionId = sessionSecret
				? await createSessionTokenDigest(sessionToken, sessionSecret)
				: sessionToken;

			await db
				.prepare(
					`
            INSERT INTO admin_sessions (id, user_id, csrf_token, ip_address, user_agent)
            VALUES (?, ?, ?, ?, ?)
          `,
				)
				.bind(
					storedSessionId,
					userRow.id,
					csrfToken,
					metadata?.ipAddress ?? null,
					metadata?.userAgent ?? null,
				)
				.run();

			return sessionToken;
		},
		async (store) => store.createSession(user, metadata),
	);
}

export async function getRuntimeSessionUser(
	sessionToken: string | null | undefined,
	locals?: App.Locals | null,
) {
	return withLocalStoreFallback<(SessionUser & { isAdmin: boolean }) | null>(
		locals,
		async (db) => {
			const row = await getLiveD1SessionRow(db, sessionToken, locals);
			if (!row) {
				return null;
			}
			// `role` is itself derived from admin_users.is_admin in the session
			// query, so the ABAC break-glass signal is exactly role === "admin".
			return { email: row.email, role: row.role, name: row.name, isAdmin: row.role === "admin" };
		},
		async (store) => {
			const user = await store.getSessionUser(sessionToken);
			return user ? { ...user, isAdmin: user.role === "admin" } : null;
		},
	);
}

export async function getRuntimeCsrfToken(
	sessionToken: string | null | undefined,
	locals?: App.Locals | null,
) {
	return withLocalStoreFallback(
		locals,
		async (db) => {
			const row = await getLiveD1SessionRow(db, sessionToken, locals);
			return row?.csrf_token ?? null;
		},
		async (store) => store.getCsrfToken(sessionToken),
	);
}

export async function revokeRuntimeSession(
	sessionToken: string | null | undefined,
	locals?: App.Locals | null,
) {
	return withLocalStoreFallback(
		locals,
		async (db) => {
			if (!sessionToken) {
				return;
			}

			const sessionCandidates = [sessionToken];
			for (const sessionSecret of getAstropressRootSecretCandidates(locals)) {
				sessionCandidates.unshift(await createSessionTokenDigest(sessionToken, sessionSecret));
			}

			for (const sessionId of sessionCandidates) {
				await db
					.prepare(
						`
              UPDATE admin_sessions
              SET revoked_at = CURRENT_TIMESTAMP
              WHERE id = ?
                AND revoked_at IS NULL
            `,
					)
					.bind(sessionId)
					.run();
			}
		},
		async (store) => {
			store.revokeSession(sessionToken);
		},
	);
}

async function recordRuntimeAudit(
	action: string,
	summary: string,
	actor: SessionUser,
	locals?: App.Locals | null,
) {
	return withLocalStoreFallback(
		locals,
		async (db) => {
			await db
				.prepare(
					`
            INSERT INTO audit_events (user_email, action, resource_type, resource_id, summary)
            VALUES (?, ?, 'auth', ?, ?)
          `,
				)
				.bind(actor.email, action, actor.email, summary)
				.run();
		},
		async (store) => {
			if (action === "auth.login") {
				store.recordSuccessfulLogin(actor);
			} else if (action === "auth.logout") {
				store.recordLogout(actor);
			}
		},
	);
}

export async function recordRuntimeSuccessfulLogin(actor: SessionUser, locals?: App.Locals | null) {
	return recordRuntimeAudit("auth.login", `${actor.name} signed in successfully.`, actor, locals);
}

export async function recordRuntimeLogout(actor: SessionUser, locals?: App.Locals | null) {
	return recordRuntimeAudit("auth.logout", `${actor.name} signed out.`, actor, locals);
}

export const _recordRuntimeAuditEvent = recordRuntimeAudit;

