	if (donations.pledgeCrypto) {
		result.PLEDGE_PARTNER_KEY = "[YOUR_PLEDGE_PARTNER_KEY]";
	}
	return result;
}

src/provider-choice.ts.source:
import {
	type AstropressDeploymentSupportLevel,
	getAstropressDeploymentMatrixEntry,
	resolveAstropressDeploymentSupportLevel,
} from "./deployment-matrix";
import type {
	AstropressAppHostEnv,
	AstropressDataServicesEnv,
	AstropressDeployTargetEnv,
} from "./project-env";

export type AstropressProviderOpsComfort = "minimal" | "moderate" | "advanced";
export type AstropressExistingPlatform = "none" | "cloudflare" | "supabase" | "appwrite";

export interface AstropressProviderChoiceInput {
	existingPlatform?: AstropressExistingPlatform;
	wantsHostedAdmin?: boolean;
	wantsStaticMirror?: boolean;
	opsComfort?: AstropressProviderOpsComfort;
}

export interface AstropressProviderChoiceRecommendation {
	appHost: AstropressAppHostEnv;
	dataServices: AstropressDataServicesEnv;
	supportLevel: AstropressDeploymentSupportLevel;
	rationale: string;
	requiredEnvKeys: string[];
	deployTarget: AstropressDeployTargetEnv;
	canonicalProvider: "cloudflare" | "supabase" | "appwrite";
	publicDeployTarget: AstropressDeployTargetEnv;
}

function appHostToDeployTarget(appHost: AstropressAppHostEnv): AstropressDeployTargetEnv {
	return appHost === "cloudflare-pages" ? "cloudflare" : appHost;
}

function finalizeRecommendation(
	appHost: AstropressAppHostEnv,
	dataServices: AstropressDataServicesEnv,
	rationale: string,
): AstropressProviderChoiceRecommendation {
	const entry = getAstropressDeploymentMatrixEntry({ appHost, dataServices });
	const deployTarget = appHostToDeployTarget(appHost);
	return {
		appHost,
		dataServices,
		supportLevel: resolveAstropressDeploymentSupportLevel({
			appHost,
			dataServices,
		}),
		rationale: entry?.notes ? `${rationale} ${entry.notes}` : rationale,
		requiredEnvKeys: entry?.requiredEnvKeys ?? [],
		deployTarget,
		canonicalProvider:
			dataServices === "cloudflare" || dataServices === "supabase" || dataServices === "appwrite"
				? dataServices
				: "cloudflare",
		publicDeployTarget: deployTarget,
	};
}

/**
 * Analyze user preferences and return a recommended provider combination with
 * rationale and required environment keys.
 *
 * @example
 * ```ts
 * import { recommendAstropressProvider } from "@astropress-diy/astropress";
 *
 * const rec = recommendAstropressProvider({ existingPlatform: "supabase" });
 * console.log(rec.appHost);       // "vercel"
 * console.log(rec.dataServices);  // "supabase"
 * console.log(rec.supportLevel);  // "supported"
 * ```
 */
export function recommendAstropressProvider(
	input: AstropressProviderChoiceInput = {},
): AstropressProviderChoiceRecommendation {
	const existingPlatform = input.existingPlatform ?? "none";
	const wantsHostedAdmin = input.wantsHostedAdmin ?? true;
	const wantsStaticMirror = input.wantsStaticMirror ?? false;
	const opsComfort = input.opsComfort ?? "minimal";

	if (existingPlatform === "supabase") {
		return finalizeRecommendation(
			wantsStaticMirror ? "github-pages" : "vercel",
			"supabase",
			"Supabase is already the content-services platform, so Astropress should keep Supabase for data, auth, storage, and the Astropress service API while using a separate Astro app host.",
		);
	}

	if (existingPlatform === "appwrite") {
		return finalizeRecommendation(
			wantsStaticMirror ? "github-pages" : "render-web",
			"appwrite",
			"Appwrite is already the content-services platform, so Astropress should keep Appwrite for data, auth, media, and the Astropress service API while choosing a separate Astro app host.",
		);
	}

	if (existingPlatform === "cloudflare" || opsComfort === "advanced") {
		return finalizeRecommendation(
			wantsStaticMirror ? "github-pages" : "cloudflare-pages",
			"cloudflare",
			"Cloudflare is the best fit for teams already comfortable with its edge/runtime model and wanting one provider to cover app hosting plus content services.",
		);
	}

	if (!wantsHostedAdmin && wantsStaticMirror) {
		return finalizeRecommendation(
			"github-pages",
			"none",
			"GitHub Pages is the clearest low-ops choice when the project only needs static Astro output and no hosted Astropress admin backend.",
		);
	}

	if (!wantsHostedAdmin) {
		return finalizeRecommendation(
			"github-pages",
			"none",
			"A static Astro deployment keeps the public site simple when hosted Astropress services are not required.",
		);
	}

	return finalizeRecommendation(
		"cloudflare-pages",
		"cloudflare",
		"Cloudflare is still the default recommendation for most Astropress users because it keeps the app host and the content-services layer aligned under one operational model.",
	);
}

src/security-headers.ts.source:
export type AstropressSecurityArea = "admin" | "auth" | "public" | "api";

export interface AstropressSecurityHeadersOptions {
	area?: AstropressSecurityArea;
	allowInlineStyles?: boolean;
	frameAncestors?: "'none'" | "'self'";
	forceHsts?: boolean;
	reportUri?: string;
}

function parseOrigin(value: string): URL | null {
	try {
		return new URL(value);
	} catch {
		return null;
	}
}

function buildContentSecurityPolicy(options: Required<AstropressSecurityHeadersOptions>) {
	const styleSource = options.allowInlineStyles
		? "style-src 'self' 'unsafe-inline'"
		: "style-src 'self'";
	const objectSource = options.area === "public" ? "object-src 'self'" : "object-src 'none'";
	const formAction = options.area === "public" ? "form-action 'self' https:" : "form-action 'self'";

	const directives = [
		"default-src 'self'",
		"base-uri 'self'",
		`frame-ancestors ${options.frameAncestors}`,
		formAction,
		"img-src 'self' data: https:",
		"font-src 'self' data: https:",
		"connect-src 'self' https:",
		"media-src 'self' data: https:",
		"script-src 'self' https://challenges.cloudflare.com",
		styleSource,
		objectSource,
		"frame-src 'self' https://challenges.cloudflare.com",
		"worker-src 'self' blob:",
		"manifest-src 'self'",
		"upgrade-insecure-requests",
	];

	if (options.reportUri) {
		directives.push(`report-uri ${options.reportUri}`, "report-to csp-endpoint");
	}

	return directives.join("; ");
}

export function createAstropressSecurityHeaders(
	options: AstropressSecurityHeadersOptions = {},
): Headers {
	const resolved: Required<AstropressSecurityHeadersOptions> = {
		area: options.area ?? "public",
		allowInlineStyles: options.allowInlineStyles ?? false,
		frameAncestors: options.frameAncestors ?? "'none'",
		forceHsts: options.forceHsts ?? false,
		reportUri: options.reportUri ?? "",
	};

	const headers = new Headers();
	headers.set("Content-Security-Policy", buildContentSecurityPolicy(resolved));
	headers.set("Referrer-Policy", "strict-origin-when-cross-origin");
	headers.set("X-Content-Type-Options", "nosniff");
	headers.set("X-Frame-Options", resolved.frameAncestors === "'none'" ? "DENY" : "SAMEORIGIN");
	headers.set("Permissions-Policy", "camera=(), geolocation=(), microphone=(), payment=(), usb=()");
	headers.set("Cross-Origin-Opener-Policy", "same-origin");

	if (resolved.area === "admin" || resolved.area === "api" || resolved.area === "auth") {
		headers.set("Cross-Origin-Resource-Policy", "same-site");
	}

	if (resolved.forceHsts) {
		headers.set("Strict-Transport-Security", "max-age=31536000; includeSubDomains");
	}

	if (resolved.reportUri) {
		headers.set(
			"Report-To",
			JSON.stringify({
				group: "csp-endpoint",
				max_age: 86400,
				endpoints: [{ url: resolved.reportUri }],
			}),
		);
	}

	return headers;
}

export function applyCacheHeaders(
	headers: Headers,
	area: AstropressSecurityArea = "public",
	publicCacheTtl?: number,
): void {
	if (area === "public") {
		// Public content: short browser cache, longer CDN cache, stale-while-revalidate for background refresh
		const browserTtl = publicCacheTtl ?? 300;
		const cdnTtl = publicCacheTtl != null ? publicCacheTtl * 12 : 3600;
		headers.set(
			"Cache-Control",
			`public, max-age=${browserTtl}, s-maxage=${cdnTtl}, stale-while-revalidate=86400`,
		);
	} else {
		// Admin, auth, and API responses must never be cached
		headers.set("Cache-Control", "private, no-store");
	}
}

export function applyAstropressSecurityHeaders(
	target: Headers,
	options: AstropressSecurityHeadersOptions = {},
): Headers {
	const generated = createAstropressSecurityHeaders(options);
	generated.forEach((value, key) => {
		target.set(key, value);
	});
	applyCacheHeaders(target, options.area ?? "public");
	return target;
}

export function createAstropressSecureRedirect(
	location: string,
	status = 302,
	options: AstropressSecurityHeadersOptions = {},
): Response {
	const headers = createAstropressSecurityHeaders({ area: "api", ...options });
	headers.set("Location", location);
	return new Response(null, { status, headers });
}

export function isTrustedRequestOrigin(request: Request): boolean {
	let requestOrigin: string;
	try {
		requestOrigin = new URL(request.url).origin;
	} catch {
		return false;
	}

	const rawOrigin = request.headers.get("origin");
	if (rawOrigin !== null) {
		const origin = parseOrigin(rawOrigin);
		if (origin === null) return false;
		return origin.origin === requestOrigin;
	}

	const rawReferer = request.headers.get("referer");
	if (rawReferer !== null) {
		const referer = parseOrigin(rawReferer);
		if (referer === null) return false;
		return referer.origin === requestOrigin;
	}

	return true;
}

export function isTrustedStrictRequestOrigin(request: Request): boolean {
	let requestOrigin: string;
	try {
		requestOrigin = new URL(request.url).origin;
	} catch {
		return false;
	}

	const origin = parseOrigin(request.headers.get("origin") ?? "");
	if (request.headers.get("origin") !== null) {
		if (!origin) return false;
		return origin.origin === requestOrigin;
	}

	const referer = parseOrigin(request.headers.get("referer") ?? "");
	if (request.headers.get("referer") !== null) {
		if (!referer) return false;
		return referer.origin === requestOrigin;
	}

	return false;
}

src/services-config.ts.source:
/**
 * Registry for optional headless service integrations (CMS, commerce, community, email).
 * Services registered here appear in the /ap-admin/services tab with an embedded iframe.
 *
 * @example
 * ```ts
 * import { registerAstropressService } from "@astropress-diy/astropress/services-config";
 *
 * registerAstropressService({
 *   provider: "cms",
 *   label: "Payload CMS",
 *   description: "Open-source TypeScript CMS — MIT licensed.",
 *   proxyTarget: "http://localhost:3000",
 *   adminPath: "/ap-admin/services/cms",
 * });
 * ```
 */

export type ServiceProvider = "cms" | "shop" | "community" | "email" | "testimonials";

export type AstropressServiceConfig = {
	/** Identifier for this service category. One of the four supported providers. */
	provider: ServiceProvider;
	/** Human-readable label shown in the Services tab. */
	label: string;
	/** Short description shown on the service card. */
	description: string;
	/**
	 * Dev server proxy target (e.g. "http://localhost:3000").
	 * The Vite / nginx proxy routes /ap-admin/services/<provider>/ → proxyTarget/.
	 */
	proxyTarget: string;
	/** Admin path for this service within ap-admin, e.g. /ap-admin/services/cms */
	adminPath: string;
};

const registeredServices: AstropressServiceConfig[] = [];

/**
 * Register (or replace) an optional service integration.
 * Call this in your Astro config / integration setup file.
 */
export function registerAstropressService(config: AstropressServiceConfig): void {
	const existing = registeredServices.findIndex((s) => s.provider === config.provider);
	if (existing >= 0) {
		registeredServices[existing] = config;
	} else {
		registeredServices.push(config);
	}
}

/** Return all currently registered services in registration order. */
export function getAstropressServices(): AstropressServiceConfig[] {
	return [...registeredServices];
}

/** Look up a single service by provider key. Returns undefined if not registered. */
export function getAstropressService(
	provider: ServiceProvider,
): AstropressServiceConfig | undefined {
	return registeredServices.find((s) => s.provider === provider);
}

/** Remove a registered service (useful in tests). */
export function unregisterAstropressService(provider: ServiceProvider): void {
	const idx = registeredServices.findIndex((s) => s.provider === provider);
	if (idx >= 0) registeredServices.splice(idx, 1);
}

/** Remove all registered services (useful in tests). */
export function clearAstropressServices(): void {
	registeredServices.length = 0;
}

/**
 * Register the testimonials service if a URL is configured.
 * When `config.url` is set, the tool's admin panel is embedded as an iframe
 * in /ap-admin/services/testimonials. Has no effect when `url` is absent.
 */
export function registerTestimonialsServiceIfConfigured(config: {
	type: string;
	url?: string;
	label?: string;
}): void {
	if (!config.url) return;
	registerAstropressService({
		provider: "testimonials",
		label: config.label ?? (config.type === "typebot" ? "Typebot" : "Formbricks"),
		description:
			config.type === "typebot"
				? "Conversational testimonial and referral capture flows."
				: "Survey and testimonial collection with referral support.",
		proxyTarget: config.url,
		adminPath: "/ap-admin/services/testimonials",
	});
}

