import { createAstropressCommentRepository } from "../comment-repository-factory";
import type { Actor } from "../persistence-types";
import { createAstropressRedirectRepository } from "../redirect-repository-factory";
import { createAstropressSettingsRepository } from "../settings-repository-factory";
import { defaultSiteSettings, type SiteSettings } from "../site-settings";
import { createAstropressTranslationRepository } from "../translation-repository-factory";
import { recordAudit } from "./audit-log";
import {
	SQL_GET_COMMENT_ROUTE,
	SQL_GET_REDIRECT,
	SQL_INSERT_COMMENT,
	SQL_READ_TRANSLATION,
	SQL_SOFT_DELETE_REDIRECT,
	SQL_UPDATE_COMMENT_STATUS,
	SQL_UPSERT_REDIRECT,
	SQL_UPSERT_SETTINGS,
	SQL_UPSERT_TRANSLATION,
} from "./settings-data.js";
import { type AstropressSqliteDatabaseLike, normalizePath } from "./utils";

type CommentStatus = "pending" | "approved" | "rejected";
type CommentPolicy = "legacy-readonly" | "disabled" | "open-moderated";

function queryRedirectRules(getDb: () => AstropressSqliteDatabaseLike) {
	const rows = getDb()
		.prepare(
			`
        SELECT source_path, target_path, status_code
        FROM redirect_rules
        WHERE deleted_at IS NULL
        ORDER BY source_path ASC
      `,
		)
		.all() as Array<{
		source_path: string;
		target_path: string;
		status_code: 301 | 302;
	}>;

	return rows.map((row) => ({
		sourcePath: row.source_path,
		targetPath: row.target_path,
		statusCode: row.status_code,
	}));
}

function queryComments(getDb: () => AstropressSqliteDatabaseLike) {
	const rows = getDb()
		.prepare(
			`
        SELECT id, author, email, body, route, status, policy, submitted_at
        FROM comments
        ORDER BY
          CASE status WHEN 'pending' THEN 0 WHEN 'approved' THEN 1 ELSE 2 END,
          datetime(submitted_at) DESC,
          id DESC
      `,
		)
		.all() as Array<{
		id: string;
		author: string;
		email: string | null;
		body: string | null;
		route: string;
		status: CommentStatus;
		policy: CommentPolicy;
		submitted_at: string;
	}>;

	return rows.map((row) => ({
		id: row.id,
		author: row.author,
		email: row.email ?? undefined,
		body: row.body ?? undefined,
		route: row.route,
		status: row.status,
		policy: row.policy,
		submittedAt: row.submitted_at,
	}));
}

function insertComment(
	getDb: () => AstropressSqliteDatabaseLike,
	comment: {
		id: string;
		author: string;
		email?: string;
		body?: string;
		route: string;
		status: CommentStatus;
		policy: CommentPolicy;
		submittedAt?: string;
	},
) {
	const submittedAt = comment.submittedAt ?? new Date().toISOString();
	getDb()
		.prepare(SQL_INSERT_COMMENT)
		.run(
			comment.id,
			comment.author,
			comment.email ?? null,
			comment.body ?? null,
			comment.route,
			comment.status,
			comment.policy,
			submittedAt,
		);
	return submittedAt;
}

export function createSqliteSettingsStore(getDb: () => AstropressSqliteDatabaseLike) {
	function getRedirectRules() {
		return queryRedirectRules(getDb);
	}

	const sqliteRedirectRepository = createAstropressRedirectRepository({
		getRedirectRules,
		normalizePath,
		getExistingRedirect(sourcePath: string) {
			const existing = getDb().prepare(SQL_GET_REDIRECT).get(sourcePath) as
				| { deleted_at: string | null }
				| undefined;
			return existing ? { deletedAt: existing.deleted_at } : null;
		},
		upsertRedirect({
			sourcePath,
			targetPath,
			statusCode,
			actor,
		}: {
			sourcePath: string;
			targetPath: string;
			statusCode: 301 | 302;
			actor: Actor;
		}) {
			getDb().prepare(SQL_UPSERT_REDIRECT).run(sourcePath, targetPath, statusCode, actor.email);
		},
		markRedirectDeleted(sourcePath: string) {
			return getDb().prepare(SQL_SOFT_DELETE_REDIRECT).run(sourcePath).changes > 0;
		},
		recordRedirectAudit({
			actor,
			action,
			summary,
			targetId,
		}: {
			actor: Actor;
			action: string;
			summary: string;
			targetId: string;
		}) {
			recordAudit(getDb(), actor, action, summary, "redirect", targetId);
		},
	});

	function getComments() {
		return queryComments(getDb);
	}

	const sqliteCommentRepository = createAstropressCommentRepository({
		getComments,
		getCommentRoute(commentId: string) {
			const comment = getDb().prepare(SQL_GET_COMMENT_ROUTE).get(commentId) as
				| { route: string }
				| undefined;
			return comment?.route ?? null;
		},
		updateCommentStatus(commentId: string, nextStatus: CommentStatus) {
			return getDb().prepare(SQL_UPDATE_COMMENT_STATUS).run(nextStatus, commentId).changes > 0;
		},
		insertPublicComment(comment: {
			id: string;
			author: string;
			email?: string;
			body?: string;
			route: string;
			status: CommentStatus;
			policy: CommentPolicy;
			submittedAt?: string;
		}) {
			return insertComment(getDb, comment);
		},
		recordCommentAudit({
			actor,
			action,
			summary,
			targetId,
		}: {
			actor: Actor;
			action: string;
			summary: string;
			targetId: string;
		}) {
			recordAudit(getDb(), actor, action, summary, "comment", targetId);
		},
	});

	const sqliteTranslationRepository = createAstropressTranslationRepository({
		readTranslationState(route: string) {
			const row = getDb().prepare(SQL_READ_TRANSLATION).get(route) as { state: string } | undefined;
			return row?.state;
		},
		persistTranslationState(route: string, state: string, actor: Actor) {
			getDb().prepare(SQL_UPSERT_TRANSLATION).run(route, state, actor.email);
		},
		recordTranslationAudit({
			actor,
			route,
			state,
		}: {
			actor: Actor;
			route: string;
			state: string;
		}) {
			recordAudit(
				getDb(),
				actor,
				"translation.update",
				`Updated translation state for ${route} to ${state}.`,
				"content",
				route,
			);
		},
	});

	function getSettings(): SiteSettings {
		const row = getDb()
			.prepare(
				`
          SELECT site_title, site_tagline, donation_url, newsletter_enabled, comments_default_policy, admin_slug
          FROM site_settings
          WHERE id = 1
          LIMIT 1
        `,
			)
			.get() as
			| {
					site_title: string;
					site_tagline: string;
					donation_url: string;
					newsletter_enabled: number;
					comments_default_policy: SiteSettings["commentsDefaultPolicy"];
					admin_slug: string;
			  }
			| undefined;

		if (!row) {
			return { ...defaultSiteSettings };
		}

		return {
			siteTitle: row.site_title,
			siteTagline: row.site_tagline,
			donationUrl: row.donation_url,
			newsletterEnabled: row.newsletter_enabled === 1,
			commentsDefaultPolicy: row.comments_default_policy,
			adminSlug: row.admin_slug ?? "ap-admin",
		};
	}

	const sqliteSettingsRepository = createAstropressSettingsRepository({
		getSettings,
		persistSettings(updated: SiteSettings, actor: Actor) {
			getDb()
				.prepare(SQL_UPSERT_SETTINGS)
				.run(
					1,
					updated.siteTitle,
					updated.siteTagline,
					updated.donationUrl,
					updated.newsletterEnabled ? 1 : 0,
					updated.commentsDefaultPolicy,
					updated.adminSlug,
					actor.email,
				);
		},
		recordSettingsAudit(actor: Actor) {
			recordAudit(
				getDb(),
				actor,
				"settings.update",
				"Updated site settings.",
				"auth",
				"site-settings",
			);
		},
	});

	return {
		sqliteRedirectRepository,
		sqliteCommentRepository,
		sqliteTranslationRepository,
		sqliteSettingsRepository,
	};
}

src/sqlite-schema-compat-data.ts.source:
// stryker-disable-file: data-only — pure SQL DDL string constants for legacy schema
// compatibility migrations. The conditional dispatch (`opts.hasX ? "..." : "..."`) lives
// in sqlite-schema-compat.ts and is mutation-tested there. The strings here are arbitrary
// SQL bytes — pinning every keystroke is not a useful exercise; integration tests in
// disaster-recovery / upgrade-path-e2e exercise the whole migration end-to-end.

export const REBUILD_OVERRIDES_HEAD = `
    PRAGMA foreign_keys = OFF;

    CREATE TABLE IF NOT EXISTS content_overrides__migrated (
      slug TEXT PRIMARY KEY,
      title TEXT NOT NULL,
      status TEXT NOT NULL CHECK(status IN ('draft', 'review', 'published', 'archived')),
      scheduled_at TEXT,
      body TEXT,
      seo_title TEXT,
      meta_description TEXT,
      excerpt TEXT,
      og_title TEXT,
      og_description TEXT,
      og_image TEXT,
      canonical_url_override TEXT,
      robots_directive TEXT,
      metadata TEXT,
      updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
      updated_by TEXT NOT NULL
    );

    INSERT INTO content_overrides__migrated (
      slug, title, status, scheduled_at, body, seo_title, meta_description, excerpt, og_title,
      og_description, og_image, canonical_url_override, robots_directive, metadata, updated_at, updated_by
    )
    SELECT
      slug,
      title,
      CASE
        WHEN status IN ('draft', 'review', 'published', 'archived') THEN status
        ELSE 'draft'
      END,
      `;

export const REBUILD_OVERRIDES_TAIL = `,
      body,
      seo_title,
      meta_description,
      excerpt,
      og_title,
      og_description,
      og_image,
      canonical_url_override,
      robots_directive,
      NULL,
      updated_at,
      updated_by
    FROM content_overrides;

    DROP TABLE content_overrides;
    ALTER TABLE content_overrides__migrated RENAME TO content_overrides;
    CREATE INDEX IF NOT EXISTS idx_content_overrides_updated_at ON content_overrides(updated_at DESC);

    CREATE TABLE IF NOT EXISTS content_revisions__migrated (
      id TEXT PRIMARY KEY,
      slug TEXT NOT NULL,
      source TEXT NOT NULL CHECK(source IN ('imported', 'reviewed')),
      title TEXT NOT NULL,
      status TEXT NOT NULL CHECK(status IN ('draft', 'review', 'published', 'archived')),
      scheduled_at TEXT,
      body TEXT,
      seo_title TEXT,
      meta_description TEXT,
      excerpt TEXT,
      og_title TEXT,
      og_description TEXT,
      og_image TEXT,
      author_ids TEXT,
      category_ids TEXT,
      tag_ids TEXT,
      canonical_url_override TEXT,
      robots_directive TEXT,
      revision_note TEXT,
      created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
      created_by TEXT,
      FOREIGN KEY(slug) REFERENCES content_overrides(slug) ON DELETE CASCADE
    );

    INSERT INTO content_revisions__migrated (
      id, slug, source, title, status, scheduled_at, body, seo_title, meta_description, excerpt,
      og_title, og_description, og_image, author_ids, category_ids, tag_ids,
      canonical_url_override, robots_directive, revision_note, created_at, created_by
    )
    SELECT
      id,
      slug,
      source,
      title,
      CASE
        WHEN status IN ('draft', 'review', 'published', 'archived') THEN status
        ELSE 'draft'
      END,
      `;

export const REBUILD_REVISIONS_MID_BEFORE_AUTHORS = `,
      body,
      seo_title,
      meta_description,
      excerpt,
      og_title,
      og_description,
      og_image,
      `;

export const REBUILD_REVISIONS_MID_AFTER_TAGS = `,
      canonical_url_override,
      robots_directive,
      `;

export const REBUILD_REVISIONS_FOOTER = `,
      created_at,
      created_by
    FROM content_revisions;

    DROP TABLE content_revisions;
    ALTER TABLE content_revisions__migrated RENAME TO content_revisions;
    CREATE INDEX IF NOT EXISTS idx_content_revisions_slug ON content_revisions(slug);
    CREATE INDEX IF NOT EXISTS idx_content_revisions_created_at ON content_revisions(created_at DESC);

    PRAGMA foreign_keys = ON;
  `;

export const FTS5_INDEX_DDL = `
    CREATE VIRTUAL TABLE content_fts USING fts5(
      slug UNINDEXED, title, body,
      content='content_overrides', content_rowid='rowid'
    );

    INSERT INTO content_fts(rowid, slug, title, body)
    SELECT rowid, slug, title, COALESCE(body, '') FROM content_overrides;

    CREATE TRIGGER content_fts_ai AFTER INSERT ON content_overrides BEGIN
      INSERT INTO content_fts(rowid, slug, title, body)
      VALUES (new.rowid, new.slug, new.title, COALESCE(new.body, ''));
    END;

    CREATE TRIGGER content_fts_au AFTER UPDATE ON content_overrides BEGIN
      INSERT INTO content_fts(content_fts, rowid, slug, title, body)
      VALUES ('delete', old.rowid, old.slug, old.title, COALESCE(old.body, ''));
      INSERT INTO content_fts(rowid, slug, title, body)
      VALUES (new.rowid, new.slug, new.title, COALESCE(new.body, ''));
    END;

    CREATE TRIGGER content_fts_ad AFTER DELETE ON content_overrides BEGIN
      INSERT INTO content_fts(content_fts, rowid, slug, title, body)
      VALUES ('delete', old.rowid, old.slug, old.title, COALESCE(old.body, ''));
    END;
  `;

export const CONTENT_LOCKS_DDL = `
      CREATE TABLE IF NOT EXISTS content_locks (
        slug TEXT PRIMARY KEY,
        locked_by_email TEXT NOT NULL,
        locked_by_name TEXT NOT NULL,
        lock_token TEXT NOT NULL,
        expires_at TEXT NOT NULL,
        acquired_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
      );
      CREATE INDEX IF NOT EXISTS idx_content_locks_expires_at ON content_locks(expires_at);
    `;

export const ADMIN_USERS_DROP_ROLE_HEAD = `
      PRAGMA foreign_keys = OFF;
      CREATE TABLE admin_users__migrated (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        email TEXT NOT NULL UNIQUE,
        password_hash TEXT NOT NULL,
        is_admin INTEGER NOT NULL DEFAULT 0,
        name TEXT NOT NULL,
        active INTEGER NOT NULL DEFAULT 1,
        created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
      );
