describe("createRuntimeContentRecord — error strings, audit, fallbacks", () => {
	it("returns the documented 'Title, slug, and meta description are required.' error", async () => {
		const result = await createRuntimeContentRecord(
			{
				title: "   ",
				slug: "empty",
				status: "draft",
