import { afterEach, describe, expect, it, vi } from "vitest";

import { createSessionTokenDigest, hashPassword } from "../src/crypto-utils.js";
import {
	authenticateRuntimeAdminUser,
	createRuntimeSession,
	getRuntimeCsrfToken,
	getRuntimeSessionUser,
	recordRuntimeLogout,
	recordRuntimeSuccessfulLogin,
	revokeRuntimeSession,
	SESSION_TTL_MS,
} from "../src/runtime-admin-auth.js";
import { makeDb } from "./helpers/make-db.js";
import { SqliteBackedD1Database } from "./helpers/provider-test-fixtures.js";

function makeLocals() {
	const db = makeDb();
	const d1 = new SqliteBackedD1Database(db);
	const locals = {
		runtime: {
			env: {
				DB: d1,
			},
		},
	} as App.Locals;

	return { db, locals };
}

describe("runtime admin auth secret rotation", () => {
	afterEach(() => {
		vi.unstubAllEnvs();
	});

	it("signs newly created sessions with the current SESSION_SECRET only", async () => {
		vi.stubEnv("SESSION_SECRET", "current-session-secret");
		vi.stubEnv("SESSION_SECRET_PREV", "previous-session-secret");

		const { db, locals } = makeLocals();
		db.prepare(
			"INSERT INTO admin_users (email, password_hash, name, active, is_admin) VALUES (?1, ?3, ?4, 1, CASE WHEN ?2 = 'admin' THEN 1 ELSE 0 END)",
		).run("admin@example.com", "admin", await hashPassword("correctpass"), "Admin User");

		const sessionToken = await createRuntimeSession(
			{ email: "admin@example.com", role: "admin", name: "Admin User" },
			undefined,
			locals,
		);

		const stored = db.prepare("SELECT id FROM admin_sessions LIMIT 1").get() as { id: string };
		expect(stored.id).toBe(await createSessionTokenDigest(sessionToken, "current-session-secret"));
		expect(stored.id).not.toBe(
			await createSessionTokenDigest(sessionToken, "previous-session-secret"),
		);

		db.close();
	});

	it("derives isAdmin=false for a non-admin (editor) D1 session", async () => {
		vi.stubEnv("SESSION_SECRET", "current-session-secret");
		const { db, locals } = makeLocals();
		// is_admin = 0 → the session query maps role to 'editor'.
		db.prepare(
			"INSERT INTO admin_users (email, password_hash, name, active, is_admin) VALUES (?1, ?2, ?3, 1, 0)",
		).run("editor@example.com", await hashPassword("pw"), "Editor User");

		const token = await createRuntimeSession(
			{ email: "editor@example.com", role: "editor", name: "Editor User" },
			undefined,
			locals,
		);

		// Force-true on `row.role === "admin"` would mark an editor as admin —
		// pin it so the derivation can't be mutated to a privilege escalation.
		await expect(getRuntimeSessionUser(token, locals)).resolves.toMatchObject({
			email: "editor@example.com",
			role: "editor",
			isAdmin: false,
		});
		db.close();
	});

	it("accepts and revokes sessions signed with SESSION_SECRET_PREV during rotation", async () => {
		vi.stubEnv("SESSION_SECRET", "current-session-secret");
		vi.stubEnv("SESSION_SECRET_PREV", "previous-session-secret");

		const { db, locals } = makeLocals();
		db.prepare(
			"INSERT INTO admin_users (id, email, password_hash, name, active, is_admin) VALUES (?1, ?2, ?4, ?5, 1, CASE WHEN ?3 = 'admin' THEN 1 ELSE 0 END)",
		).run(1, "admin@example.com", "admin", await hashPassword("correctpass"), "Admin User");

		const legacySessionToken = "legacy-session-token";
		const legacyDigest = await createSessionTokenDigest(
			legacySessionToken,
			"previous-session-secret",
		);
		db.prepare(
			"INSERT INTO admin_sessions (id, user_id, csrf_token, ip_address, user_agent) VALUES (?, ?, ?, ?, ?)",
		).run(legacyDigest, 1, "csrf-token", null, "vitest");

		await expect(getRuntimeSessionUser(legacySessionToken, locals)).resolves.toMatchObject({
			email: "admin@example.com",
			role: "admin",
			// Derived from role === "admin" (which the session query maps from
			// admin_users.is_admin); assert it to pin the derivation under mutation.
			isAdmin: true,
		});

		await revokeRuntimeSession(legacySessionToken, locals);

		const revoked = db
			.prepare("SELECT revoked_at FROM admin_sessions WHERE id = ?")
			.get(legacyDigest) as { revoked_at: string | null };
		expect(revoked.revoked_at).not.toBeNull();

		db.close();
	});
});

describe("authenticateRuntimeAdminUser", () => {
	afterEach(() => {
		vi.unstubAllEnvs();
	});

	async function seedUser(db: ReturnType<typeof makeDb>, opts: { active?: number } = {}) {
		db.prepare(
			"INSERT INTO admin_users (id, email, password_hash, name, active, is_admin) VALUES (?1, ?2, ?4, ?5, ?6, CASE WHEN ?3 = 'admin' THEN 1 ELSE 0 END)",
		).run(
			1,
			"admin@example.com",
			"admin",
			await hashPassword("correctpass"),
			"Admin User",
			opts.active ?? 1,
		);
	}

	it("returns SessionUser for correct credentials", { timeout: 60_000 }, async () => {
		const { db, locals } = makeLocals();
		await seedUser(db);
		const result = await authenticateRuntimeAdminUser("admin@example.com", "correctpass", locals);
		expect(result).toMatchObject({
			email: "admin@example.com",
			role: "admin",
			name: "Admin User",
		});
		db.close();
	});

	it("normalizes email — case-insensitive lookup", async () => {
		const { db, locals } = makeLocals();
		await seedUser(db);
		const result = await authenticateRuntimeAdminUser(
			"  ADMIN@EXAMPLE.COM  ",
			"correctpass",
			locals,
		);
		expect(result).not.toBeNull();
		expect(result?.email).toBe("admin@example.com");
		db.close();
	});

	it("returns null for wrong password", async () => {
		const { db, locals } = makeLocals();
		await seedUser(db);
		const result = await authenticateRuntimeAdminUser("admin@example.com", "wrongpass", locals);
		expect(result).toBeNull();
		db.close();
	});

	it("returns null for unknown user", async () => {
		const { db, locals } = makeLocals();
		const result = await authenticateRuntimeAdminUser("unknown@example.com", "somepass", locals);
		expect(result).toBeNull();
		db.close();
	});

	it("returns null when email is empty — kills guard mutation via seeded empty-email user", async () => {
		const { db, locals } = makeLocals();
		// Seed user with empty email so that if the !normalizedEmail guard is removed,
		// the DB lookup would find this user and return a non-null result.
		db.prepare(
			"INSERT INTO admin_users (id, email, password_hash, name, active, is_admin) VALUES (?1, ?2, ?4, ?5, 1, CASE WHEN ?3 = 'admin' THEN 1 ELSE 0 END)",
