import { afterAll, beforeEach, describe, expect, it, vi } from "vitest";

import { makeFormRequest } from "./helpers/make-request.js";

const mocks = vi.hoisted(() => ({
	getRuntimeCsrfToken: vi.fn(),
	getRuntimeSessionUser: vi.fn(),
	getRuntimeEnv: vi.fn(),
	getAccessContext: vi.fn(),
	logAccessDeny: vi.fn(),
}));

vi.mock("../src/runtime-admin-auth", () => ({
	getRuntimeCsrfToken: mocks.getRuntimeCsrfToken,
	getRuntimeSessionUser: mocks.getRuntimeSessionUser,
}));

vi.mock("../src/access/index.js", async () => {
	const actual =
		await vi.importActual<typeof import("../src/access/index.js")>("../src/access/index.js");
	return { ...actual, getAccessContext: mocks.getAccessContext };
});

vi.mock("../src/access/audit-deny.js", () => ({
	logAccessDeny: mocks.logAccessDeny,
}));

vi.mock("../src/runtime-env", async () => {
	const actual = await vi.importActual<typeof import("../src/runtime-env")>("../src/runtime-env");
	return {
		...actual,
		getRuntimeEnv: mocks.getRuntimeEnv,
	};
});

vi.mock("../src/runtime-env.js", async () => {
	const actual = await vi.importActual<typeof import("../src/runtime-env")>("../src/runtime-env");
	return {
		...actual,
		getRuntimeEnv: mocks.getRuntimeEnv,
	};
});

function makeContext(
	form: Record<string, string> = {},
	options: {
		url?: string;
		origin?: string | null;
		referer?: string | null;
	} = {},
) {
	const headers = new Headers();
	if (options.origin !== undefined && options.origin !== null) {
		headers.set("origin", options.origin);
	}
	if (options.referer !== undefined && options.referer !== null) {
		headers.set("referer", options.referer);
	}

	return {
		cookies: {
			get: vi.fn(() => ({ value: "session-token" })),
		},
		locals: {} as App.Locals,
		// makeFormRequest builds a real Request with a real FormData body — no cast needed.
		request: makeFormRequest(form, { url: options.url, headers }),
	} as unknown as Parameters<
		typeof import("@astropress-diy/astropress")["requireAdminFormAction"]
	>[0];
}

describe("admin action utils", () => {
	beforeEach(() => {
		vi.resetModules();
		vi.resetAllMocks();
		mocks.getRuntimeCsrfToken.mockResolvedValue("csrf-token");
		mocks.getRuntimeSessionUser.mockResolvedValue({
			email: "admin@example.com",
			role: "admin",
			name: "Admin User",
		});
		mocks.getRuntimeEnv.mockReturnValue(undefined);
		mocks.getAccessContext.mockResolvedValue(null);
		mocks.logAccessDeny.mockResolvedValue(undefined);
	});

	afterAll(() => {
		vi.resetModules();
	});

	it("redirects unauthenticated requests to login", async () => {
		mocks.getRuntimeSessionUser.mockResolvedValue(null);
		const { requireAdminFormAction } = await import("@astropress-diy/astropress");

		const result = await requireAdminFormAction(makeContext({ _csrf: "csrf-token" }), {
			failurePath: "/ap-admin/posts",
		});

		expect(result.ok).toBe(false);
		if (!result.ok) {
			expect(result.response.headers.get("Location")).toBe("/ap-admin/login");
		}
	});

	it("redirects non-admin users away from admin-only actions", async () => {
		mocks.getRuntimeSessionUser.mockResolvedValue({
			email: "editor@example.com",
			role: "editor",
			name: "Editor User",
		});
		const { requireAdminFormAction } = await import("@astropress-diy/astropress");

		const result = await requireAdminFormAction(makeContext({ _csrf: "csrf-token" }), {
			failurePath: "/ap-admin/users",
			requireAdmin: true,
		});

		expect(result.ok).toBe(false);
		if (!result.ok) {
			expect(result.response.headers.get("Location")).toContain("/ap-admin/users?error=1");
		}
	});

	it("rejects invalid csrf tokens with a safe redirect", async () => {
		const { requireAdminFormAction } = await import("@astropress-diy/astropress");

		const result = await requireAdminFormAction(makeContext({ _csrf: "wrong" }), {
			failurePath: "/ap-admin/posts/new",
		});

		expect(result.ok).toBe(false);
		if (!result.ok) {
			expect(result.response.headers.get("Location")).toBe(
				"/ap-admin/posts/new?error=1&message=Invalid+security+token",
			);
		}
	});

	it("denies a requireAction when the access engine returns a deny decision and logs the deny", async () => {
		mocks.getAccessContext.mockResolvedValue({
			subject: { email: "editor@example.com" },
			can: vi.fn(() => ({
				decision: "deny",
				reason: "policy says no",
			})),
		});
		const { requireAdminFormAction } = await import("@astropress-diy/astropress");

		const result = await requireAdminFormAction(makeContext({ _csrf: "csrf-token" }), {
			failurePath: "/ap-admin/posts",
			requireAction: "posts:delete",
		});

		expect(result.ok).toBe(false);
		if (!result.ok) {
			expect(result.response.headers.get("Location")).toContain("message=policy+says+no");
		}
		expect(mocks.logAccessDeny).toHaveBeenCalledTimes(1);
	});

	it("uses actionDeniedMessage override over the engine's reason when provided", async () => {
		mocks.getAccessContext.mockResolvedValue({
			subject: { email: "editor@example.com" },
			can: vi.fn(() => ({ decision: "deny", reason: "engine reason" })),
		});
		const { requireAdminFormAction } = await import("@astropress-diy/astropress");

		const result = await requireAdminFormAction(makeContext({ _csrf: "csrf-token" }), {
			failurePath: "/ap-admin/posts",
			requireAction: "posts:delete",
			actionDeniedMessage: "Custom denied",
		});

		expect(result.ok).toBe(false);
		if (!result.ok) {
			expect(result.response.headers.get("Location")).toContain("message=Custom+denied");
		}
	});

	it("allows the request when requireAction's decision is not 'deny'", async () => {
		mocks.getAccessContext.mockResolvedValue({
			subject: { email: "admin@example.com" },
			can: vi.fn(() => ({ decision: "allow" })),
		});
		const { requireAdminFormAction } = await import("@astropress-diy/astropress");

		const result = await requireAdminFormAction(makeContext({ _csrf: "csrf-token" }), {
			failurePath: "/ap-admin/posts",
			requireAction: "posts:delete",
		});

		expect(result.ok).toBe(true);
		expect(mocks.logAccessDeny).not.toHaveBeenCalled();
	});

	it("denies a requireAction with the default message when no engine context is available", async () => {
		mocks.getAccessContext.mockResolvedValue(null);
		const { requireAdminFormAction } = await import("@astropress-diy/astropress");

		const result = await requireAdminFormAction(makeContext({ _csrf: "csrf-token" }), {
			failurePath: "/ap-admin/posts",
			requireAction: "posts:delete",
		});

		expect(result.ok).toBe(false);
		if (!result.ok) {
			expect(result.response.headers.get("Location")).toContain(
				"message=You+do+not+have+permission",
			);
		}
		expect(mocks.logAccessDeny).not.toHaveBeenCalled();
	});

	it("rejects cross-origin admin form posts", async () => {
		const { requireAdminFormAction } = await import("@astropress-diy/astropress");

		const result = await requireAdminFormAction(
			makeContext({ _csrf: "csrf-token" }, { origin: "https://evil.example" }),
			{ failurePath: "/ap-admin/posts/new" },
		);

		expect(result.ok).toBe(false);
		if (!result.ok) {
			expect(result.response.headers.get("Location")).toBe(
				"/ap-admin/posts/new?error=1&message=Invalid+request+origin",
			);
		}
	});

	it("actionRedirect sets HSTS header only when target is an absolute https URL", async () => {
		const { actionRedirect } = await import("@astropress-diy/astropress");
		const httpsResp = actionRedirect("https://example.com/ap-admin/posts");
		const relativeResp = actionRedirect("/ap-admin/posts");
		expect(httpsResp.headers.get("Strict-Transport-Security")).not.toBeNull();
		expect(relativeResp.headers.get("Strict-Transport-Security")).toBeNull();
	});

	it("requireAdmin uses the default admin-required message when no override is provided", async () => {
		mocks.getRuntimeSessionUser.mockResolvedValue({
			email: "editor@example.com",
			role: "editor",
			name: "Editor User",
		});
		const { requireAdminFormAction } = await import("@astropress-diy/astropress");

		const result = await requireAdminFormAction(makeContext({ _csrf: "csrf-token" }), {
			failurePath: "/ap-admin/users",
			requireAdmin: true,
		});

		expect(result.ok).toBe(false);
		if (!result.ok) {
			expect(result.response.headers.get("Location")).toContain(
				"message=This+action+requires+an+admin+account.",
			);
		}
	});

	it("falls back to the legacy session cookie when the primary cookie is absent", async () => {
		const { requireAdminFormAction } = await import("@astropress-diy/astropress");
		const context = makeContext({ _csrf: "csrf-token" });
		context.cookies.get = vi.fn((name: string) =>
			name === "ff_admin_session" ? { value: "legacy-token" } : undefined,
		);

		const result = await requireAdminFormAction(context, {
			failurePath: "/ap-admin/posts",
		});

		expect(result.ok).toBe(true);
		expect(mocks.getRuntimeSessionUser).toHaveBeenCalledWith("legacy-token", expect.anything());
	});

	it("uses the loginPath override when provided for unauthenticated requests", async () => {
		mocks.getRuntimeSessionUser.mockResolvedValue(null);
		const { requireAdminFormAction } = await import("@astropress-diy/astropress");

		const result = await requireAdminFormAction(makeContext({ _csrf: "csrf-token" }), {
			failurePath: "/ap-admin/posts",
			loginPath: "/custom-login",
		});

		expect(result.ok).toBe(false);
		if (!result.ok) {
			expect(result.response.headers.get("Location")).toBe("/custom-login");
		}
	});

	it("wraps unexpected handler failures in a safe redirect", async () => {
		const { withAdminFormAction } = await import("@astropress-diy/astropress");

		const response = await withAdminFormAction(
			makeContext({ _csrf: "csrf-token" }),
			{ failurePath: "/ap-admin/posts/new" },
			async () => {
				throw new Error("boom");
			},
		);

		expect(response.headers.get("Location")).toBe(
			"/ap-admin/posts/new?error=1&message=The+requested+change+could+not+be+completed.+Reload+the+page+and+retry+the+action.",
		);
	});

	it("accepts the current non-legacy session cookie name", async () => {
		const { requireAdminFormAction } = await import("@astropress-diy/astropress");
		const context = makeContext({ _csrf: "csrf-token" });
		context.cookies.get = vi.fn((name: string) =>
			name === "astropress_admin_session" ? { value: "session-token" } : undefined,
		);

		const result = await requireAdminFormAction(context, {
			failurePath: "/ap-admin/posts",
		});

		expect(result.ok).toBe(true);
	});

	it("accepts harness locals when PLAYWRIGHT_E2E_MODE is admin-harness", async () => {
		mocks.getRuntimeSessionUser.mockResolvedValue(null);
		mocks.getRuntimeCsrfToken.mockResolvedValue(null);
		mocks.getRuntimeEnv.mockImplementation((name: string) =>
			name === "PLAYWRIGHT_E2E_MODE" ? "admin-harness" : undefined,
		);
		const { requireAdminFormAction } = await import("@astropress-diy/astropress");
		const context = makeContext({ _csrf: "harness-csrf-token" });
		context.locals = {
			adminUser: {
				email: "admin@example.com",
				role: "admin",
				name: "Admin Harness",
			},
			csrfToken: "harness-csrf-token",
		} as App.Locals;

		const result = await requireAdminFormAction(context, {
			failurePath: "/ap-admin/posts",
		});

		expect(result.ok).toBe(true);
	});

	it("projects the harness AuthUser onto the session user (admin role/name)", async () => {
		mocks.getRuntimeSessionUser.mockResolvedValue(null);
		mocks.getRuntimeCsrfToken.mockResolvedValue(null);
		mocks.getRuntimeEnv.mockImplementation((name: string) =>
			name === "PLAYWRIGHT_E2E_MODE" ? "admin-harness" : undefined,
		);
		const { withAdminFormAction } = await import("@astropress-diy/astropress");
		const context = makeContext({ _csrf: "harness-csrf-token" });
		context.locals = {
			adminUser: { email: "boss@example.com", isAdmin: true, name: "Boss" },
			csrfToken: "harness-csrf-token",
		} as unknown as App.Locals;

		let seenActor: { email: string; role: string; name: string } | undefined;
		// requireAdmin only passes if the projected isAdmin is true.
		const response = await withAdminFormAction(
			context,
			{ failurePath: "/ap-admin", requireAdmin: true },
			async ({ actor, redirect }) => {
				seenActor = actor;
				return redirect("/ok");
			},
		);
		expect(response.headers.get("Location")).toBe("/ok");
		expect(seenActor).toMatchObject({ email: "boss@example.com", role: "admin", name: "Boss" });
	});

	it("projects a non-admin harness user as editor and falls back name→email", async () => {
		mocks.getRuntimeSessionUser.mockResolvedValue(null);
		mocks.getRuntimeCsrfToken.mockResolvedValue(null);
		mocks.getRuntimeEnv.mockImplementation((name: string) =>
			name === "PLAYWRIGHT_E2E_MODE" ? "admin-harness" : undefined,
		);
		const { withAdminFormAction } = await import("@astropress-diy/astropress");
		const context = makeContext({ _csrf: "harness-csrf-token" });
		context.locals = {
			// No `name` → projection falls back to the email.
			adminUser: { email: "ed@example.com", isAdmin: false },
			csrfToken: "harness-csrf-token",
		} as unknown as App.Locals;

		let seenActor: { email: string; role: string; name: string } | undefined;
		const response = await withAdminFormAction(
			context,
			{ failurePath: "/ap-admin" },
			async ({ actor, redirect }) => {
				seenActor = actor;
				return redirect("/ok");
			},
		);
		expect(response.headers.get("Location")).toBe("/ok");
		expect(seenActor).toMatchObject({ role: "editor", name: "ed@example.com" });
	});

	it("denies a requireAdmin harness action when the projected user is not admin", async () => {
		mocks.getRuntimeSessionUser.mockResolvedValue(null);
		mocks.getRuntimeCsrfToken.mockResolvedValue(null);
		mocks.getRuntimeEnv.mockImplementation((name: string) =>
			name === "PLAYWRIGHT_E2E_MODE" ? "admin-harness" : undefined,
		);
		const { withAdminFormAction } = await import("@astropress-diy/astropress");
		const context = makeContext({ _csrf: "harness-csrf-token" });
		context.locals = {
			adminUser: { email: "ed@example.com", isAdmin: false, name: "Ed" },
			csrfToken: "harness-csrf-token",
		} as unknown as App.Locals;

		const response = await withAdminFormAction(
			context,
			{ failurePath: "/ap-admin", requireAdmin: true },
			async () => new Response("must not run"),
		);
		expect(response.headers.get("Location")).toContain("error=1");
	});

	it("passes actor and form data into successful handlers", async () => {
		const { withAdminFormAction } = await import("@astropress-diy/astropress");

		const response = await withAdminFormAction(
			makeContext({ _csrf: "csrf-token", slug: "hello-world" }),
			{ failurePath: "/ap-admin/posts/new" },
			async ({ actor, formData, redirect }) => {
				expect(actor.email).toBe("admin@example.com");
				expect(String(formData.get("slug"))).toBe("hello-world");
				return redirect("/ap-admin/posts/hello-world?created=1");
			},
		);

		expect(response.headers.get("Location")).toBe("/ap-admin/posts/hello-world?created=1");
	});

	it("builds error redirects with encoded messages", async () => {
		const { actionErrorRedirect } = await import("@astropress-diy/astropress");
		const response = actionErrorRedirect("/ap-admin/settings", "Bad input");
		expect(response.headers.get("Location")).toBe("/ap-admin/settings?error=1&message=Bad+input");
	});

	it("builds notice (success) redirects with encoded messages", async () => {
		const { actionNoticeRedirect } = await import("@astropress-diy/astropress");
		const response = actionNoticeRedirect("/ap-admin", "Build triggered.");
		expect(response.headers.get("Location")).toBe("/ap-admin?notice=1&message=Build+triggered.");
	});

	it("propagates guard non-ok response when auth check fails inside withAdminFormAction", async () => {
		mocks.getRuntimeSessionUser.mockResolvedValue(null);
		const { withAdminFormAction } = await import("@astropress-diy/astropress");

		const response = await withAdminFormAction(
			makeContext({ _csrf: "csrf-token" }),
			{ failurePath: "/ap-admin/posts" },
			async () => new Response("should not reach"),
		);

		expect(response.headers.get("Location")).toBe("/ap-admin/login");
	});

	it("fail() redirects to failurePath with encoded message", async () => {
		const { withAdminFormAction } = await import("@astropress-diy/astropress");

		const response = await withAdminFormAction(
			makeContext({ _csrf: "csrf-token" }),
			{ failurePath: "/ap-admin/posts/new" },
			async ({ fail }) => fail("Invalid title"),
		);

		expect(response.headers.get("Location")).toBe(
			"/ap-admin/posts/new?error=1&message=Invalid+title",
		);
	});

	it("fail() uses overridePath when provided", async () => {
		const { withAdminFormAction } = await import("@astropress-diy/astropress");

		const response = await withAdminFormAction(
			makeContext({ _csrf: "csrf-token" }),
			{ failurePath: "/ap-admin/posts/new" },
			async ({ fail }) => fail("Already exists", "/ap-admin/posts/existing"),
		);

		expect(response.headers.get("Location")).toBe(
			"/ap-admin/posts/existing?error=1&message=Already+exists",
		);
	});

	it("uses secure cookie name when PROD env is set", async () => {
		process.env.PROD = "true";
		try {
			const { requireAdminFormAction } = await import("@astropress-diy/astropress");
			const context = makeContext({ _csrf: "csrf-token" });
			context.cookies.get = vi.fn((name: string) =>
				name === "__Host-astropress_admin_session" ? { value: "session-token" } : undefined,
			);
			const result = await requireAdminFormAction(context, {
				failurePath: "/ap-admin/posts",
			});
			expect(result.ok).toBe(true);
		} finally {
			delete process.env.PROD;
		}
	});

	it("falls back to legacy cookie when primary session cookie is absent", async () => {
		const { requireAdminFormAction } = await import("@astropress-diy/astropress");
		const context = makeContext({ _csrf: "csrf-token" });
		// Return undefined for the primary cookie names, a value only for the legacy name
		context.cookies.get = vi.fn((name: string) =>
			name === "ff_admin_session" ? { value: "session-token" } : undefined,
		);
		const result = await requireAdminFormAction(context, {
			failurePath: "/ap-admin/posts",
		});
		expect(result.ok).toBe(true);
	});

	it("rejects when csrf token resolves to null and not in harness mode", async () => {
		mocks.getRuntimeCsrfToken.mockResolvedValue(null);
		mocks.getRuntimeEnv.mockReturnValue(undefined); // not harness mode
		const { requireAdminFormAction } = await import("@astropress-diy/astropress");
		const result = await requireAdminFormAction(makeContext({ _csrf: "anything" }), {
			failurePath: "/ap-admin/posts",
		});
		expect(result.ok).toBe(false);
	});

	it("rejects when in harness mode but csrfToken is absent from locals", async () => {
		mocks.getRuntimeCsrfToken.mockResolvedValue(null);
		mocks.getRuntimeEnv.mockImplementation((name: string) =>
			name === "PLAYWRIGHT_E2E_MODE" ? "admin-harness" : undefined,
		);
		const { requireAdminFormAction } = await import("@astropress-diy/astropress");
		const context = makeContext({ _csrf: "any" });
		// locals has adminUser but no csrfToken — triggers csrfToken ?? null path
		context.locals = {
			adminUser: { email: "admin@example.com", role: "admin", name: "Admin" },
		} as App.Locals;
		const result = await requireAdminFormAction(context, {
			failurePath: "/ap-admin/posts",
		});
		expect(result.ok).toBe(false); // expectedToken = null → CSRF check fails
	});

	it("treats a missing _csrf form field as an empty string", async () => {
		const { requireAdminFormAction } = await import("@astropress-diy/astropress");
		// Submit form with no _csrf field; empty string won't match "csrf-token"
		const result = await requireAdminFormAction(makeContext({}), {
			failurePath: "/ap-admin/posts",
		});
		expect(result.ok).toBe(false);
	});

	it("logger.info fires on successful admin action (pins L177 'admin action' message + payload)", async () => {
		const logSpy = vi.spyOn(console, "log").mockImplementation(() => {});
		const { withAdminFormAction } = await import("@astropress-diy/astropress");
		await withAdminFormAction(
			makeContext({ _csrf: "csrf-token" }),
			{ failurePath: "/ap-admin" },
			async () => new Response("ok"),
		);
		const matched = logSpy.mock.calls.find((args) =>
			args.some((a) => typeof a === "string" && a === "admin action"),
		);
		expect(matched).toBeDefined();
		const meta = matched?.[2] as Record<string, unknown>;
		expect(meta?.actor).toBe("admin@example.com");
		logSpy.mockRestore();
	});

	it("logger.warn fires when fail() is invoked (pins L193 'admin action failed' message + payload)", async () => {
		const warnSpy = vi.spyOn(console, "warn").mockImplementation(() => {});
		const { withAdminFormAction } = await import("@astropress-diy/astropress");
		await withAdminFormAction(
			makeContext({ _csrf: "csrf-token" }),
			{ failurePath: "/ap-admin" },
			async ({ fail }) => fail("bad input"),
		);
		const matched = warnSpy.mock.calls.find((args) =>
			args.some((a) => typeof a === "string" && a === "admin action failed"),
		);
		expect(matched).toBeDefined();
		const meta = matched?.[2] as Record<string, unknown>;
		expect(meta?.message).toBe("bad input");
		warnSpy.mockRestore();
	});

	it("logger.error fires on unexpected handler throw (pins L203 'admin action error' message + payload)", async () => {
		const errorSpy = vi.spyOn(console, "error").mockImplementation(() => {});
		const { withAdminFormAction } = await import("@astropress-diy/astropress");
		await withAdminFormAction(
			makeContext({ _csrf: "csrf-token" }),
			{ failurePath: "/ap-admin" },
			async () => {
				throw new Error("kaboom");
			},
		);
		const matched = errorSpy.mock.calls.find((args) =>
			args.some((a) => typeof a === "string" && a === "admin action error"),
		);
		expect(matched).toBeDefined();
		const meta = matched?.[2] as Record<string, unknown>;
		expect(String(meta?.error)).toContain("kaboom");
		errorSpy.mockRestore();
	});

	it("logAccessDeny payload uses subjectEmail from access subject (pins L83 ?? fallback ordering)", async () => {
		mocks.getAccessContext.mockResolvedValue({
			subject: { email: "subject-email@example.com" },
			can: vi.fn(() => ({ decision: "deny", reason: "no" })),
		});
		const { requireAdminFormAction } = await import("@astropress-diy/astropress");
		await requireAdminFormAction(makeContext({ _csrf: "csrf-token" }), {
			failurePath: "/ap-admin",
			requireAction: "posts:delete",
		});
		expect(mocks.logAccessDeny).toHaveBeenCalledWith(
			expect.anything(),
			expect.objectContaining({ subjectEmail: "subject-email@example.com" }),
		);
	});

	it("unknown option keys like requireRole do NOT enforce admin-only access (regression for #35)", async () => {
		// Simulates the old publish.ts bug: passing { requireRole: "admin" } instead of { requireAdmin: true }.
		// The guard must not silently ignore unknown keys — this test proves that only requireAdmin works.
		mocks.getRuntimeSessionUser.mockResolvedValue({
			email: "editor@example.com",
			role: "editor",
			name: "Editor User",
		});
		const { requireAdminFormAction } = await import("@astropress-diy/astropress");

		const result = await requireAdminFormAction(makeContext({ _csrf: "csrf-token" }), {
			failurePath: "/ap-admin",
			// @ts-expect-error — deliberately testing the wrong key to prove it doesn't guard
			requireRole: "admin",
		});

		// Without requireAdmin: true, an editor session passes the guard — this is the bug.
		// The fix is in publish.ts (use requireAdmin: true), not here. This test documents the footgun.
		expect(result.ok).toBe(true);
	});
});

