import { readFileSync } from "node:fs";
import path from "node:path";
import { beforeEach, describe, expect, it, vi } from "vitest";

// Mock only the runtime store/registry seams; the real ./sections pipeline runs
// so the tests prove the body is genuinely rendered (not an empty stub — #200)
// and the on-demand dev entrypoint resolves pages exactly like production (#198).
const mocks = vi.hoisted(() => ({
	getRuntimeStructuredPageRoute: vi.fn(),
	listRuntimeStructuredPageRoutes: vi.fn(),
	getRuntimeMediaAssets: vi.fn(),
	getRuntimeTestimonials: vi.fn(),
}));

vi.mock("../src/runtime-route-registry", () => ({
	getRuntimeStructuredPageRoute: mocks.getRuntimeStructuredPageRoute,
	listRuntimeStructuredPageRoutes: mocks.listRuntimeStructuredPageRoutes,
}));
vi.mock("../src/runtime-page-store", () => ({
	getRuntimeMediaAssets: mocks.getRuntimeMediaAssets,
	getRuntimeTestimonials: mocks.getRuntimeTestimonials,
}));

import {
	buildPublicStructuredPageModel,
	listPublishedStructuredPagePaths,
} from "../src/public-structured-page";

const locals = {} as App.Locals;

const publishedRecord = {
	path: "/about",
	status: "published",
	title: "About Us",
	seoTitle: "About Us — SEO",
	summary: "A short summary.",
	metaDescription: "Meta description.",
	canonicalUrlOverride: "https://example.com/about",
	robotsDirective: "index,follow",
	ogImage: "https://example.com/og.png",
	sections: [
		{ id: "h1", kind: "hero", headline: "Welcome", mediaId: "m1" },
		{ id: "r1", kind: "rich-text", html: "<p>RICHTEXT_MARKER</p>" },
	],
};

describe("buildPublicStructuredPageModel", () => {
	beforeEach(() => {
		vi.clearAllMocks();
		mocks.getRuntimeMediaAssets.mockResolvedValue([
			{ id: "m1", sourceUrl: null, localPath: "/media/hero.webp", r2Key: null },
		]);
		mocks.getRuntimeTestimonials.mockResolvedValue([]);
	});

	it("returns null for a page that is not published", async () => {
		mocks.getRuntimeStructuredPageRoute.mockResolvedValue({ ...publishedRecord, status: "draft" });
		expect(await buildPublicStructuredPageModel("/about", locals)).toBeNull();
	});

	it("returns null when no route record exists", async () => {
		mocks.getRuntimeStructuredPageRoute.mockResolvedValue(null);
		expect(await buildPublicStructuredPageModel("/missing", locals)).toBeNull();
	});

	it("resolves a published page into a render-ready model, querying by path", async () => {
		mocks.getRuntimeStructuredPageRoute.mockResolvedValue(publishedRecord);
		const model = await buildPublicStructuredPageModel("/about", locals);

		expect(mocks.getRuntimeStructuredPageRoute).toHaveBeenCalledWith("/about", locals);
		expect(model).not.toBeNull();
		expect(model?.title).toBe("About Us — SEO");
		expect(model?.description).toBe("Meta description.");
		expect(model?.canonical).toBe("https://example.com/about");
		expect(model?.robots).toBe("index,follow");
		expect(model?.ogImage).toBe("https://example.com/og.png");
	});

	it("actually renders the sections into the body, resolving referenced media (#200)", async () => {
		mocks.getRuntimeStructuredPageRoute.mockResolvedValue(publishedRecord);
		const model = await buildPublicStructuredPageModel("/about", locals);
		// Body is genuinely rendered from the sections, not an empty stub…
		expect(model?.body).toContain("RICHTEXT_MARKER");
		// …and a referenced media asset lands in the HTML rather than being dropped.
		expect(model?.body).toContain('src="/media/hero.webp"');
	});

	it("falls back seoTitle → title → slug for the page title", async () => {
		mocks.getRuntimeStructuredPageRoute.mockResolvedValue({ ...publishedRecord, seoTitle: "" });
		expect((await buildPublicStructuredPageModel("/about", locals))?.title).toBe("About Us");

		mocks.getRuntimeStructuredPageRoute.mockResolvedValue({
			...publishedRecord,
			seoTitle: "",
			title: "",
		});
		// Slug is derived from the requested path, sans leading slash.
		expect((await buildPublicStructuredPageModel("/about", locals))?.title).toBe("about");
	});

	it("falls back metaDescription → summary → empty string", async () => {
		mocks.getRuntimeStructuredPageRoute.mockResolvedValue({
			...publishedRecord,
			metaDescription: undefined,
		});
		expect((await buildPublicStructuredPageModel("/about", locals))?.description).toBe(
			"A short summary.",
		);

		mocks.getRuntimeStructuredPageRoute.mockResolvedValue({
			...publishedRecord,
			metaDescription: undefined,
			summary: undefined,
		});
		expect((await buildPublicStructuredPageModel("/about", locals))?.description).toBe("");
	});

	it("defaults canonical/robots/ogImage to empty strings when the record omits them", async () => {
		mocks.getRuntimeStructuredPageRoute.mockResolvedValue({
			...publishedRecord,
			canonicalUrlOverride: undefined,
			robotsDirective: undefined,
			ogImage: undefined,
		});
		const model = await buildPublicStructuredPageModel("/about", locals);
		expect(model?.canonical).toBe("");
		expect(model?.robots).toBe("");
		expect(model?.ogImage).toBe("");
	});

	it("fetches only approved+featured testimonials and renders their quotes", async () => {
		mocks.getRuntimeStructuredPageRoute.mockResolvedValue({
			...publishedRecord,
			sections: [{ id: "t1", kind: "testimonials", source: "approved", layout: "grid" }],
		});
		mocks.getRuntimeTestimonials.mockImplementation(async (status: string) =>
			status === "approved"
				? [
						{
							id: "q1",
							name: "Ada",
							specificResult: "TESTIMONIAL_QUOTE",
							consentToPublish: true,
							status: "approved",
						},
					]
				: [],
		);
		const model = await buildPublicStructuredPageModel("/about", locals);
		// The testimonials reader must actually run and its quote must land in the body.
		expect(model?.body).toContain("TESTIMONIAL_QUOTE");
		// Only the approved + featured statuses are ever queried for the public surface.
		expect(mocks.getRuntimeTestimonials).toHaveBeenCalledWith("approved", locals);
		expect(mocks.getRuntimeTestimonials).toHaveBeenCalledWith("featured", locals);
	});

	it("renders no section content when the sections payload fails to parse", async () => {
		mocks.getRuntimeStructuredPageRoute.mockResolvedValue({
			...publishedRecord,
			sections: "not-a-valid-sections-payload",
		});
		const model = await buildPublicStructuredPageModel("/about", locals);
		expect(model).not.toBeNull();
		// Parse failure → sections = [] → none of the record's authored content renders.
		expect(model?.body).not.toContain("RICHTEXT_MARKER");
		expect(model?.body).not.toContain('src="/media/hero.webp"');
	});
});

describe("listPublishedStructuredPagePaths", () => {
	it("returns only published paths, excluding empty and the host-owned root", async () => {
		mocks.listRuntimeStructuredPageRoutes.mockResolvedValue([
			{ path: "/about", status: "published" },
			{ path: "/draft", status: "draft" },
			{ path: "/", status: "published" },
			{ path: "", status: "published" },
			{ path: "/contact", status: "published" },
		]);
		expect(await listPublishedStructuredPagePaths()).toEqual(["/about", "/contact"]);
	});
});

// #198 / #200 wiring guards: the .astro entrypoints' frontmatter can't run under
// vitest, so assert their source delegates to the shared resolver and can't
// regress to inlined logic or the wrong prerender strategy.
describe("public-renderer entrypoint wiring", () => {
	const read = (rel: string) => readFileSync(path.resolve(import.meta.dirname, "..", rel), "utf8");

	it("both entrypoints resolve pages through buildPublicStructuredPageModel", () => {
		expect(read("pages/astropress-public-page.astro")).toContain("buildPublicStructuredPageModel(");
		expect(read("pages/astropress-public-page-dev.astro")).toContain(
			"buildPublicStructuredPageModel(",
		);
	});

	it("the production entrypoint prerenders via getStaticPaths", () => {
		const src = read("pages/astropress-public-page.astro");
		expect(src).toMatch(/export const prerender = true/);
		// The call/definition, not the word — the dev page mentions it in prose.
		expect(src).toMatch(/getStaticPaths\s*\(/);
	});

	it("the dev entrypoint is on-demand: prerender=false and no getStaticPaths (#198)", () => {
		const src = read("pages/astropress-public-page-dev.astro");
		expect(src).toMatch(/export const prerender = false/);
		// No getStaticPaths definition/call (a passing mention in the comment is fine).
		expect(src).not.toMatch(/getStaticPaths\s*\(/);
	});
});

tests/disaster-recovery.test.ts.source:
/**
 * Disaster recovery tests — verifies the backup/restore and schema upgrade cycles
 * that operators rely on after data loss or failed migrations.
 *
 * All tests are fully in-process: no CLI invocations, no real filesystem state outside tmpdir.
 */

import { existsSync, mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { DatabaseSync } from "node:sqlite";
import { afterEach, beforeEach, describe, expect, it } from "vitest";

import { readAstropressSqliteSchemaSql, runAstropressMigrations } from "../src/sqlite-bootstrap.js";
import { ensureLegacySchemaCompatibility, getTableColumns } from "../src/sqlite-schema-compat.js";
import { createAstropressGitSyncAdapter } from "../src/sync/git.js";
import { makeDb } from "./helpers/make-db.js";

// Minimal v0.0.1-era schema — missing columns added in later versions
const V001_SCHEMA = `
  CREATE TABLE IF NOT EXISTS content_entries (
    slug TEXT PRIMARY KEY,
    title TEXT NOT NULL,
    kind TEXT NOT NULL DEFAULT 'post',
    template_key TEXT,
    source_html_path TEXT,
    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
    body TEXT,
    summary TEXT
  );

  CREATE TABLE IF NOT EXISTS content_overrides (
    slug TEXT PRIMARY KEY,
    title TEXT NOT NULL,
    status TEXT NOT NULL CHECK(status IN ('draft', 'published')),
    body TEXT,
    seo_title TEXT,
    meta_description TEXT,
    excerpt TEXT,
    og_title TEXT,
    og_description TEXT,
    og_image TEXT,
    canonical_url_override TEXT,
    robots_directive TEXT,
    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
    updated_by TEXT NOT NULL
  );

  CREATE TABLE IF NOT EXISTS content_revisions (
    id TEXT PRIMARY KEY,
    slug TEXT NOT NULL,
    source TEXT NOT NULL DEFAULT 'reviewed',
    title TEXT NOT NULL,
    status TEXT NOT NULL,
    body TEXT,
    seo_title TEXT,
    meta_description TEXT,
    excerpt TEXT,
    og_title TEXT,
    og_description TEXT,
    og_image TEXT,
    canonical_url_override TEXT,
    robots_directive TEXT,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    created_by TEXT,
    updated_at TEXT NOT NULL,
    updated_by TEXT NOT NULL
  );

  CREATE TABLE IF NOT EXISTS media_assets (
    id TEXT PRIMARY KEY,
    filename TEXT NOT NULL,
    mime_type TEXT NOT NULL,
    file_size INTEGER,
    alt_text TEXT,
    created_at TEXT DEFAULT CURRENT_TIMESTAMP
  );

  CREATE TABLE IF NOT EXISTS schema_migrations (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL UNIQUE,
    applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
  );

  CREATE TABLE IF NOT EXISTS admin_users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    email TEXT NOT NULL UNIQUE,
    password_hash TEXT NOT NULL,
    role TEXT NOT NULL DEFAULT 'editor',
    name TEXT
  );
`;

let tempDir: string;

beforeEach(() => {
	tempDir = mkdtempSync(join(tmpdir(), "astropress-dr-"));
});

afterEach(() => {
	rmSync(tempDir, { recursive: true, force: true });
});

describe("schema compatibility after restore from old version", () => {
	it("adds metadata column to content_overrides when restoring from v0.0.1 schema", () => {
		const db = new DatabaseSync(":memory:");
		db.exec(V001_SCHEMA);

		// Confirm metadata column is absent before compat
		const colsBefore = getTableColumns(db, "content_overrides");
		expect(colsBefore).not.toContain("metadata");

		ensureLegacySchemaCompatibility(db);

		const colsAfter = getTableColumns(db, "content_overrides");
		expect(colsAfter).toContain("metadata");
		db.close();
	});

	it("adds scheduled_at and revision columns after compat run", () => {
		const db = new DatabaseSync(":memory:");
		db.exec(V001_SCHEMA);

		ensureLegacySchemaCompatibility(db);

		const overrideCols = getTableColumns(db, "content_overrides");
		expect(overrideCols).toContain("metadata");

		const mediaCols = getTableColumns(db, "media_assets");
		expect(mediaCols).toContain("thumbnail_url");
		expect(mediaCols).toContain("srcset");

		db.close();
	});

	it("existing content rows survive the compat upgrade", () => {
		const db = new DatabaseSync(":memory:");
		db.exec(V001_SCHEMA);

		// Seed a row in the old schema
		db.prepare(
			`INSERT INTO content_overrides (slug, title, status, updated_by)
       VALUES ('hello-world', 'Hello World', 'published', 'admin@example.com')`,
		).run();

		ensureLegacySchemaCompatibility(db);

		const row = db
			.prepare("SELECT slug, title, status FROM content_overrides WHERE slug = 'hello-world'")
			.get() as { slug: string; title: string; status: string } | undefined;

		expect(row).toBeDefined();
		expect(row?.slug).toBe("hello-world");
		expect(row?.title).toBe("Hello World");
		expect(row?.status).toBe("published");

		db.close();
	});
});

describe("migration runner on fresh schema", () => {
	it("runAstropressMigrations does not throw on a fresh schema with no migrations dir", () => {
		const db = makeDb();

		const migrationsDir = join(tempDir, "nonexistent-migrations");
		expect(() => runAstropressMigrations(db, migrationsDir)).not.toThrow();

		db.close();
	});

	it("applies pending migrations from a migrations dir and records them", () => {
		const db = makeDb();

		const migrationsDir = join(tempDir, "migrations");
		mkdirSync(migrationsDir);

		// Write a simple additive migration
		writeFileSync(
			join(migrationsDir, "0001_add_custom_column.sql"),
			"ALTER TABLE content_overrides ADD COLUMN custom_field TEXT;",
		);
		writeFileSync(
			join(migrationsDir, "0001_add_custom_column.down.sql"),
			"-- rollback: column cannot be removed in SQLite without table rebuild",
		);

		const result = runAstropressMigrations(db, migrationsDir);
		expect(result.applied).toContain("0001_add_custom_column.sql");
		expect(result.skipped).toHaveLength(0);

		// Verify it was recorded in schema_migrations
		const record = db
			.prepare(
				"SELECT name, rollback_sql FROM schema_migrations WHERE name = '0001_add_custom_column.sql'",
			)
			.get() as { name: string; rollback_sql: string | null } | undefined;

		expect(record).toBeDefined();
		expect(record?.name).toBe("0001_add_custom_column.sql");
		expect(record?.rollback_sql).toContain("rollback");

		// Verify column was added
		const cols = getTableColumns(db, "content_overrides");
		expect(cols).toContain("custom_field");

		db.close();
	});

	it("skips already-applied migrations on re-run", () => {
		const db = makeDb();

		const migrationsDir = join(tempDir, "migrations");
		mkdirSync(migrationsDir);
		writeFileSync(
			join(migrationsDir, "0001_idempotent.sql"),
			"ALTER TABLE content_overrides ADD COLUMN idempotent_col TEXT;",
		);

		runAstropressMigrations(db, migrationsDir);
		const result2 = runAstropressMigrations(db, migrationsDir);

		expect(result2.applied).toHaveLength(0);
		expect(result2.skipped).toContain("0001_idempotent.sql");

		db.close();
	});
});

describe("backup and restore cycle using git sync adapter", () => {
	it("restores content after simulating DB loss", async () => {
		const projectDir = join(tempDir, "project");
		const dataDir = join(projectDir, ".data");
		const dbPath = join(dataDir, "admin.db");
		const snapshotDir = join(tempDir, "snapshot");

		mkdirSync(dataDir, { recursive: true });

		// Create a SQLite DB in the project .data directory and seed a record
		const db = new DatabaseSync(dbPath);
		db.exec(readAstropressSqliteSchemaSql());
		db.prepare(
			`INSERT INTO content_overrides (slug, title, status, updated_by)
       VALUES ('dr-test-post', 'DR Test Post', 'published', 'admin@example.com')`,
		).run();
		db.close();

		// Export snapshot including .data directory
		const adapter = createAstropressGitSyncAdapter({
			projectDir,
			include: [".data"],
		});
		await adapter.exportSnapshot(snapshotDir);

		// Simulate data loss: remove the DB file
		rmSync(dbPath);
		expect(existsSync(dbPath)).toBe(false);

		// Restore from snapshot
		await adapter.importSnapshot(snapshotDir);
		expect(existsSync(dbPath)).toBe(true);

		// Verify content is intact
		const restored = new DatabaseSync(dbPath);
		const row = restored
			.prepare("SELECT slug, title FROM content_overrides WHERE slug = 'dr-test-post'")
			.get() as { slug: string; title: string } | undefined;

		expect(row).toBeDefined();
		expect(row?.slug).toBe("dr-test-post");
		expect(row?.title).toBe("DR Test Post");

		restored.close();
	});
});

tests/runtime-actions-content-helpers.te.source:
import { describe, expect, it } from "vitest";
import {
	cleanIdList,
	detectConflict,
	insertContentRevision,
	normalizeLegacyUrl,
	normalizeScheduledAt,
	normalizeSeoFields,
	nullsToUndefined,
	serializeMetadata,
	trimOrNull,
} from "../src/runtime-actions-content-helpers";
import { makeDb, STANDARD_ACTOR } from "./helpers/make-db.js";
import { SqliteBackedD1Database } from "./helpers/provider-test-fixtures.js";

describe("trimOrNull", () => {
	it("returns null for undefined / null / empty / whitespace-only inputs", () => {
		expect(trimOrNull(undefined)).toBeNull();
		expect(trimOrNull(null)).toBeNull();
		expect(trimOrNull("")).toBeNull();
		expect(trimOrNull("   ")).toBeNull();
	});

	it("returns the trimmed string for non-empty input", () => {
		expect(trimOrNull("  hello  ")).toBe("hello");
		expect(trimOrNull("hello")).toBe("hello");
	});
});

describe("cleanIdList", () => {
	it("returns [] when input is undefined or empty", () => {
		expect(cleanIdList(undefined)).toEqual([]);
		expect(cleanIdList([])).toEqual([]);
	});

	it("filters non-positive integers and de-dupes while preserving first-seen order", () => {
		expect(cleanIdList([1, 2, 2, 3, 1, 4])).toEqual([1, 2, 3, 4]);
		expect(cleanIdList([0, -1, 1.5, Number.NaN, 5])).toEqual([5]);
	});

	it("treats Infinity and non-integers as invalid", () => {
		expect(cleanIdList([Number.POSITIVE_INFINITY, 1.1, 0, 7])).toEqual([7]);
	});
});

describe("normalizeSeoFields", () => {
	it("trims each field and converts blank/missing to null", () => {
		expect(
			normalizeSeoFields({
				excerpt: "  ex  ",
				ogTitle: "",
				ogDescription: "   ",
				ogImage: undefined,
				canonicalUrlOverride: "https://example.com/c",
				robotsDirective: "noindex",
			}),
		).toEqual({
			excerpt: "ex",
			ogTitle: null,
			ogDescription: null,
			ogImage: null,
			canonicalUrlOverride: "https://example.com/c",
			robotsDirective: "noindex",
		});
	});

	it("returns null for every field when input is fully empty", () => {
		expect(normalizeSeoFields({})).toEqual({
			excerpt: null,
			ogTitle: null,
			ogDescription: null,
			ogImage: null,
			canonicalUrlOverride: null,
			robotsDirective: null,
		});
	});
});

describe("normalizeScheduledAt", () => {
	it("returns null for undefined / empty / whitespace-only inputs", () => {
		expect(normalizeScheduledAt(undefined)).toBeNull();
		expect(normalizeScheduledAt("")).toBeNull();
		expect(normalizeScheduledAt("   ")).toBeNull();
	});

	it("returns an ISO-8601 UTC string for a parseable timestamp", () => {
		expect(normalizeScheduledAt("2026-02-01T00:00:00Z")).toBe("2026-02-01T00:00:00.000Z");
		expect(normalizeScheduledAt("2026-02-01T00:00:00+00:00")).toBe("2026-02-01T00:00:00.000Z");
	});
});

describe("normalizeLegacyUrl", () => {
	it("returns the trimmed legacyUrl when present, prefixed with '/' if missing", () => {
		expect(normalizeLegacyUrl("/already-prefixed", "slug")).toBe("/already-prefixed");
		expect(normalizeLegacyUrl("missing-prefix", "slug")).toBe("/missing-prefix");
		expect(normalizeLegacyUrl("  /trimmed  ", "slug")).toBe("/trimmed");
	});

	it("falls back to '/<slug>' when legacyUrl is undefined / empty / whitespace-only", () => {
		expect(normalizeLegacyUrl(undefined, "hello")).toBe("/hello");
		expect(normalizeLegacyUrl("", "hello")).toBe("/hello");
		expect(normalizeLegacyUrl("   ", "hello")).toBe("/hello");
	});
});

describe("serializeMetadata", () => {
	it("returns null when metadata is empty", () => {
		expect(serializeMetadata({})).toBeNull();
	});

	it("returns a JSON-stringified copy when metadata has at least one key", () => {
		expect(serializeMetadata({ a: 1, b: "x" })).toBe(JSON.stringify({ a: 1, b: "x" }));
	});
});

describe("nullsToUndefined", () => {
	it("replaces null values with undefined while preserving the original key set", () => {
		const result = nullsToUndefined({ a: 1, b: null, c: "x", d: null });
		expect(result).toEqual({ a: 1, b: undefined, c: "x", d: undefined });
		expect(Object.keys(result).sort()).toEqual(["a", "b", "c", "d"]);
	});

	it("leaves undefined values as undefined and non-null primitives unchanged", () => {
		const result = nullsToUndefined({ a: undefined, b: 0, c: false });
		expect(result).toEqual({ a: undefined, b: 0, c: false });
	});
});

describe("detectConflict", () => {
	function setup() {
		const db = makeDb();
		const d1 = new SqliteBackedD1Database(db);
		db.prepare(
			"INSERT INTO content_overrides (slug, title, status, updated_at, updated_by) VALUES (?, ?, ?, ?, ?)",
		).run("hello", "Hello", "draft", "2026-01-01T00:00:00Z", "seed@test.local");
		return d1;
	}

	it("returns null when no row exists for the slug", async () => {
		const d1 = new SqliteBackedD1Database(makeDb());
		expect(await detectConflict(d1, "nope", "2026-01-01T00:00:00Z")).toBeNull();
	});

	it("returns null when the persisted updated_at matches the lastKnownUpdatedAt", async () => {
		const d1 = setup();
		expect(await detectConflict(d1, "hello", "2026-01-01T00:00:00Z")).toBeNull();
	});

	it("returns the conflict envelope when updated_at differs from lastKnownUpdatedAt", async () => {
		const d1 = setup();
		const result = await detectConflict(d1, "hello", "1999-01-01T00:00:00Z");
		expect(result).toEqual({
			ok: false,
			error:
				"This record was modified by another editor after you opened it. Reload to see the latest version.",
			conflict: true,
		});
	});
});

describe("insertContentRevision", () => {
	it("writes a content_revisions row with source='reviewed', a 'revision-<uuid>' id, and persisted SEO fields", async () => {
		const db = makeDb();
		const d1 = new SqliteBackedD1Database(db);
		db.prepare(
			"INSERT INTO content_overrides (slug, title, status, updated_by) VALUES (?, ?, ?, ?)",
		).run("hello", "Hello", "draft", "seed@test.local");
		await insertContentRevision(d1, "hello", {
			title: "T",
			status: "draft",
			scheduledAt: "2026-02-01T00:00:00Z",
			body: "body",
			seoTitle: "S",
			metaDescription: "M",
			seo: normalizeSeoFields({
				excerpt: "ex",
				ogTitle: "ot",
				ogDescription: "od",
				ogImage: "https://example.com/og.png",
				canonicalUrlOverride: "https://example.com/c",
				robotsDirective: "noindex",
			}),
			authorIds: "[1]",
			categoryIds: "[2]",
			tagIds: "[3]",
			revisionNote: "first",
			actor: STANDARD_ACTOR,
		});
		const row = db
			.prepare(
				"SELECT id, slug, source, title, status, scheduled_at, body, seo_title, meta_description, excerpt, og_title, og_description, og_image, author_ids, category_ids, tag_ids, canonical_url_override, robots_directive, revision_note, created_by FROM content_revisions WHERE slug = 'hello'",
			)
			.get() as Record<string, unknown>;
		expect((row.id as string).startsWith("revision-")).toBe(true);
		expect(row.source).toBe("reviewed");
		expect(row.title).toBe("T");
		expect(row.status).toBe("draft");
		expect(row.scheduled_at).toBe("2026-02-01T00:00:00Z");
		expect(row.body).toBe("body");
		expect(row.seo_title).toBe("S");
		expect(row.meta_description).toBe("M");
		expect(row.excerpt).toBe("ex");
		expect(row.og_title).toBe("ot");
		expect(row.og_description).toBe("od");
		expect(row.og_image).toBe("https://example.com/og.png");
		expect(row.author_ids).toBe("[1]");
		expect(row.category_ids).toBe("[2]");
		expect(row.tag_ids).toBe("[3]");
		expect(row.canonical_url_override).toBe("https://example.com/c");
		expect(row.robots_directive).toBe("noindex");
		expect(row.revision_note).toBe("first");
		expect(row.created_by).toBe(STANDARD_ACTOR.email);
	});

	it("binds null for scheduledAt when scheduledAt is undefined", async () => {
		const db = makeDb();
		const d1 = new SqliteBackedD1Database(db);
		db.prepare(
			"INSERT INTO content_overrides (slug, title, status, updated_by) VALUES (?, ?, ?, ?)",
		).run("hello", "Hello", "draft", "seed@test.local");
		await insertContentRevision(d1, "hello", {
			title: "T",
			status: "draft",
			body: "b",
			seoTitle: "S",
			metaDescription: "M",
			seo: normalizeSeoFields({}),
			authorIds: "[]",
			categoryIds: "[]",
			tagIds: "[]",
			revisionNote: null,
			actor: STANDARD_ACTOR,
		});
		const row = db
			.prepare("SELECT scheduled_at, revision_note FROM content_revisions WHERE slug = 'hello'")
			.get() as { scheduled_at: string | null; revision_note: string | null };
		expect(row.scheduled_at).toBeNull();
		expect(row.revision_note).toBeNull();
	});
});

tests/sqlite-runtime/routes-helpers.test.source:
import { afterEach, beforeEach, describe, expect, it } from "vitest";

import { registerCms } from "../../src/config";
import {
	mapArchiveRow,
	mapStructuredPageRow,
	SQL_FIND_ARCHIVE_FOR_UPDATE,
	SQL_FIND_STRUCTURED_FOR_UPDATE,
	SQL_FIND_SYSTEM_FOR_UPDATE,
	SQL_GET_ARCHIVE,
	SQL_INSERT_ARCHIVE_REVISION,
	SQL_INSERT_REVISION,
	SQL_INSERT_ROUTE_GROUP,
	SQL_INSERT_ROUTE_VARIANT,
	SQL_IS_PATH_TAKEN,
	SQL_LIST_ARCHIVES,
	SQL_LIST_STRUCTURED,
	SQL_LIST_SYSTEM,
	SQL_PERSIST_ARCHIVE,
	SQL_PERSIST_STRUCTURED,
	SQL_PERSIST_SYSTEM,
