import { createAstropressCloudflareAdapter, registerCms } from "@astropress-diy/astropress";
import { beforeEach, describe, expect, it } from "vitest";
import { makeDb, STANDARD_CMS_CONFIG } from "./helpers/make-db.js";
import { SqliteBackedD1Database } from "./helpers/provider-test-fixtures.js";

let db: ReturnType<typeof makeDb>;
let d1: SqliteBackedD1Database;
let adapter: ReturnType<typeof createAstropressCloudflareAdapter>;

beforeEach(() => {
	registerCms(STANDARD_CMS_CONFIG);
	db = makeDb();
	d1 = new SqliteBackedD1Database(db);
	adapter = createAstropressCloudflareAdapter({ db: d1 });
});

function getOverride(slug: string) {
	return db
		.prepare(
			"SELECT title, status, body, seo_title, meta_description, excerpt, og_title, og_description, og_image, canonical_url_override, robots_directive FROM content_overrides WHERE slug = ?",
		)
		.get(slug) as Record<string, unknown> | undefined;
}

function getEntry(slug: string) {
	return db
		.prepare(
			"SELECT slug, legacy_url, title, kind, template_key, source_html_path, body, summary, seo_title, meta_description, og_title, og_description, og_image FROM content_entries WHERE slug = ?",
		)
		.get(slug) as Record<string, unknown> | undefined;
}

describe("cloudflare savePageOrPost — new record (no existing entry)", () => {
	it("uses metadata.legacyUrl when provided, else falls back to '/<slug>'", async () => {
		await adapter.content.save({
			id: "with-legacy",
			kind: "post",
			slug: "with-legacy",
			title: "T",
			metadata: { legacyUrl: "/custom/legacy/path" },
		});
		expect(getEntry("with-legacy")?.legacy_url).toBe("/custom/legacy/path");

		await adapter.content.save({
			id: "default-legacy",
			kind: "post",
			slug: "default-legacy",
			title: "T",
		});
		expect(getEntry("default-legacy")?.legacy_url).toBe("/default-legacy");
	});

	it("uses metadata.templateKey when provided, else falls back to 'content'", async () => {
		await adapter.content.save({
			id: "with-template",
			kind: "post",
			slug: "with-template",
			title: "T",
			metadata: { templateKey: "custom-template" },
		});
		expect(getEntry("with-template")?.template_key).toBe("custom-template");

		await adapter.content.save({
			id: "default-template",
			kind: "post",
			slug: "default-template",
			title: "T",
		});
		expect(getEntry("default-template")?.template_key).toBe("content");
	});

	it("uses 'runtime://content/<slug>' as the source_html_path for new entries", async () => {
		await adapter.content.save({
			id: "src-path",
			kind: "post",
			slug: "src-path",
			title: "T",
		});
		expect(getEntry("src-path")?.source_html_path).toBe("runtime://content/src-path");
	});

	it("falls back to slug when title is omitted and there is no existing record", async () => {
		await adapter.content.save({
			id: "no-title-slug",
			kind: "post",
			slug: "no-title-slug",
		});
		const override = getOverride("no-title-slug");
		expect(override?.title).toBe("no-title-slug");
	});

	it("uses record.id as the slug when slug is omitted", async () => {
		await adapter.content.save({
			id: "id-as-slug",
			kind: "post",
			title: "T",
		});
		expect(getEntry("id-as-slug")?.slug).toBe("id-as-slug");
	});
});

describe("cloudflare savePageOrPost — metadata → override fields", () => {
	it("maps metadata.summary, seoTitle, metaDescription, ogTitle/Description/Image, canonicalUrlOverride, robotsDirective to the override row", async () => {
		await adapter.content.save({
			id: "rich-meta",
			kind: "post",
			slug: "rich-meta",
			title: "Rich Title",
			body: "<p>body</p>",
			metadata: {
				summary: "rich summary",
				seoTitle: "rich seo title",
				metaDescription: "rich meta description",
				ogTitle: "rich og title",
				ogDescription: "rich og description",
				ogImage: "https://example.com/og.png",
				canonicalUrlOverride: "https://example.com/canonical",
				robotsDirective: "noindex",
			},
		});

		const override = getOverride("rich-meta");
		expect(override).toMatchObject({
			title: "Rich Title",
			body: "<p>body</p>",
			seo_title: "rich seo title",
			meta_description: "rich meta description",
			excerpt: "rich summary",
			og_title: "rich og title",
			og_description: "rich og description",
			og_image: "https://example.com/og.png",
			canonical_url_override: "https://example.com/canonical",
			robots_directive: "noindex",
		});
	});

	it("falls back to title when metadata.seoTitle / metaDescription are absent", async () => {
		await adapter.content.save({
			id: "no-seo",
			kind: "post",
			slug: "no-seo",
			title: "Fallback Title",
		});
		const override = getOverride("no-seo");
		expect(override?.seo_title).toBe("Fallback Title");
		expect(override?.meta_description).toBe("Fallback Title");
	});

	it("ignores non-string metadata values for ogTitle/Description/Image/canonical/robots and falls back to null", async () => {
		await adapter.content.save({
			id: "bad-meta",
			kind: "post",
			slug: "bad-meta",
			title: "T",
			metadata: {
				ogTitle: 123,
				ogDescription: { not: "a string" },
				ogImage: null,
				canonicalUrlOverride: false,
				robotsDirective: undefined,
			},
		});
		const override = getOverride("bad-meta");
		expect(override).toMatchObject({
			og_title: null,
			og_description: null,
			og_image: null,
			canonical_url_override: null,
			robots_directive: null,
		});
	});

	it("persists '' (not the metadata key string) for body/summary when neither record nor metadata supplies them", async () => {
		await adapter.content.save({
			id: "empty-fields",
			kind: "post",
			slug: "empty-fields",
			title: "T",
		});
		const override = getOverride("empty-fields");
		expect(override?.body).toBe("");
		expect(override?.excerpt).toBe("");
	});
});

describe("cloudflare savePageOrPost — revision snapshot is persisted with the saved fields", () => {
	it("writes a content_revisions row whose snapshot/body/title columns match the saved values (snapshot object is NOT empty)", async () => {
		await adapter.content.save({
			id: "rev-snap",
			kind: "post",
			slug: "rev-snap",
			title: "Snap Title",
			body: "<p>Snap body</p>",
			metadata: {
				seoTitle: "Snap SEO",
				metaDescription: "Snap Meta",
			},
		});

		const rev = db
			.prepare(
				"SELECT title, status, body, seo_title, meta_description FROM content_revisions WHERE slug = 'rev-snap' ORDER BY id DESC LIMIT 1",
			)
			.get() as Record<string, unknown> | undefined;
		expect(rev).toMatchObject({
			title: "Snap Title",
			body: "<p>Snap body</p>",
			seo_title: "Snap SEO",
			meta_description: "Snap Meta",
		});
	});
});

describe("cloudflare savePageOrPost — existing record preserves prior fields", () => {
	it("preserves the existing override's ogTitle/Description/Image/canonical/robots when the record's metadata omits them", async () => {
		// First save with full metadata to populate existing override fields.
		await adapter.content.save({
			id: "preserve",
			kind: "post",
			slug: "preserve",
			title: "T1",
			metadata: {
				ogTitle: "OG One",
				ogDescription: "OG Desc One",
				ogImage: "https://example.com/og1.png",
				canonicalUrlOverride: "https://example.com/canon1",
				robotsDirective: "index",
			},
		});

		// Second save WITHOUT those metadata fields. resolveContentFields should fall back
		// to the existing override row (NOT to null) for the og/canonical/robots fields.
		await adapter.content.save({
			id: "preserve",
			kind: "post",
			slug: "preserve",
			title: "T2",
			metadata: {},
		});

		const override = getOverride("preserve");
		expect(override).toMatchObject({
			title: "T2",
			og_title: "OG One",
			og_description: "OG Desc One",
			og_image: "https://example.com/og1.png",
			canonical_url_override: "https://example.com/canon1",
			robots_directive: "index",
		});
	});
});

tests/audit-log.test.ts.source:
import { beforeAll, describe, expect, it } from "vitest";
import { registerCms } from "../src/config.js";
import { listAuditEvents, recordAudit, recordAuditEvent } from "../src/sqlite-runtime/audit-log.js";
import { makeDb } from "./helpers/make-db.js";

let db: ReturnType<typeof makeDb>;

beforeAll(() => {
	db = makeDb();
});

describe("audit log", () => {
	it("records an audit event and retrieves it", () => {
		recordAuditEvent(db, {
			userEmail: "editor@example.com",
			action: "content.published",
			resourceType: "post",
			resourceId: "my-post",
			summary: "Published post my-post",
		});

		const events = listAuditEvents(db, { limit: 10 });
		expect(events.length).toBeGreaterThanOrEqual(1);

		const event = events.find((e) => e.resourceId === "my-post");
		expect(event).toBeDefined();
		expect(event?.userEmail).toBe("editor@example.com");
		expect(event?.action).toBe("content.published");
		expect(event?.resourceType).toBe("post");
		expect(event?.summary).toBe("Published post my-post");
		expect(event?.details).toBeNull();
	});

	it("stores and retrieves structured details JSON", () => {
		recordAuditEvent(db, {
			userEmail: "admin@example.com",
			action: "user.invited",
			resourceType: "user",
			resourceId: "new@example.com",
			summary: "Invited new@example.com",
			details: { role: "editor", invitedBy: "admin@example.com" },
		});

		const events = listAuditEvents(db, { resourceId: "new@example.com" });
		expect(events.length).toBe(1);
		expect(events[0].details).toEqual({
			role: "editor",
			invitedBy: "admin@example.com",
		});
	});

	it("filters by resourceId", () => {
		recordAuditEvent(db, {
			userEmail: "admin@example.com",
			action: "content.deleted",
			resourceType: "post",
			resourceId: "another-post",
			summary: "Deleted another-post",
		});

		const filtered = listAuditEvents(db, { resourceId: "my-post" });
		expect(filtered.every((e) => e.resourceId === "my-post")).toBe(true);
	});

	it("prunes audit events older than auditRetentionDays on write", () => {
		const freshDb = makeDb();
		registerCms({
			templateKeys: [],
			siteUrl: "https://example.com",
			seedPages: [],
			archives: [],
			translationStatus: [],
			auditRetentionDays: 30,
		});

		// Insert a very old event by manipulating created_at directly
		freshDb
			.prepare(
				`INSERT INTO audit_events (user_email, action, resource_type, resource_id, summary, created_at)
       VALUES ('old@test.local', 'content.published', 'post', 'old-post', 'Old post', datetime('now', '-31 days'))`,
			)
			.run();

		const before = (
			freshDb.prepare("SELECT COUNT(*) as n FROM audit_events").get() as {
				n: number;
			}
		).n;
		expect(before).toBe(1);

		// Writing a new event should trigger pruning
		recordAuditEvent(freshDb, {
			userEmail: "new@test.local",
			action: "content.published",
			resourceType: "post",
			resourceId: "new-post",
			summary: "New post",
		});

		const after = (
			freshDb.prepare("SELECT COUNT(*) as n FROM audit_events").get() as {
				n: number;
			}
		).n;
		// Old event should be pruned; new event should remain
		expect(after).toBe(1);
		const remaining = freshDb.prepare("SELECT resource_id FROM audit_events").get() as {
			resource_id: string;
		};
		expect(remaining.resource_id).toBe("new-post");
	});

	it("does NOT prune when auditRetentionDays is 0 (kills > 0 boundary mutant)", () => {
		const freshDb = makeDb();
		registerCms({
			templateKeys: [],
			siteUrl: "https://example.com",
			seedPages: [],
			archives: [],
			translationStatus: [],
			auditRetentionDays: 0,
		});
		freshDb
			.prepare(
				`INSERT INTO audit_events (user_email, action, resource_type, resource_id, summary, created_at)
       VALUES ('old@x', 'content.published', 'post', 'old', 'old', datetime('now', '-365 days'))`,
			)
			.run();
		recordAuditEvent(freshDb, {
			userEmail: "new@x",
			action: "content.published",
			resourceType: "post",
			resourceId: "new",
			summary: "new",
		});
		// Both rows survive — pruning skipped because retention=0.
		const count = (
			freshDb.prepare("SELECT COUNT(*) as n FROM audit_events").get() as {
				n: number;
			}
		).n;
		expect(count).toBe(2);
	});

	it("falls back to 90-day retention when auditRetentionDays is undefined (pins ?? 90 default)", () => {
		const freshDb = makeDb();
		registerCms({
			templateKeys: [],
			siteUrl: "https://example.com",
			seedPages: [],
			archives: [],
			translationStatus: [],
			// auditRetentionDays intentionally omitted
		});
		// Row at 91 days should be pruned by the default 90-day window.
		freshDb
			.prepare(
				`INSERT INTO audit_events (user_email, action, resource_type, resource_id, summary, created_at)
       VALUES ('old@x', 'content.published', 'post', '91d', 'old', datetime('now', '-91 days'))`,
			)
			.run();
		// Row at 89 days should survive.
		freshDb
			.prepare(
				`INSERT INTO audit_events (user_email, action, resource_type, resource_id, summary, created_at)
       VALUES ('keep@x', 'content.published', 'post', '89d', 'keep', datetime('now', '-89 days'))`,
			)
			.run();
		recordAuditEvent(freshDb, {
			userEmail: "trigger@x",
			action: "content.published",
			resourceType: "post",
			resourceId: "trigger",
			summary: "trigger prune",
		});
		const ids = (
			freshDb.prepare("SELECT resource_id as id FROM audit_events ORDER BY id").all() as {
				id: string;
			}[]
		).map((r) => r.id);
		expect(ids).toContain("89d");
		expect(ids).toContain("trigger");
		expect(ids).not.toContain("91d");
	});

	it("listAuditEvents default limit is 50 (pins ?? 50 default)", () => {
		const freshDb = makeDb();
		// 51 rows so a default of 50 returns 50 (mutant ?? 0 would return 0).
		for (let i = 0; i < 51; i++) {
			recordAuditEvent(freshDb, {
				userEmail: "x@y",
				action: "act",
				resourceType: "post",
				resourceId: `r-${i}`,
				summary: "s",
			});
		}
		const events = listAuditEvents(freshDb);
		expect(events.length).toBe(50);
	});

	it("listAuditEvents default offset is 0 (pins ?? 0 default)", () => {
		const freshDb = makeDb();
		for (let i = 0; i < 3; i++) {
			recordAuditEvent(freshDb, {
				userEmail: "x@y",
				action: "act",
				resourceType: "post",
				resourceId: `r-${i}`,
				summary: "s",
			});
		}
		// Without offset arg → offset 0 → 3 rows. Mutant ?? 1 → 2 rows.
		const events = listAuditEvents(freshDb, { limit: 10 });
		expect(events.length).toBe(3);
	});

	it("recordAudit wrapper forwards actor.email and resourceId to the underlying event", () => {
		const freshDb = makeDb();
		recordAudit(
			freshDb,
			{ email: "wrapper@example.com" },
			"test.action",
			"summary text",
			"page",
			"resource-x",
		);
		const events = listAuditEvents(freshDb, { resourceId: "resource-x" });
		expect(events.length).toBe(1);
		expect(events[0].userEmail).toBe("wrapper@example.com");
		expect(events[0].action).toBe("test.action");
		expect(events[0].summary).toBe("summary text");
		expect(events[0].resourceType).toBe("page");
		expect(events[0].resourceId).toBe("resource-x");
	});

	it("respects limit and offset", () => {
		// Insert several events
		for (let i = 0; i < 5; i++) {
			recordAuditEvent(db, {
				userEmail: "editor@example.com",
				action: "content.updated",
				resourceType: "post",
				resourceId: `post-${i}`,
				summary: `Updated post-${i}`,
			});
		}

		const page1 = listAuditEvents(db, { limit: 3, offset: 0 });
		const page2 = listAuditEvents(db, { limit: 3, offset: 3 });

		expect(page1.length).toBe(3);
		// Page 2 should have different events than page 1
		const page1Ids = page1.map((e) => e.id);
		const page2Ids = page2.map((e) => e.id);
		expect(page1Ids.some((id) => page2Ids.includes(id))).toBe(false);
	});
});

tests/sqlite-bootstrap-helpers.test.ts.source:
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import { checkpointSqliteWal, loadSqliteDatabase } from "../src/sqlite-bootstrap-helpers";

// A fully controllable stand-in for the `bun:sqlite` Database class. Setting
// `globalThis.Bun` routes loadSqliteDatabase() through the Bun branch so tests
// can drive checkpointSqliteWal's database interactions deterministically.
const { fakeBunDatabase, bunDbState } = vi.hoisted(() => {
	const bunDbState = {
		// Value returned by `PRAGMA wal_checkpoint(TRUNCATE)`.get()
		pragmaRow: { log: 0, checkpointed: 1 } as { log: number; checkpointed: number } | null,
		throwOnConstruct: false,
		// When true, the `bun:sqlite` mock factory throws — making the dynamic
		// import (and therefore loadSqliteDatabase) reject.
		importThrows: false,
		closeCalls: 0,
	};
	class FakeBunDatabase {
		constructor(public readonly filename: string) {
			if (bunDbState.throwOnConstruct) {
				throw new Error(`cannot open ${filename}`);
			}
		}
		prepare(_sql: string) {
			return {
				get: () => bunDbState.pragmaRow,
				run: () => ({}),
				all: () => [],
			};
		}
		exec() {}
		close() {
			bunDbState.closeCalls += 1;
		}
	}
	return { fakeBunDatabase: FakeBunDatabase, bunDbState };
});

vi.mock("bun:sqlite", () => ({
	// A getter so each access can be toggled to throw — accessing `m.Database`
	// inside loadSqliteDatabase then makes that function's promise reject.
	get Database() {
		if (bunDbState.importThrows) {
			throw new Error("bun:sqlite Database unavailable");
		}
		return fakeBunDatabase;
	},
}));

let testRoot: string;

beforeEach(() => {
	testRoot = mkdtempSync(join(tmpdir(), "astropress-helpers-test-"));
	bunDbState.pragmaRow = { log: 0, checkpointed: 1 };
	bunDbState.throwOnConstruct = false;
	bunDbState.importThrows = false;
	bunDbState.closeCalls = 0;
});

afterEach(() => {
	rmSync(testRoot, { recursive: true, force: true });
	delete (globalThis as { Bun?: unknown }).Bun;
	vi.resetModules();
});

describe("loadSqliteDatabase", () => {
	it("returns a constructor that can open an in-memory database", async () => {
		const DbClass = await loadSqliteDatabase();
		const db = new DbClass(":memory:");
		db.exec("CREATE TABLE t (id INTEGER PRIMARY KEY)");
		db.prepare("INSERT INTO t VALUES (1)").run();
		const row = db.prepare("SELECT id FROM t").get() as { id: number };
		expect(row.id).toBe(1);
		db.close();
	});

	it("returns the node:sqlite DatabaseSync constructor when not running under Bun", async () => {
		// Pins the node branch: a non-Bun runtime must resolve to node:sqlite's
		// DatabaseSync, never the bun:sqlite stub.
		expect("Bun" in globalThis).toBe(false);
		const DbClass = await loadSqliteDatabase();
		expect(DbClass).not.toBe(fakeBunDatabase);
		expect(DbClass.name).toBe("DatabaseSync");
	});

	it("returns the bun:sqlite Database constructor when running under Bun", async () => {
		// Pins the `"Bun" in globalThis` guard and the `bun:sqlite` import: with
		// Bun present, loadSqliteDatabase must resolve to bun:sqlite's Database.
		(globalThis as { Bun?: unknown }).Bun = {};
		const DbClass = await loadSqliteDatabase();
		expect(DbClass).toBe(fakeBunDatabase);
	});
});

describe("checkpointSqliteWal", () => {
	it("returns true and emits no warning for a real WAL-mode SQLite file", async () => {
		const DbClass = await loadSqliteDatabase();
		const dbPath = join(testRoot, "real.sqlite");

		// Create a real SQLite DB in WAL mode with some data
		const db = new DbClass(dbPath);
		db.prepare("PRAGMA journal_mode = WAL").get();
		db.exec("CREATE TABLE items (id INTEGER PRIMARY KEY, val TEXT)");
		db.prepare("INSERT INTO items VALUES (1, 'hello')").run();
		db.close();

		const warnings: string[] = [];
		const result = await checkpointSqliteWal(dbPath, (msg) => warnings.push(msg));

		expect(result).toBe(true);
		expect(warnings).toHaveLength(0);
	});

	it("returns false and warns when the file is not a valid SQLite database", async () => {
		const badPath = join(testRoot, "bad.sqlite");
		writeFileSync(badPath, "this is not sqlite", "utf8");

		const warnings: string[] = [];
		const result = await checkpointSqliteWal(badPath, (msg) => warnings.push(msg));

		expect(result).toBe(false);
		expect(warnings.length).toBeGreaterThan(0);
		expect(warnings[0]).toContain("bad.sqlite");
	});

	it("returns false (not a rejection) when the driver constructor itself throws on an unopenable path", async () => {
		// Path under a non-existent directory makes node:sqlite throw inside
		// `new DatabaseSync(path)` synchronously, leaving `db` undefined inside
		// the checkpoint helper. The finally block must still resolve cleanly —
		// `db?.close()`'s optional chain is load-bearing here.
		const unopenablePath = join(testRoot, "no-such-dir", "db.sqlite");

		const warnings: string[] = [];
		await expect(checkpointSqliteWal(unopenablePath, (msg) => warnings.push(msg))).resolves.toBe(
			false,
		);
		expect(warnings.length).toBeGreaterThan(0);
		expect(warnings[0]).toContain("WAL checkpoint failed");
	});

	it("warns and returns false when loadSqliteDatabase rejects", async () => {
		// Drives the first catch block: with Bun present but `bun:sqlite`'s
		// Database export unresolvable, loadSqliteDatabase rejects and
		// checkpointSqliteWal must emit the "checkpoint skipped" warning.
		bunDbState.importThrows = true;
		(globalThis as { Bun?: unknown }).Bun = {};

		const warnings: string[] = [];
		const result = await checkpointSqliteWal("/tmp/skipme.sqlite", (msg) => warnings.push(msg));

		expect(result).toBe(false);
		expect(warnings).toHaveLength(1);
		expect(warnings[0]).toContain("SQLite WAL checkpoint skipped for /tmp/skipme.sqlite");
	});

	it("returns false without warning when the WAL is not fully flushed (log > 0)", async () => {
		// Pins `row.log === 0`: a non-zero log page count means the checkpoint
		// did not fully truncate, so the helper must report false — and must NOT
		// warn (no error occurred, the WAL simply wasn't fully flushed).
		bunDbState.pragmaRow = { log: 3, checkpointed: 0 };
		(globalThis as { Bun?: unknown }).Bun = {};

		const warnings: string[] = [];
		const result = await checkpointSqliteWal("/tmp/partial.sqlite", (msg) => warnings.push(msg));

		expect(result).toBe(false);
		expect(warnings).toHaveLength(0);
	});

	it("returns false without warning when the checkpoint pragma yields no row", async () => {
		// Pins `row != null`: a null pragma result must short-circuit to false
		// without dereferencing `row.log` (which would throw and warn).
		bunDbState.pragmaRow = null;
		(globalThis as { Bun?: unknown }).Bun = {};

		const warnings: string[] = [];
		const result = await checkpointSqliteWal("/tmp/norow.sqlite", (msg) => warnings.push(msg));

		expect(result).toBe(false);
		expect(warnings).toHaveLength(0);
	});

	it("returns true when the WAL is fully flushed (log === 0)", async () => {
		bunDbState.pragmaRow = { log: 0, checkpointed: 5 };
		(globalThis as { Bun?: unknown }).Bun = {};

		const warnings: string[] = [];
		const result = await checkpointSqliteWal("/tmp/clean.sqlite", (msg) => warnings.push(msg));

		expect(result).toBe(true);
		expect(warnings).toHaveLength(0);
	});

	it("closes the database in the finally block after a successful checkpoint", async () => {
		bunDbState.pragmaRow = { log: 0, checkpointed: 1 };
		(globalThis as { Bun?: unknown }).Bun = {};

		await checkpointSqliteWal("/tmp/closeme.sqlite", () => {});

		expect(bunDbState.closeCalls).toBe(1);
	});
});

tests/build-time-content-loader.test.ts.source:
import {
	type AstropressPlatformAdapter,
	assertProviderContract,
	type ContentListOptions,
	type ContentStoreRecord,
	normalizeProviderCapabilities,
} from "@astropress-diy/astropress";
import { describe, expect, it } from "vitest";
import { createAstropressBuildTimeLoader } from "../src/build-time-content-loader";

function makeTestRecord(
	overrides: Partial<ContentStoreRecord> &
		Pick<ContentStoreRecord, "id" | "kind" | "slug" | "status">,
): ContentStoreRecord {
	return {
		title: overrides.title ?? `Title for ${overrides.slug}`,
		body: null,
		locale: null,
		metadata: {},
		...overrides,
	};
}

function createFilteringAdapter(records: ContentStoreRecord[]): AstropressPlatformAdapter {
	return assertProviderContract({
		capabilities: normalizeProviderCapabilities({ name: "test-filtering" }),
		content: {
			async list(kind, options?: ContentListOptions) {
				let results = [...records];

				if (kind) {
					results = results.filter((r) => r.kind === kind);
				}

				if (options?.status && options.status !== "all") {
					results = results.filter((r) => r.status === options.status);
				}

				if (options?.locale) {
					results = results.filter((r) => !r.locale || r.locale === options.locale);
				}

				if (options?.offset) {
					results = results.slice(options.offset);
				}

				if (options?.limit !== undefined) {
					results = results.slice(0, options.limit);
				}

				return results;
			},
			async get(id) {
				return records.find((r) => r.id === id) ?? null;
			},
			async save(record) {
				return record;
			},
			async delete() {},
		},
		media: {
			async put(a) {
				return a;
			},
			async get() {
				return null;
			},
			async delete() {},
		},
		revisions: {
			async list() {
				return [];
			},
			async append(r) {
				return r;
			},
		},
		auth: {
			async signIn() {
				return null;
			},
			async signOut() {},
			async getSession() {
				return null;
			},
		},
	});
}

describe("ContentListOptions", () => {
	it("list accepts status filter and returns only published records", async () => {
		const records: ContentStoreRecord[] = [
			makeTestRecord({
				id: "a",
				kind: "post",
				slug: "hello-world",
				status: "published",
			}),
			makeTestRecord({
				id: "b",
				kind: "post",
				slug: "unpublished",
				status: "draft",
			}),
		];
		const adapter = createFilteringAdapter(records);

		const published = await adapter.content.list("post", {
			status: "published",
		});
		expect(published.map((r) => r.slug)).toEqual(["hello-world"]);
	});

	it("list with no status filter returns all records", async () => {
		const records: ContentStoreRecord[] = [
			makeTestRecord({
				id: "a",
				kind: "post",
				slug: "hello-world",
				status: "published",
			}),
			makeTestRecord({
				id: "b",
				kind: "post",
				slug: "draft-post",
				status: "draft",
			}),
		];
		const adapter = createFilteringAdapter(records);

		const all = await adapter.content.list("post");
		expect(all).toHaveLength(2);
	});

	it("list with kind and status filter returns only matching records", async () => {
		const records: ContentStoreRecord[] = [
			makeTestRecord({
				id: "a",
				kind: "post",
				slug: "post-1",
				status: "published",
			}),
			makeTestRecord({
				id: "b",
				kind: "page",
				slug: "page-1",
				status: "published",
			}),
			makeTestRecord({
				id: "c",
				kind: "post",
				slug: "post-draft",
				status: "draft",
			}),
		];
		const adapter = createFilteringAdapter(records);

		const posts = await adapter.content.list("post", { status: "published" });
		expect(posts.map((r) => r.kind)).toEqual(["post"]);
		expect(posts.map((r) => r.slug)).toEqual(["post-1"]);
	});

	it("list respects limit and offset", async () => {
		const records: ContentStoreRecord[] = Array.from({ length: 10 }, (_, i) =>
			makeTestRecord({
				id: `post-${i}`,
				kind: "post",
				slug: `post-${i}`,
				status: "published",
			}),
		);
		const adapter = createFilteringAdapter(records);

		const page1 = await adapter.content.list("post", {
			status: "published",
			limit: 3,
			offset: 0,
		});
		expect(page1).toHaveLength(3);

		const page2 = await adapter.content.list("post", {
			status: "published",
			limit: 3,
			offset: 3,
		});
		expect(page2).toHaveLength(3);
		expect(page2[0].slug).toBe("post-3");
	});
});

describe("createAstropressBuildTimeLoader", () => {
	it("returns a loader with posts() and pages() factories", () => {
		const adapter = createFilteringAdapter([]);
		const loader = createAstropressBuildTimeLoader(adapter);

		expect(typeof loader.posts).toBe("function");
		expect(typeof loader.pages).toBe("function");
	});

	it("posts loader fetches only published posts", async () => {
		const records: ContentStoreRecord[] = [
			makeTestRecord({
				id: "a",
				kind: "post",
				slug: "live-post",
				status: "published",
			}),
			makeTestRecord({
				id: "b",
				kind: "post",
				slug: "draft-post",
				status: "draft",
			}),
			makeTestRecord({
				id: "c",
				kind: "page",
				slug: "a-page",
				status: "published",
			}),
		];
		const adapter = createFilteringAdapter(records);
		const loader = createAstropressBuildTimeLoader(adapter);

		const posts = await loader.posts().load();
		expect(posts).toHaveLength(1);
		expect(posts[0].slug).toBe("live-post");
		expect(posts[0].kind).toBe("post");
	});

	it("pages loader fetches only published pages", async () => {
		const records: ContentStoreRecord[] = [
			makeTestRecord({
				id: "a",
				kind: "page",
				slug: "about",
				status: "published",
			}),
			makeTestRecord({
				id: "b",
				kind: "page",
				slug: "draft-page",
				status: "draft",
			}),
			makeTestRecord({
				id: "c",
				kind: "post",
				slug: "a-post",
				status: "published",
			}),
		];
		const adapter = createFilteringAdapter(records);
		const loader = createAstropressBuildTimeLoader(adapter);

		const pages = await loader.pages().load();
		expect(pages).toHaveLength(1);
		expect(pages[0].slug).toBe("about");
		expect(pages[0].kind).toBe("page");
	});

	it("each returned record has the required ContentStoreRecord shape", async () => {
		const records: ContentStoreRecord[] = [
			makeTestRecord({
				id: "post-1",
				kind: "post",
				slug: "post-1",
				status: "published",
				title: "Hello World",
			}),
		];
		const adapter = createFilteringAdapter(records);
		const loader = createAstropressBuildTimeLoader(adapter);

		const posts = await loader.posts().load();
		const record = posts[0];

		expect(record).toHaveProperty("id");
		expect(record).toHaveProperty("kind");
		expect(record).toHaveProperty("slug");
		expect(record).toHaveProperty("status");
		expect(record).toHaveProperty("title");
	});

	it("loader kind property matches the content kind", () => {
		const adapter = createFilteringAdapter([]);
		const loader = createAstropressBuildTimeLoader(adapter);

		expect(loader.posts().kind).toBe("post");
		expect(loader.pages().kind).toBe("page");
	});

	it("respects locale option when provided", async () => {
		const records: ContentStoreRecord[] = [
			makeTestRecord({
				id: "a",
				kind: "post",
				slug: "en-post",
				status: "published",
				locale: "en",
			}),
			makeTestRecord({
				id: "b",
				kind: "post",
				slug: "fr-post",
				status: "published",
				locale: "fr",
			}),
		];
		const adapter = createFilteringAdapter(records);
		const loader = createAstropressBuildTimeLoader(adapter, { locale: "en" });

		const posts = await loader.posts().load();
		expect(posts).toHaveLength(1);
		expect(posts[0].slug).toBe("en-post");
	});
});

tests/api-token-store.test.ts.source:
import { describe, expect, it } from "vitest";

import type { ApiScope, ApiTokenRecord, ApiTokenStore } from "../src/platform-contracts";
import { createApiTokenStore } from "../src/sqlite-runtime/api-tokens.js";
import { hashOpaqueToken } from "../src/sqlite-runtime/utils.js";
import { makeDb } from "./helpers/make-db.js";

// ─── ApiTokenRecord shape ─────────────────────────────────────────────────────

describe("ApiTokenRecord shape", () => {
	it("has all required fields", () => {
		const record: ApiTokenRecord = {
			id: "tok_01",
			label: "AI assistant",
			scopes: ["content:read"],
			createdAt: new Date().toISOString(),
		};

		expect(record.id).toBe("tok_01");
		expect(record.label).toBe("AI assistant");
		expect(record.scopes).toContain("content:read");
		expect(record.revokedAt).toBeUndefined();
	});

	it("supports all defined scopes", () => {
		const allScopes: ApiScope[] = [
			"content:read",
			"content:write",
			"media:read",
			"media:write",
			"settings:read",
			"webhooks:manage",
			"import:write",
		];
		const record: ApiTokenRecord = {
			id: "tok_02",
			label: "Full access",
			scopes: allScopes,
			createdAt: new Date().toISOString(),
		};
		expect(record.scopes).toHaveLength(7);
	});

	it("optional fields are truly optional", () => {
		const minimal: ApiTokenRecord = {
			id: "tok_03",
			label: "Minimal",
			scopes: ["settings:read"],
			createdAt: "2026-01-01T00:00:00Z",
		};
		expect(minimal.expiresAt).toBeUndefined();
		expect(minimal.lastUsedAt).toBeUndefined();
		expect(minimal.revokedAt).toBeUndefined();
	});
});

describe("ApiTokenStore SQLite implementation", () => {
	it("create: stores hashed token and returns raw token once", async () => {
		const db = makeDb();
		const store = createApiTokenStore(db);

		const { record, rawToken } = await store.create({
			label: "test",
			scopes: ["content:read"],
		});

		expect(rawToken.length).toBeGreaterThanOrEqual(32);
		expect(record.label).toBe("test");
		expect(record.scopes).toEqual(["content:read"]);
		expect(record.revokedAt).toBeNull();

		// Hash stored, not raw token
		const row = db.prepare("SELECT token_hash FROM api_tokens WHERE id = ?").get(record.id) as {
			token_hash: string;
		};
		expect(row.token_hash).toBe(hashOpaqueToken(rawToken));
		expect(row.token_hash).not.toBe(rawToken);
	});

	it("list: returns tokens without token_hash", async () => {
		const db = makeDb();
		const store = createApiTokenStore(db);
		await store.create({ label: "alpha", scopes: ["content:read"] });
		await store.create({ label: "beta", scopes: ["media:read"] });

		const tokens = await store.list();
		expect(tokens).toHaveLength(2);
		const labels = tokens.map((t) => t.label);
		expect(labels).toContain("alpha");
		expect(labels).toContain("beta");
		// No hash exposed
		for (const token of tokens) {
			expect((token as Record<string, unknown>).token_hash).toBeUndefined();
		}
	});

	it("verify: valid unrevoked token succeeds and updates lastUsedAt", async () => {
		const db = makeDb();
		const store = createApiTokenStore(db);
		const { rawToken } = await store.create({
			label: "agent",
			scopes: ["content:read"],
		});

		const result = await store.verify(rawToken);
		expect(result.valid).toBe(true);
		if (!result.valid) throw new Error("expected valid");

		expect(result.record.label).toBe("agent");
		expect(result.record.lastUsedAt).not.toBeNull();
	});

	it("verify: revoked token returns { valid: false }", async () => {
		const db = makeDb();
		const store = createApiTokenStore(db);
		const { record, rawToken } = await store.create({
			label: "short-lived",
			scopes: ["settings:read"],
		});

		await store.revoke(record.id);
		const result = await store.verify(rawToken);
		expect(result.valid).toBe(false);
	});

	it("verify: unknown token returns { valid: false }", async () => {
		const db = makeDb();
		const store = createApiTokenStore(db);
		const result = await store.verify("completely-unknown-token");
		expect(result.valid).toBe(false);
	});

	it("revoke: sets revokedAt timestamp", async () => {
		const db = makeDb();
		const store = createApiTokenStore(db);
		const { record } = await store.create({
			label: "revoke-me",
			scopes: ["content:write"],
		});

		await store.revoke(record.id);
		const tokens = await store.list();
		const revoked = tokens.find((t) => t.id === record.id);
		expect(revoked?.revokedAt).not.toBeNull();
	});

	it("verify: expired token returns { valid: false } with 'expired' reason", async () => {
		const db = makeDb();
		const store = createApiTokenStore(db);
		const past = new Date(Date.now() - 60_000).toISOString();
		const { rawToken } = await store.create({
			label: "expired",
			scopes: ["content:read"],
			expiresAt: past,
		});
		const result = await store.verify(rawToken);
		expect(result.valid).toBe(false);
		if (result.valid) throw new Error("expected invalid");
		expect(result.reason).toMatch(/expired/i);
	});

	it("verify: future-expiry token still verifies (pins < boundary on expires_at)", async () => {
		const db = makeDb();
		const store = createApiTokenStore(db);
		const future = new Date(Date.now() + 60_000).toISOString();
		const { rawToken, record } = await store.create({
			label: "future",
			scopes: ["content:read"],
			expiresAt: future,
		});
		const result = await store.verify(rawToken);
		expect(result.valid).toBe(true);
		if (!result.valid) throw new Error("expected valid");
		expect(result.record.expiresAt).toBe(future);
		expect(record.expiresAt).toBe(future);
	});

	it("create: persists expiresAt in the returned record (pins ?? null fallback)", async () => {
		const db = makeDb();
		const store = createApiTokenStore(db);
		const { record } = await store.create({
			label: "no-expiry",
			scopes: ["content:read"],
		});
		expect(record.expiresAt).toBeNull();
	});

	it("verify: revoked token reason mentions 'revoked' (pins reason literal)", async () => {
		const db = makeDb();
		const store = createApiTokenStore(db);
		const { record, rawToken } = await store.create({
			label: "revoke-reason",
			scopes: ["content:read"],
		});
		await store.revoke(record.id);
		const result = await store.verify(rawToken);
		if (result.valid) throw new Error("expected invalid");
		expect(result.reason).toMatch(/revoked/i);
	});

	it("verify: unknown token reason mentions 'not found' (pins reason literal)", async () => {
		const db = makeDb();
		const store = createApiTokenStore(db);
		const result = await store.verify("nonexistent-token");
		if (result.valid) throw new Error("expected invalid");
		expect(result.reason).toMatch(/not found/i);
	});

	it("list: revoked tokens still appear in list (for admin display)", async () => {
		const db = makeDb();
		const store = createApiTokenStore(db);
		const { record } = await store.create({
			label: "revocable",
			scopes: ["content:read"],
		});
		await store.revoke(record.id);

		const tokens = await store.list();
		expect(tokens.some((t) => t.id === record.id)).toBe(true);
	});
});

// Type-level smoke test: ensure the interface is structurally correct
function assertApiTokenStoreShape(store: ApiTokenStore) {
	const _create = store.create;
	const _list = store.list;
	const _verify = store.verify;
	const _revoke = store.revoke;
	return { _create, _list, _verify, _revoke };
}

// Unused reference satisfies TypeScript without needing a real implementation
void assertApiTokenStoreShape;

