import { describe, expect, it, vi } from "vitest";
import { createAstropressLocalMediaRepository } from "../src/local-media-repository-factory";

// Mock filesystem ops — this test covers repository orchestration logic only.
// local-media-storage.test.ts covers the storage layer in isolation. Without
// this mock, isolate:false coverage runs inherit a deleted temp dir from that
// test's afterEach, causing ENOENT on the module-level uploadsDir constant.
vi.mock("../src/local-media-storage", () => ({
	createLocalMediaUpload: vi.fn(() => ({
		ok: true as const,
		asset: {
			id: "media-test-uuid",
			storedFilename: "media-test-uuid",
			diskPath: "/var/astropress-mock/media-test-uuid",
			publicPath: "/images/uploads/media-test-uuid",
			r2Key: "media/media-test-uuid",
			mimeType: "image/png",
			fileSize: 3,
			title: "Test",
			altText: "Alt",
		},
	})),
	deleteLocalMediaUpload: vi.fn(),
}));

describe("local media repository factory", () => {
	it("creates and deletes local media through package-owned storage helpers", () => {
		const insertStoredMediaAsset = vi.fn();
		const getStoredMediaDeletionCandidate = vi.fn(() => ({
			localPath: "/images/uploads/test.png",
		}));
		const markStoredMediaDeleted = vi.fn(() => true);
		const recordMediaAudit = vi.fn();

		const repository = createAstropressLocalMediaRepository({
			listMediaAssets: vi.fn(() => []),
			updateMediaAsset: vi.fn(() => ({ ok: true })),
			insertStoredMediaAsset,
			getStoredMediaDeletionCandidate,
			markStoredMediaDeleted,
			recordMediaAudit,
		});

		const upload = repository.createMediaAsset(
			{
				filename: "test.png",
				bytes: new Uint8Array([1, 2, 3]),
				mimeType: "image/png",
				title: "Test",
				altText: "Alt",
			},
			{ email: "editor@example.com", name: "Editor", role: "editor" },
		);

		expect(upload.ok).toBe(true);
		if (!upload.ok) {
			return;
		}

		expect(insertStoredMediaAsset).toHaveBeenCalledTimes(1);
		expect(recordMediaAudit).toHaveBeenCalledWith(
			expect.objectContaining({
				action: "media.upload",
				targetId: upload.id,
			}),
		);

		const deletion = repository.deleteMediaAsset(upload.id, {
			email: "editor@example.com",
			name: "Editor",
			role: "editor",
		});

		expect(deletion).toEqual({ ok: true });
		expect(getStoredMediaDeletionCandidate).toHaveBeenCalledWith(upload.id);
		expect(markStoredMediaDeleted).toHaveBeenCalledWith(upload.id);
		expect(recordMediaAudit).toHaveBeenCalledWith(
			expect.objectContaining({
				action: "media.delete",
				targetId: upload.id,
			}),
		);
	});

	it("upload audit summary contains 'Uploaded media asset <storedFilename>.' (pins L35 template)", () => {
		const insertStoredMediaAsset = vi.fn();
		const recordMediaAudit = vi.fn();
		const repository = createAstropressLocalMediaRepository({
			listMediaAssets: vi.fn(() => []),
			updateMediaAsset: vi.fn(() => ({ ok: true })),
			insertStoredMediaAsset,
			getStoredMediaDeletionCandidate: vi.fn(),
			markStoredMediaDeleted: vi.fn(),
			recordMediaAudit,
		});
		repository.createMediaAsset(
			{
				filename: "test.png",
				bytes: new Uint8Array([1, 2, 3]),
				mimeType: "image/png",
			},
			{ email: "e@x.com", name: "E", role: "editor" },
		);
		const call = recordMediaAudit.mock.calls[0]?.[0] as { summary: string };
		expect(call.summary).toBe("Uploaded media asset media-test-uuid.");
	});

	it("deleteMediaAsset returns ok:false with the 'could not be deleted' error when row is missing (pins L48 !row + L51 error message)", () => {
		const markStoredMediaDeleted = vi.fn();
		const recordMediaAudit = vi.fn();
		const repository = createAstropressLocalMediaRepository({
			listMediaAssets: vi.fn(() => []),
			updateMediaAsset: vi.fn(() => ({ ok: true })),
			insertStoredMediaAsset: vi.fn(),
			getStoredMediaDeletionCandidate: vi.fn(() => null),
			markStoredMediaDeleted,
			recordMediaAudit,
		});
		const result = repository.deleteMediaAsset("missing-id", {
			email: "e@x.com",
			name: "E",
			role: "editor",
		});
		expect(result.ok).toBe(false);
		if (!result.ok) {
			expect(result.error).toBe("The selected media asset could not be deleted.");
		}
		// Mutating `if (!row)` to `if (false)` (or emptying its block) would skip
		// the early-return and continue into markStoredMediaDeleted + audit. The
		// observable error message happens to match the L56 path, so we must
		// pin the side-effects: neither markStoredMediaDeleted nor recordMediaAudit
		// should fire when the row is missing.
		expect(markStoredMediaDeleted).not.toHaveBeenCalled();
		expect(recordMediaAudit).not.toHaveBeenCalled();
	});

	it("delete audit summary contains 'Deleted media asset <assetId>.' (pins L67 StringLiteral)", () => {
		const recordMediaAudit = vi.fn();
		const repository = createAstropressLocalMediaRepository({
			listMediaAssets: vi.fn(() => []),
			updateMediaAsset: vi.fn(() => ({ ok: true })),
			insertStoredMediaAsset: vi.fn(),
			getStoredMediaDeletionCandidate: vi.fn(() => ({ localPath: "/some/path" })),
			markStoredMediaDeleted: vi.fn(() => true),
			recordMediaAudit,
		});
		repository.deleteMediaAsset("asset-123", {
			email: "e@x.com",
			name: "E",
			role: "editor",
		});
		const deleteCall = recordMediaAudit.mock.calls.find(
			(args) => (args[0] as { action: string }).action === "media.delete",
		);
		expect((deleteCall![0] as { summary: string }).summary).toBe("Deleted media asset asset-123.");
	});

	it("deleteMediaAsset returns ok:false when markStoredMediaDeleted returns false (pins L56 !deleted + L59 error message)", () => {
		const repository = createAstropressLocalMediaRepository({
			listMediaAssets: vi.fn(() => []),
			updateMediaAsset: vi.fn(() => ({ ok: true })),
			insertStoredMediaAsset: vi.fn(),
			getStoredMediaDeletionCandidate: vi.fn(() => ({ localPath: "/some/path" })),
			markStoredMediaDeleted: vi.fn(() => false),
			recordMediaAudit: vi.fn(),
		});
		const result = repository.deleteMediaAsset("found-id", {
			email: "e@x.com",
			name: "E",
			role: "editor",
		});
		expect(result.ok).toBe(false);
		if (!result.ok) {
			expect(result.error).toBe("The selected media asset could not be deleted.");
		}
	});
});

tests/d1-content-scheduling.test.ts.source:
import type { DatabaseSync } from "node:sqlite";

import { beforeEach, describe, expect, it } from "vitest";

import { createD1SchedulingPart } from "../src/d1-store-content.js";
import { makeDb } from "./helpers/make-db.js";
import { SqliteBackedD1Database } from "./helpers/provider-test-fixtures.js";

function seedEntry(db: DatabaseSync, slug: string) {
	db.prepare(
		`INSERT INTO content_entries (slug, legacy_url, title, kind, template_key, source_html_path, updated_at)
     VALUES (?, ?, ?, 'post', 'content', 'runtime://content/' || ?, CURRENT_TIMESTAMP)`,
	).run(slug, `/${slug}`, `Title for ${slug}`, slug);
}

function makeScheduling(db: DatabaseSync) {
	return createD1SchedulingPart(new SqliteBackedD1Database(db));
}

describe("D1 scheduling — schedulePublish", () => {
	let db: DatabaseSync;

	beforeEach(() => {
		db = makeDb();
		seedEntry(db, "my-post");
	});

	it("creates an override with scheduled_at when none exists", async () => {
		const scheduling = makeScheduling(db);
		const future = new Date(Date.now() + 60_000).toISOString();
		await scheduling.schedulePublish("my-post", future);

		const row = db
			.prepare("SELECT slug, status, scheduled_at FROM content_overrides WHERE slug = ?")
			.get("my-post") as {
			slug: string;
			status: string;
			scheduled_at: string;
		};
		expect(row).toBeDefined();
		expect(row.slug).toBe("my-post");
		expect(row.status).toBe("draft");
		expect(row.scheduled_at).toBe(future);
	});

	it("updates existing override's scheduled_at", async () => {
		const scheduling = makeScheduling(db);
		db.prepare(
			`INSERT INTO content_overrides (slug, title, status, seo_title, meta_description, updated_at, updated_by)
       VALUES ('my-post', 'Title for my-post', 'draft', 'Title for my-post', '', CURRENT_TIMESTAMP, 'test@test.com')`,
		).run();

		const future = new Date(Date.now() + 120_000).toISOString();
		await scheduling.schedulePublish("my-post", future);

		const row = db
			.prepare("SELECT scheduled_at FROM content_overrides WHERE slug = ?")
			.get("my-post") as {
			scheduled_at: string;
		};
		expect(row.scheduled_at).toBe(future);
	});
});

describe("D1 scheduling — listScheduled", () => {
	let db: DatabaseSync;

	beforeEach(() => {
		db = makeDb();
		seedEntry(db, "future-post");
		seedEntry(db, "past-post");
	});

	it("returns only future-scheduled entries", async () => {
		const scheduling = makeScheduling(db);
		const future = new Date(Date.now() + 60_000).toISOString();
		const past = new Date(Date.now() - 60_000).toISOString();

		db.prepare(
			`INSERT INTO content_overrides (slug, title, status, scheduled_at, seo_title, meta_description, updated_at, updated_by)
       VALUES ('future-post', 'Future Post', 'draft', ?, 'Future Post', '', CURRENT_TIMESTAMP, 'scheduler')`,
		).run(future);
		db.prepare(
			`INSERT INTO content_overrides (slug, title, status, scheduled_at, seo_title, meta_description, updated_at, updated_by)
       VALUES ('past-post', 'Past Post', 'draft', ?, 'Past Post', '', CURRENT_TIMESTAMP, 'scheduler')`,
		).run(past);

		const list = await scheduling.listScheduled();
		expect(list).toHaveLength(1);
		expect(list[0].slug).toBe("future-post");
		expect(list[0].scheduledAt).toBe(future);
	});

	it("returns empty array when no scheduled entries", async () => {
		const list = await makeScheduling(db).listScheduled();
		expect(list).toEqual([]);
	});
});

describe("D1 scheduling — cancelScheduledPublish", () => {
	it("clears scheduled_at without changing status", async () => {
		const db = makeDb();
		seedEntry(db, "cancel-post");
		const future = new Date(Date.now() + 60_000).toISOString();
		db.prepare(
			`INSERT INTO content_overrides (slug, title, status, scheduled_at, seo_title, meta_description, updated_at, updated_by)
       VALUES ('cancel-post', 'Cancel Post', 'draft', ?, 'Cancel Post', '', CURRENT_TIMESTAMP, 'scheduler')`,
		).run(future);

		await makeScheduling(db).cancelScheduledPublish("cancel-post");

		const row = db
			.prepare("SELECT status, scheduled_at FROM content_overrides WHERE slug = ?")
			.get("cancel-post") as {
			status: string;
			scheduled_at: string | null;
		};
		expect(row.status).toBe("draft");
		expect(row.scheduled_at).toBeNull();
	});
});

describe("D1 scheduling — runScheduledPublishes", () => {
	it("publishes past-due entries and returns count", async () => {
		const db = makeDb();
		seedEntry(db, "due-post");
		seedEntry(db, "not-due-post");
		const past = new Date(Date.now() - 60_000).toISOString();
		const future = new Date(Date.now() + 60_000).toISOString();

		db.prepare(
			`INSERT INTO content_overrides (slug, title, status, scheduled_at, seo_title, meta_description, updated_at, updated_by)
       VALUES ('due-post', 'Due Post', 'draft', ?, 'Due Post', '', CURRENT_TIMESTAMP, 'scheduler')`,
		).run(past);
		db.prepare(
			`INSERT INTO content_overrides (slug, title, status, scheduled_at, seo_title, meta_description, updated_at, updated_by)
       VALUES ('not-due-post', 'Not Due Post', 'draft', ?, 'Not Due Post', '', CURRENT_TIMESTAMP, 'scheduler')`,
		).run(future);

		const count = await makeScheduling(db).runScheduledPublishes();
		expect(count).toBe(1);

		const due = db
			.prepare("SELECT status, scheduled_at FROM content_overrides WHERE slug = ?")
			.get("due-post") as {
			status: string;
			scheduled_at: string | null;
		};
		expect(due.status).toBe("published");
		expect(due.scheduled_at).toBeNull();

		const notDue = db
			.prepare("SELECT status, scheduled_at FROM content_overrides WHERE slug = ?")
			.get("not-due-post") as {
			status: string;
			scheduled_at: string;
		};
		expect(notDue.status).toBe("draft");
		expect(notDue.scheduled_at).toBe(future);
	});

	it("returns 0 when no entries are due", async () => {
		const db = makeDb();
		const count = await makeScheduling(db).runScheduledPublishes();
		expect(count).toBe(0);
	});
});

