import { describe, expect, it } from "vitest";
import { createAstropressInMemoryPlatformAdapter } from "../src/in-memory-platform-adapter";
import type {
	ContentStoreRecord,
	MediaAssetRecord,
	RevisionRecord,
} from "../src/platform-contracts";

const minimalCapabilities = { name: "in-memory-test" };

function makeAdapter() {
	return createAstropressInMemoryPlatformAdapter({
		capabilities: minimalCapabilities,
	});
}

describe("createAstropressInMemoryPlatformAdapter — content store", () => {
	it("save / get / list / delete round-trip a content record", async () => {
		const adapter = makeAdapter();
		const record: ContentStoreRecord = {
			id: "post-1",
			kind: "post",
			title: "T",
			body: "B",
			updatedAt: "2026-01-01",
		};
		expect(await adapter.content.list()).toEqual([]);
		expect(await adapter.content.save(record)).toEqual(record);
		expect(await adapter.content.get("post-1")).toEqual(record);
		expect(await adapter.content.list()).toEqual([record]);
		await adapter.content.delete("post-1");
		expect(await adapter.content.get("post-1")).toBeNull();
		expect(await adapter.content.list()).toEqual([]);
	});

	it("list filters by kind when supplied", async () => {
		const adapter = makeAdapter();
		await adapter.content.save({
			id: "p1",
			kind: "post",
			title: "P",
			body: "",
			updatedAt: "2026-01-01",
		});
		await adapter.content.save({
			id: "g1",
			kind: "page",
			title: "G",
			body: "",
			updatedAt: "2026-01-01",
		});
		expect((await adapter.content.list("post")).map((r) => r.id)).toEqual(["p1"]);
		expect((await adapter.content.list("page")).map((r) => r.id)).toEqual(["g1"]);
	});
});

describe("createAstropressInMemoryPlatformAdapter — media store", () => {
	it("put / get / delete round-trip a media asset", async () => {
		const adapter = makeAdapter();
		const asset: MediaAssetRecord = {
			id: "m1",
			url: "/m1.png",
			mimeType: "image/png",
		};
		expect(await adapter.media.put(asset)).toEqual(asset);
		expect(await adapter.media.get("m1")).toEqual(asset);
		await adapter.media.delete("m1");
		expect(await adapter.media.get("m1")).toBeNull();
	});
});

describe("createAstropressInMemoryPlatformAdapter — revision store", () => {
	it("list returns [] for an unknown record id and append accumulates per recordId", async () => {
		const adapter = makeAdapter();
		expect(await adapter.revisions.list("missing")).toEqual([]);

		const r1: RevisionRecord = {
			id: "rev-1",
			recordId: "post-1",
			savedAt: "2026-01-01",
			payload: { title: "v1" },
		};
		const r2: RevisionRecord = {
			id: "rev-2",
			recordId: "post-1",
			savedAt: "2026-01-02",
			payload: { title: "v2" },
		};
		await adapter.revisions.append(r1);
		await adapter.revisions.append(r2);
		const listed = await adapter.revisions.list("post-1");
		expect(listed.map((r) => r.id)).toEqual(["rev-1", "rev-2"]);
		expect(await adapter.revisions.list("other-id")).toEqual([]);
	});
});

describe("createAstropressInMemoryPlatformAdapter — auth store (default seed user)", () => {
	it("signs in the default seeded admin with id='admin-1', email='admin@example.com', isAdmin=true, password='password'", async () => {
		const adapter = makeAdapter();
		const user = await adapter.auth.signIn("admin@example.com", "password");
		expect(user).toEqual({ id: "admin-1", email: "admin@example.com", isAdmin: true });
	});

	it("returns null for unknown email and for wrong password", async () => {
		const adapter = makeAdapter();
		expect(await adapter.auth.signIn("nobody@example.com", "password")).toBeNull();
		expect(await adapter.auth.signIn("admin@example.com", "wrong")).toBeNull();
	});

	it("normalises email casing/whitespace on lookup so 'ADMIN@EXAMPLE.COM' and '  admin@example.com  ' both authenticate", async () => {
		const adapter = makeAdapter();
		const upper = await adapter.auth.signIn("ADMIN@EXAMPLE.COM", "password");
		expect(upper?.email).toBe("admin@example.com");
		const padded = await adapter.auth.signIn("  admin@example.com  ", "password");
		expect(padded?.email).toBe("admin@example.com");
	});

	it("getSession resolves a session created by signIn under the documented session:<id> key, and signOut clears it", async () => {
		const adapter = makeAdapter();
		const user = await adapter.auth.signIn("admin@example.com", "password");
		expect(user).not.toBeNull();
		expect(await adapter.auth.getSession(`session:${user?.id}`)).toEqual(user);
		await adapter.auth.signOut(`session:${user?.id}`);
		expect(await adapter.auth.getSession(`session:${user?.id}`)).toBeNull();
	});
});

describe("createAstropressInMemoryPlatformAdapter — explicit users override the default", () => {
	it("authenticates a custom seed user and rejects the default admin when users[] is supplied", async () => {
		const adapter = createAstropressInMemoryPlatformAdapter({
			capabilities: minimalCapabilities,
			users: [
				{
					id: "editor-9",
					email: "editor@example.com",
					isAdmin: false,
					password: "secret",
				},
			],
		});
		const user = await adapter.auth.signIn("editor@example.com", "secret");
		expect(user).toEqual({ id: "editor-9", email: "editor@example.com", isAdmin: false });
		// Default admin must NOT exist under this configuration.
		expect(await adapter.auth.signIn("admin@example.com", "password")).toBeNull();
	});
});

tests/api-tokens-d1.test.ts.source:
// Mutation-coverage + behavioral tests for the D1 API-token store
// (src/sqlite-runtime/api-tokens-d1.ts). The D1 backend is exercised through
// the SqliteBackedD1Database fixture so the async `.bind().run()/.first()/.all()`
// surface, the hashed-token storage, and the verify() reason literals are all
// observable — the D1 sibling that #137 added must behave identically to the
// sqlite store on every host that provides a D1 binding.
import { describe, expect, it } from "vitest";

import { createD1ApiTokenStore } from "../src/sqlite-runtime/api-tokens-d1.js";
import { hashOpaqueToken } from "../src/sqlite-runtime/utils.js";
import { makeDb } from "./helpers/make-db.js";
import { SqliteBackedD1Database } from "./helpers/provider-test-fixtures.js";

function makeStore() {
	const db = makeDb();
	const d1 = new SqliteBackedD1Database(db);
	return { db, store: createD1ApiTokenStore(d1) };
}

describe("createD1ApiTokenStore", () => {
	it("create: stores the hash (not the raw token) and returns the raw token once", async () => {
		const { db, store } = makeStore();
		const { record, rawToken } = await store.create({
			label: "agent",
			scopes: ["content:read"],
		});

		expect(rawToken.length).toBeGreaterThanOrEqual(32);
		expect(record.label).toBe("agent");
		expect(record.scopes).toEqual(["content:read"]);
		expect(record.id.startsWith("tok_")).toBe(true);
		expect(record.revokedAt).toBeNull();
		expect(record.lastUsedAt).toBeNull();

		const row = db.prepare("SELECT token_hash FROM api_tokens WHERE id = ?").get(record.id) as {
			token_hash: string;
		};
		expect(row.token_hash).toBe(hashOpaqueToken(rawToken));
		expect(row.token_hash).not.toBe(rawToken);
	});

	it("create: persists expiresAt and defaults it to null when omitted", async () => {
		const { store } = makeStore();
		const noExpiry = await store.create({ label: "a", scopes: ["content:read"] });
		expect(noExpiry.record.expiresAt).toBeNull();

		const future = new Date(Date.now() + 60_000).toISOString();
		const withExpiry = await store.create({
			label: "b",
			scopes: ["content:read"],
			expiresAt: future,
		});
		expect(withExpiry.record.expiresAt).toBe(future);
	});

	it("list: returns all tokens newest-first without exposing the hash", async () => {
		const { store } = makeStore();
		await store.create({ label: "alpha", scopes: ["content:read"] });
		await store.create({ label: "beta", scopes: ["media:read"] });

		const tokens = await store.list();
		expect(tokens).toHaveLength(2);
		expect(tokens.map((t) => t.label)).toEqual(expect.arrayContaining(["alpha", "beta"]));
		for (const token of tokens) {
			expect((token as Record<string, unknown>).token_hash).toBeUndefined();
		}
	});

	it("verify: valid token succeeds and stamps lastUsedAt", async () => {
		const { store } = makeStore();
		const { rawToken } = await store.create({ label: "agent", scopes: ["content:read"] });

		const result = await store.verify(rawToken);
		expect(result.valid).toBe(true);
		if (!result.valid) throw new Error("expected valid");
		expect(result.record.label).toBe("agent");
		expect(result.record.lastUsedAt).not.toBeNull();
	});

	it("verify: unknown token is rejected with a 'not found' reason", async () => {
		const { store } = makeStore();
		const result = await store.verify("definitely-not-a-real-token");
		expect(result.valid).toBe(false);
		if (result.valid) throw new Error("expected invalid");
		expect(result.reason).toMatch(/not found/i);
	});

	it("verify: revoked token is rejected with a 'revoked' reason", async () => {
		const { store } = makeStore();
		const { record, rawToken } = await store.create({
			label: "revoke-me",
			scopes: ["content:read"],
		});
		await store.revoke(record.id);

		const result = await store.verify(rawToken);
		expect(result.valid).toBe(false);
		if (result.valid) throw new Error("expected invalid");
		expect(result.reason).toMatch(/revoked/i);
	});

	it("verify: expired token is rejected with an 'expired' reason", async () => {
		const { store } = makeStore();
		const past = new Date(Date.now() - 60_000).toISOString();
		const { rawToken } = await store.create({
			label: "expired",
			scopes: ["content:read"],
			expiresAt: past,
		});

		const result = await store.verify(rawToken);
		expect(result.valid).toBe(false);
		if (result.valid) throw new Error("expected invalid");
		expect(result.reason).toMatch(/expired/i);
	});

	it("verify: future-expiry token still verifies", async () => {
		const { store } = makeStore();
		const future = new Date(Date.now() + 60_000).toISOString();
		const { rawToken } = await store.create({
			label: "future",
			scopes: ["content:read"],
			expiresAt: future,
		});
		const result = await store.verify(rawToken);
		expect(result.valid).toBe(true);
	});

	it("revoke: marks the token revoked while keeping it listed for admin display", async () => {
		const { store } = makeStore();
		const { record } = await store.create({ label: "revocable", scopes: ["content:write"] });
		await store.revoke(record.id);

		const tokens = await store.list();
		const revoked = tokens.find((t) => t.id === record.id);
		expect(revoked).toBeDefined();
		expect(revoked?.revokedAt).not.toBeNull();
	});
});

tests/local-provider.integration.test.ts.source:
import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

import {
	createAstropressCloudflareAdapter,
	createAstropressSupabaseAdapter,
} from "@astropress-diy/astropress";
import { describe, expect, it } from "vitest";
import { createAstropressLocalAdapter } from "../src/adapters/local.js";
import { createAstropressSqliteAdapter } from "../src/adapters/sqlite.js";
import { createAstropressSupabaseSqliteAdapter } from "../src/adapters/supabase-sqlite.js";

describe("local provider integration", () => {
	it("creates first-party adapters with provider-specific capability defaults", async () => {
		const workspace = await mkdtemp(join(tmpdir(), "astropress-sqlite-adapter-"));
		const sqlite = createAstropressSqliteAdapter({
			workspaceRoot: workspace,
			dbPath: join(workspace, "admin.sqlite"),
		});
		const cloudflare = createAstropressCloudflareAdapter();
		// Bare construction (no backingAdapter, no granular stores) was
		// previously allowed and silently dropped to in-memory; the adapter
		// now refuses misconfiguration. Pass the sqlite adapter as the real
		// backing surface to keep the capability-inspection path honest.
		const supabase = createAstropressSupabaseAdapter({
			backingAdapter: sqlite,
		});

		expect(sqlite.capabilities.name).toBe("sqlite");
		expect(sqlite.capabilities.database).toBe(true);
		expect(cloudflare.capabilities.objectStorage).toBe(true);
		expect(supabase.capabilities.name).toBe("supabase");

		const user = await sqlite.auth.signIn("admin@example.com", "password");
		expect(user?.isAdmin).toBe(true);
		expect(user?.id).toBeTruthy();
		expect(await sqlite.auth.getSession(user?.id ?? "")).toEqual(user);

		const savedRecord = await sqlite.content.save({
			id: "hello-world",
			kind: "post",
			slug: "hello-world",
			status: "published",
			title: "Hello world",
			body: "Astropress SQLite adapter",
			metadata: {
				metaDescription: "Adapter-backed post",
				seoTitle: "Hello world",
				legacyUrl: "/hello-world",
			},
		});
		expect(savedRecord.kind).toBe("post");
		expect(await sqlite.content.get("hello-world")).toMatchObject({
			slug: "hello-world",
			kind: "post",
		});
		expect(
			(await sqlite.content.list("post")).some((record) => record.slug === "hello-world"),
		).toBe(true);

		await rm(workspace, { recursive: true, force: true });
	});

	it("lets Supabase wrap a real backing adapter surface", async () => {
		const workspace = await mkdtemp(join(tmpdir(), "astropress-provider-wrap-"));
		const backingAdapter = createAstropressSqliteAdapter({
			workspaceRoot: workspace,
			dbPath: join(workspace, "admin.sqlite"),
		});
		const supabase = createAstropressSupabaseAdapter({ backingAdapter });

		expect(supabase.capabilities.name).toBe("supabase");

		const saved = await supabase.content.save({
			id: "wrapped-post",
			kind: "post",
			slug: "wrapped-post",
			status: "published",
			title: "Wrapped post",
			body: "Supabase-backed content",
			metadata: {
				metaDescription: "Wrapped provider",
				seoTitle: "Wrapped post",
				legacyUrl: "/wrapped-post",
			},
		});

		expect(saved.slug).toBe("wrapped-post");
		expect(await supabase.content.get("wrapped-post")).toMatchObject({
			slug: "wrapped-post",
			kind: "post",
		});

		await rm(workspace, { recursive: true, force: true });
	});

	it("creates sqlite-backed local runtime for Supabase", async () => {
		const workspace = await mkdtemp(join(tmpdir(), "astropress-provider-sqlite-"));
		const supabase = createAstropressSupabaseSqliteAdapter({
			workspaceRoot: workspace,
			dbPath: join(workspace, "supabase-admin.sqlite"),
		});

		const supabaseUser = await supabase.auth.signIn("admin@example.com", "password");
		expect(supabaseUser?.isAdmin).toBe(true);

		const saved = await supabase.content.save({
			id: "provider-local-post",
			kind: "post",
			slug: "provider-local-post",
			status: "published",
			title: "Provider local post",
			body: "Supabase local runtime",
			metadata: {
				metaDescription: "Provider local runtime",
				seoTitle: "Provider local post",
				legacyUrl: "/provider-local-post",
			},
		});
		expect(saved.slug).toBe("provider-local-post");
		expect(await supabase.content.get("provider-local-post")).toMatchObject({
			slug: "provider-local-post",
		});

		await rm(workspace, { recursive: true, force: true });
	});

	it("selects the requested local provider runtime", { timeout: 60_000 }, async () => {
		const workspace = await mkdtemp(join(tmpdir(), "astropress-provider-local-select-"));
		const supabase = createAstropressLocalAdapter({
			provider: "supabase",
			workspaceRoot: workspace,
			dbPath: join(workspace, "supabase-admin.sqlite"),
		});
		const sqlite = createAstropressLocalAdapter({
			workspaceRoot: workspace,
			dbPath: join(workspace, "admin.sqlite"),
		});

		expect(supabase.capabilities.name).toBe("supabase");
		expect(sqlite.capabilities.name).toBe("sqlite");

		await rm(workspace, { recursive: true, force: true });
	});
});

tests/sqlite-helpers-utils.test.ts.source:
import { describe, expect, it } from "vitest";
import {
	buildRevisionParams,
	resolveMetaString,
	resolveSqliteStatus,
	SQL_INSERT_REVISION,
	SQL_LIST_TRANSLATIONS,
	SQL_UPSERT_MEDIA,
	snapshotField,
} from "../src/adapters/sqlite-helpers";

describe("resolveMetaString", () => {
	it("returns the string value when meta[key] is a string", () => {
		expect(resolveMetaString({ a: "hello" }, "a")).toBe("hello");
	});
	it("returns undefined when meta[key] is not a string", () => {
		expect(resolveMetaString({ a: 42 }, "a")).toBeUndefined();
		expect(resolveMetaString({ a: null }, "a")).toBeUndefined();
		expect(resolveMetaString({ a: true }, "a")).toBeUndefined();
		expect(resolveMetaString({}, "missing")).toBeUndefined();
	});
	it("returns undefined when meta is null or undefined (optional-chain pin)", () => {
		expect(resolveMetaString(null, "x")).toBeUndefined();
		expect(resolveMetaString(undefined, "x")).toBeUndefined();
	});
});

describe("resolveSqliteStatus", () => {
	it("returns 'archived' only for the literal 'archived'", () => {
		expect(resolveSqliteStatus("archived")).toBe("archived");
	});
	it("returns 'draft' only for the literal 'draft'", () => {
		expect(resolveSqliteStatus("draft")).toBe("draft");
	});
	it("returns 'published' for anything else including undefined and unrecognized strings", () => {
		expect(resolveSqliteStatus(undefined)).toBe("published");
		expect(resolveSqliteStatus("published")).toBe("published");
		expect(resolveSqliteStatus("scheduled")).toBe("published");
		expect(resolveSqliteStatus("")).toBe("published");
	});
});

describe("snapshotField", () => {
	it("returns snapshot[key] when present and non-null", () => {
		expect(snapshotField({ a: "x" }, "a")).toBe("x");
		expect(snapshotField({ a: 0 }, "a")).toBe(0);
		expect(snapshotField({ a: false }, "a")).toBe(false);
	});
	it("returns the fallback when snapshot[key] is null or undefined", () => {
		expect(snapshotField({ a: null }, "a", "FB")).toBe("FB");
		expect(snapshotField({}, "missing", "FB")).toBe("FB");
	});
	it("defaults the fallback to null", () => {
		expect(snapshotField({}, "missing")).toBeNull();
	});
});

describe("buildRevisionParams", () => {
	it("produces a 21-element array matching the SQL_INSERT_REVISION column order", () => {
		const params = buildRevisionParams(
			{
				title: "T",
				status: "draft",
				scheduledAt: "2026-01-01",
				body: "B",
				seoTitle: "ST",
				metaDescription: "MD",
				excerpt: "E",
				ogTitle: "OG",
				ogDescription: "OGD",
				ogImage: "OGI",
				authorIds: ["a1"],
				categoryIds: ["c1"],
				tagIds: ["t1"],
				canonicalUrlOverride: "/canon",
				robotsDirective: "noindex",
			},
			{ id: "rev-1", recordId: "rec-1", summary: "S", createdAt: "2026-01-02", actorId: "u1" },
			"actor@example.com",
		);
		expect(params).toEqual([
			"rev-1",
			"rec-1",
			"T",
			"draft",
			"2026-01-01",
			"B",
			"ST",
			"MD",
			"E",
			"OG",
			"OGD",
			"OGI",
			'["a1"]',
			'["c1"]',
			'["t1"]',
			"/canon",
			"noindex",
			"S",
			"2026-01-02",
			"u1",
		]);
	});

	it("falls back to recordId / actorEmail when title/actorId are missing", () => {
		const params = buildRevisionParams(
			{},
			{ id: "rev-2", recordId: "rec-2", createdAt: "2026-01-03" },
			"actor@example.com",
		);
		expect(params[2]).toBe("rec-2"); // title fallback
		expect(params[6]).toBe("rec-2"); // seoTitle fallback
		expect(params[7]).toBe("rec-2"); // metaDescription fallback
		expect(params[12]).toBe("[]"); // empty authorIds JSON
		expect(params[13]).toBe("[]");
		expect(params[14]).toBe("[]");
		expect(params[17]).toBeNull(); // revision.summary ?? null
		expect(params[19]).toBe("actor@example.com"); // actorId fallback
	});

	it("uses snapshot.title for seoTitle/metaDescription when explicit fields are absent", () => {
		const params = buildRevisionParams(
			{ title: "FromSnapshot" },
			{ id: "r", recordId: "rec", createdAt: "now" },
			"e@example.com",
		);
		expect(params[6]).toBe("FromSnapshot");
		expect(params[7]).toBe("FromSnapshot");
	});
});

describe("SQL constants are literal strings (kill StringLiteral mutants)", () => {
	it("SQL_UPSERT_MEDIA inserts into media_assets and ON CONFLICT updates", () => {
		expect(SQL_UPSERT_MEDIA).toContain("INSERT INTO media_assets");
		expect(SQL_UPSERT_MEDIA).toContain("ON CONFLICT(id) DO UPDATE SET");
		expect(SQL_UPSERT_MEDIA).toContain("deleted_at = NULL");
	});
	it("SQL_INSERT_REVISION targets content_revisions with the source='reviewed' literal", () => {
		expect(SQL_INSERT_REVISION).toContain("INSERT INTO content_revisions");
		expect(SQL_INSERT_REVISION).toContain("'reviewed'");
	});
	it("SQL_LIST_TRANSLATIONS reads translation_overrides ordered by route ASC", () => {
		expect(SQL_LIST_TRANSLATIONS).toContain("FROM translation_overrides");
		expect(SQL_LIST_TRANSLATIONS).toContain("ORDER BY route ASC");
	});
});

tests/integrations/webhooks/receiver.tes.source:
import { afterEach, beforeEach, describe, expect, it } from "vitest";

import { receiveInboundWebhook } from "../../../src/integrations/webhooks/receiver";
import {
	_resetInboundWebhookRegistryForTests,
	registerInboundWebhookProvider,
} from "../../../src/integrations/webhooks/registry";

const SECRET = "super-secret";
const BODY_TEXT = '{"action":"opened","number":42}';
const BODY = new TextEncoder().encode(BODY_TEXT);

async function signGithubBody(body: Uint8Array, secret: string): Promise<string> {
	const key = await crypto.subtle.importKey(
		"raw",
		new TextEncoder().encode(secret),
		{ name: "HMAC", hash: "SHA-256" },
		false,
		["sign"],
	);
	const sig = await crypto.subtle.sign("HMAC", key, body);
	const hex = Array.from(new Uint8Array(sig))
		.map((b) => b.toString(16).padStart(2, "0"))
		.join("");
	return `sha256=${hex}`;
}

function headerLookup(map: Record<string, string>): (name: string) => string | null {
	return (name) => {
		const lower = name.toLowerCase();
		for (const [k, v] of Object.entries(map)) {
			if (k.toLowerCase() === lower) return v;
		}
		return null;
	};
}

beforeEach(() => {
	registerInboundWebhookProvider({
		id: "github",
		label: "GitHub",
		signatureHeader: "X-Hub-Signature-256",
		algorithm: "hmac-sha256",
		eventHeader: "X-GitHub-Event",
	});
});

afterEach(() => _resetInboundWebhookRegistryForTests());

describe("receiveInboundWebhook — happy path", () => {
	it("returns ok with provider + eventName when signature verifies and event header is present", async () => {
		const sig = await signGithubBody(BODY, SECRET);
		const r = await receiveInboundWebhook({
			providerId: "github",
			bodyBytes: BODY,
			secret: SECRET,
			headers: headerLookup({
				"X-Hub-Signature-256": sig,
				"X-GitHub-Event": "pull_request",
			}),
		});
		expect(r.ok).toBe(true);
		if (r.ok) {
			expect(r.provider.id).toBe("github");
			expect(r.eventName).toBe("pull_request");
		}
	});

	it("returns ok with eventName=null when the provider has no eventHeader", async () => {
		_resetInboundWebhookRegistryForTests();
		registerInboundWebhookProvider({
			id: "anon",
			label: "Anon",
			signatureHeader: "X-Sig",
			algorithm: "hmac-sha256",
		});
		// Re-sign body using a known shape: raw hex (no prefix).
		const key = await crypto.subtle.importKey(
			"raw",
			new TextEncoder().encode(SECRET),
			{ name: "HMAC", hash: "SHA-256" },
			false,
			["sign"],
		);
		const sigBytes = await crypto.subtle.sign("HMAC", key, BODY);
		const hex = Array.from(new Uint8Array(sigBytes))
			.map((b) => b.toString(16).padStart(2, "0"))
			.join("");
		const r = await receiveInboundWebhook({
			providerId: "anon",
			bodyBytes: BODY,
			secret: SECRET,
			headers: headerLookup({ "X-Sig": `sha256=${hex}` }),
		});
		expect(r.ok).toBe(true);
		if (r.ok) expect(r.eventName).toBeNull();
	});
});

describe("receiveInboundWebhook — error branches", () => {
	it("returns RECEIVER_UNKNOWN_PROVIDER for an unregistered id", async () => {
		const r = await receiveInboundWebhook({
			providerId: "stripe",
			bodyBytes: BODY,
			secret: SECRET,
			headers: headerLookup({}),
		});
		expect(r).toEqual({ ok: false, code: "RECEIVER_UNKNOWN_PROVIDER" });
	});

	it("returns RECEIVER_MISSING_SIGNATURE when the signature header is absent", async () => {
		const r = await receiveInboundWebhook({
			providerId: "github",
			bodyBytes: BODY,
			secret: SECRET,
			headers: headerLookup({}),
		});
		expect(r).toEqual({ ok: false, code: "RECEIVER_MISSING_SIGNATURE" });
	});

	it("returns RECEIVER_MISSING_SIGNATURE when the signature header is empty", async () => {
		const r = await receiveInboundWebhook({
			providerId: "github",
			bodyBytes: BODY,
			secret: SECRET,
			headers: headerLookup({ "X-Hub-Signature-256": "" }),
		});
		expect(r).toEqual({ ok: false, code: "RECEIVER_MISSING_SIGNATURE" });
	});

	it("returns RECEIVER_INVALID_SIGNATURE when the signature does not match", async () => {
		const sig = await signGithubBody(BODY, "WRONG-SECRET");
		const r = await receiveInboundWebhook({
			providerId: "github",
			bodyBytes: BODY,
			secret: SECRET,
			headers: headerLookup({
				"X-Hub-Signature-256": sig,
				"X-GitHub-Event": "ping",
			}),
		});
		expect(r).toEqual({ ok: false, code: "RECEIVER_INVALID_SIGNATURE" });
	});

	it("returns RECEIVER_INVALID_SIGNATURE when the body has been tampered with", async () => {
		const sig = await signGithubBody(BODY, SECRET);
		const r = await receiveInboundWebhook({
			providerId: "github",
			bodyBytes: new TextEncoder().encode(`${BODY_TEXT}!`),
			secret: SECRET,
			headers: headerLookup({
				"X-Hub-Signature-256": sig,
				"X-GitHub-Event": "ping",
			}),
		});
		expect(r).toEqual({ ok: false, code: "RECEIVER_INVALID_SIGNATURE" });
	});
});

