/**
 * admin-page-model-helpers mutation pins.
 *
 * Targets ArrayDeclaration `[]` → `["Stryker was here"]` survivors in
 * emptyDashboardModel and the default-warnings parameter of `result`, and
 * the `settled.some` vs `.every` boundary in withSettledMap.
 */

import { describe, expect, it } from "vitest";

import {
	emptyDashboardModel,
	forbidden,
	notFound,
	ok,
	result,
	safeAdminUserName,
	withSettledMap,
} from "../src/admin-page-model-helpers.js";

describe("safeAdminUserName", () => {
	it("returns an empty string for an anonymous (undefined/null) user — no deref", () => {
		// This is the #105/#108/#138/#139 crash guard: a forbidden page renders
		// the layout shell with status 403 even when adminUser is undefined.
		expect(safeAdminUserName(undefined)).toBe("");
		expect(safeAdminUserName(null)).toBe("");
	});

	it("returns the user's name when present", () => {
		expect(safeAdminUserName({ email: "a@b.c", name: "Ada", isAdmin: false })).toBe("Ada");
	});

	it("does not throw for a user object missing a name", () => {
		expect(safeAdminUserName({ email: "a@b.c" } as never)).toBe("");
	});
});

describe("emptyDashboardModel", () => {
	it("seeds every list field with a fresh empty array (kills L84-L98 ArrayDeclaration mutants)", () => {
		const model = emptyDashboardModel();
		// Each per-field assertion targets one of the L84-L98 mutants
		// (`[]` → `["Stryker was here"]`). toEqual([]) fails on any non-empty seed.
		expect(model.auditEvents).toEqual([]);
		expect(model.comments).toEqual([]);
		expect(model.redirectRules).toEqual([]);
		expect(model.routePages).toEqual([]);
		expect(model.contentStates).toEqual([]);
		expect(model.systemRoutes).toEqual([]);
		expect(model.posts).toEqual([]);
		expect(model.pages).toEqual([]);
		expect(model.reviewPosts).toEqual([]);
		expect(model.scheduledPosts).toEqual([]);
		expect(model.recentAuditEvents).toEqual([]);
		expect(model.recentActivity).toEqual([]);
		expect(model.archiveRoutes).toEqual([]);
		expect(model.supportSurfaceLinks).toEqual([]);
		expect(model.translationNeedsAttention).toBe(0);
		expect(model.seoNeedsAttention).toBe(0);
		expect(model.latestDeployment).toBeNull();
	});
});

describe("result/ok/forbidden/notFound default warnings parameter", () => {
	it("result() defaults warnings to a fresh empty array (kills L16:73 ArrayDeclaration)", () => {
		// Original: result("ok", {}, []) → warnings=[].
		// Mutant L16:73: warnings parameter default becomes ["Stryker was here"].
		expect(result("ok", { value: 1 }).warnings).toEqual([]);
	});

	it("ok() with no warnings produces status 'ok' and empty warnings", () => {
		const r = ok({ value: "x" });
		// ok() forwards [] through result()'s default — the L21 ternary picks "ok" when
		// warnings.length === 0. A mutated default of ["Stryker was here"] (length 1) would flip
		// status to "partial".
		expect(r.status).toBe("ok");
		expect(r.warnings).toEqual([]);
	});

	it("forbidden() emits an empty warnings array", () => {
		expect(forbidden({ value: null }).warnings).toEqual([]);
	});

	it("notFound() defaults warnings to []", () => {
		expect(notFound({ value: null }).warnings).toEqual([]);
	});
});

describe("withSettledMap — settled.some(rejected) boundary", () => {
	it("does NOT push a warning when every item resolves (proves .some not .every on no-rejections)", async () => {
		const warnings: string[] = [];
		const out = await withSettledMap(
			warnings,
			"never-pushed",
			[1, 2, 3],
			async (n) => n * 2,
			(n) => -n,
		);
		expect(out).toEqual([2, 4, 6]);
		expect(warnings).toEqual([]);
	});

	it("pushes a warning when ANY item rejects, not only when ALL reject (kills L71 MethodExpression .every)", async () => {
		// Mixed: index 0 rejects, index 1 resolves. some=true, every=false.
		// Original (.some): hadFailure=true → warning pushed.
		// Mutant (.every): hadFailure=false → warning NOT pushed.
		const warnings: string[] = [];
		const out = await withSettledMap(
			warnings,
			"mixed-failures",
			["fail", "ok"] as const,
			async (item) => {
				if (item === "fail") throw new Error("boom");
				return `mapped:${item}`;
			},
			(item) => `fallback:${item}`,
		);
		expect(out).toEqual(["fallback:fail", "mapped:ok"]);
		expect(warnings).toEqual(["mixed-failures"]);
	});

	it("pushes a warning when ALL items reject (proves the .some side of the boundary holds)", async () => {
		const warnings: string[] = [];
		await withSettledMap(
			warnings,
			"all-failed",
			[1, 2],
			async () => {
				throw new Error("nope");
			},
			(n) => `fallback:${n}`,
		);
		expect(warnings).toEqual(["all-failed"]);
	});
});

tests/access-page-guard.test.ts.source:
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { beforeEach, describe, expect, test, vi } from "vitest";
import type { LocalAccessStoreSurface } from "../src/access";
import { createAccessRepository, requiresAccess, seedStarterRoles } from "../src/access";
import { loadSqliteDatabase } from "../src/sqlite-bootstrap-helpers";

const SCHEMA = readFileSync(
	fileURLToPath(new URL("../src/sqlite-schema.sql", import.meta.url)),
	"utf8",
);

interface DbHandle {
	prepare: (sql: string) => {
		all: <T = unknown>(...args: unknown[]) => T[];
		get: <T = unknown>(...args: unknown[]) => T | undefined;
		run: (...args: unknown[]) => { changes: number };
	};
	exec: (sql: string) => void;
}

let currentStore: { access?: LocalAccessStoreSurface } = {};

vi.mock("../src/local-runtime-modules", async (orig) => {
	const original = await orig<typeof import("../src/local-runtime-modules")>();
	return {
		...original,
		loadLocalAdminStore: async () => currentStore as never,
	};
});

function buildLocalSurface(db: DbHandle): LocalAccessStoreSurface {
	const repo = createAccessRepository(db as never);
	return {
		resolveAccessSnapshotByEmail(email) {
			const row = db
				.prepare("SELECT id, is_admin FROM admin_users WHERE email = ? AND active = 1 LIMIT 1")
				.get<{ id: number; is_admin: number }>(email);
			if (!row) return null;
			return {
				userId: String(row.id),
				isAdmin: row.is_admin === 1,
				roles: repo.listUserRoleIds(row.id),
				attributes: repo.getUserAttributes(row.id),
				policies: repo.resolvePoliciesForUser(row.id),
			};
		},
	};
}

function fakeAstro(adminUser: { email: string; role: "admin" | "editor"; name: string } | null) {
	const calls: Array<{ path: string; status?: number }> = [];
	const astro = {
		locals: { adminUser } as unknown as App.Locals,
		redirect(path: string, status?: number) {
			calls.push({ path, status });
			return new Response(null, {
				status: status ?? 302,
				headers: { Location: path },
			});
		},
	};
	return { astro, calls };
}

describe("requiresAccess", () => {
	let db: DbHandle;
	beforeEach(async () => {
		const DbClass = await loadSqliteDatabase();
		const inst = new DbClass(":memory:");
		inst.exec(SCHEMA);
		db = inst as unknown as DbHandle;
		db.prepare(
			"INSERT INTO admin_users (email, password_hash, name, is_admin) VALUES (?, 'h', 'Admin', 1)",
		).run("admin@example.com");
		db.prepare(
			"INSERT INTO admin_users (email, password_hash, name, is_admin) VALUES (?, 'h', 'Editor', 0)",
		).run("editor@example.com");
		const repo = createAccessRepository(db as never);
		seedStarterRoles(repo);
		const editor = repo.listRoles().find((r) => r.name === "Editor");
		if (!editor) throw new Error("Editor role missing");
		const editorRow = db
			.prepare("SELECT id FROM admin_users WHERE email = ?")
			.get<{ id: number }>("editor@example.com");
		if (!editorRow) throw new Error("editor fixture missing");
		repo.assignRole({ userId: editorRow.id, roleId: editor.id });
		currentStore = { access: buildLocalSurface(db) };
	});

	test("returns null and continues when subject is allowed", async () => {
		const { astro, calls } = fakeAstro({
			email: "admin@example.com",
			role: "admin",
			name: "Admin",
		});
		const result = await requiresAccess(astro, "settings:edit");
		expect(result).toBeNull();
		expect(calls).toHaveLength(0);
	});

	test("redirects with forbidden path on deny — appends the engine reason for the UI banner", async () => {
		const { astro, calls } = fakeAstro({
			email: "editor@example.com",
			role: "editor",
			name: "Editor",
		});
		const result = await requiresAccess(astro, "users:invite");
		expect(result).not.toBeNull();
		expect(calls[0]?.path).toMatch(/^\/ap-admin\?error=insufficient-permissions&reason=/);
	});

	test("redirects to login when no admin user", async () => {
		const { astro, calls } = fakeAstro(null);
		const result = await requiresAccess(astro, "settings:edit");
		expect(result).not.toBeNull();
		expect(calls[0]?.path).toBe("/ap-admin/login");
	});

	test("respects override forbidden + login paths", async () => {
		const { astro: astro1, calls: calls1 } = fakeAstro({
			email: "editor@example.com",
			role: "editor",
			name: "Editor",
		});
		await requiresAccess(astro1, "users:invite", {
			forbiddenPath: "/ap-admin/forbidden",
		});
		expect(calls1[0]?.path).toBe("/ap-admin/forbidden");

		const { astro: astro2, calls: calls2 } = fakeAstro(null);
		await requiresAccess(astro2, "settings:edit", {
			loginPath: "/auth/login",
		});
		expect(calls2[0]?.path).toBe("/auth/login");
	});
});

tests/content-locking.test.ts.source:
import type { DatabaseSync } from "node:sqlite";
import { beforeEach, describe, expect, it } from "vitest";

import { createSqliteLocksOps } from "../src/sqlite-runtime/locks.js";
import { makeDb } from "./helpers/make-db.js";

describe("createSqliteLocksOps — pessimistic content locking", () => {
	let db: DatabaseSync;
	let locks: ReturnType<typeof createSqliteLocksOps>;

	beforeEach(() => {
		db = makeDb();
		locks = createSqliteLocksOps(() => db);
	});

	it("acquire succeeds for first requester", () => {
		const result = locks.acquireLock("my-post", "alice@test.com", "Alice");
		expect(result.ok).toBe(true);
		if (result.ok) {
			expect(result.lockToken).toBeTruthy();
			expect(result.expiresAt).toBeTruthy();
		}
	});

	it("acquire returns conflict when another user holds the lock", () => {
		locks.acquireLock("my-post", "alice@test.com", "Alice");
		const conflict = locks.acquireLock("my-post", "bob@test.com", "Bob");
		expect(conflict.ok).toBe(false);
		if (!conflict.ok) {
			// Pins L53 BooleanLiteral `conflict: true` — without an explicit
			// assertion the field could flip to false and the existing
			// destructuring branch would silently skip.
			expect(conflict.conflict).toBe(true);
			expect(conflict.lockedByEmail).toBe("alice@test.com");
			expect(conflict.lockedByName).toBe("Alice");
			expect(conflict.expiresAt).toBeTruthy();
		}
	});

	it("rolls back the open transaction on conflict so the same connection can acquire again (pins L50 ROLLBACK)", () => {
		locks.acquireLock("my-post", "alice@test.com", "Alice");
		const conflict = locks.acquireLock("my-post", "bob@test.com", "Bob");
		expect(conflict.ok).toBe(false);
		// L50 mutates `db.exec("ROLLBACK")` → `db.exec("")`. Without the rollback
		// the BEGIN IMMEDIATE transaction stays open on this shared connection;
		// the next acquireLock would throw "cannot start a transaction within
		// a transaction". Alice re-acquiring her own lock must just work.
		const aliceAgain = locks.acquireLock("my-post", "alice@test.com", "Alice");
		expect(aliceAgain.ok).toBe(true);
	});

	it("releaseLock returns true when a matching row is deleted (pins L91 boundary)", () => {
		const acquired = locks.acquireLock("my-post", "alice@test.com", "Alice");
		expect(acquired.ok).toBe(true);
		if (!acquired.ok) return;
		const released = locks.releaseLock("my-post", acquired.lockToken);
		expect(released).toBe(true);
	});

	it("releaseLock returns false for unknown token (pins L91 boundary)", () => {
		locks.acquireLock("my-post", "alice@test.com", "Alice");
		const released = locks.releaseLock("my-post", "wrong-token");
		expect(released).toBe(false);
	});

	it("same user re-acquiring refreshes the lock", () => {
		const first = locks.acquireLock("my-post", "alice@test.com", "Alice");
		const second = locks.acquireLock("my-post", "alice@test.com", "Alice");
		expect(first.ok).toBe(true);
		expect(second.ok).toBe(true);
		if (first.ok && second.ok) {
			expect(second.lockToken).not.toBe(first.lockToken);
		}
	});

	it("heartbeat (refreshLock) extends expiry and returns true", () => {
		const acquired = locks.acquireLock("my-post", "alice@test.com", "Alice");
		expect(acquired.ok).toBe(true);
		if (!acquired.ok) return;

		const refreshed = locks.refreshLock("my-post", acquired.lockToken);
		expect(refreshed).toBe(true);
	});

	it("refreshLock returns false for unknown token", () => {
		locks.acquireLock("my-post", "alice@test.com", "Alice");
		const refreshed = locks.refreshLock("my-post", "bad-token");
		expect(refreshed).toBe(false);
	});

	it("release enables immediate re-acquire by another user", () => {
		const acquired = locks.acquireLock("my-post", "alice@test.com", "Alice");
		expect(acquired.ok).toBe(true);
		if (!acquired.ok) return;

		locks.releaseLock("my-post", acquired.lockToken);

		const bob = locks.acquireLock("my-post", "bob@test.com", "Bob");
		expect(bob.ok).toBe(true);
	});

	it("expired lock allows re-acquire by another user", () => {
		// Insert an expired lock row directly
		const pastExpiry = new Date(Date.now() - 1000).toISOString();
		db.prepare(
			`INSERT INTO content_locks (slug, locked_by_email, locked_by_name, lock_token, expires_at)
       VALUES (?, ?, ?, ?, ?)`,
		).run("stale-post", "alice@test.com", "Alice", "old-token", pastExpiry);

		const bob = locks.acquireLock("stale-post", "bob@test.com", "Bob");
		expect(bob.ok).toBe(true);
	});
});

tests/admin-slug-cache.test.ts.source:
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

vi.mock("../src/runtime-page-store", () => ({
	getRuntimeSettings: vi.fn(),
}));

import {
	invalidateAstropressAdminSlugCache,
	resolveAstropressAdminSlug,
} from "../src/admin-slug-cache";
import { getRuntimeSettings } from "../src/runtime-page-store";

const mockedGetRuntimeSettings = vi.mocked(getRuntimeSettings);

beforeEach(() => {
	invalidateAstropressAdminSlugCache();
	mockedGetRuntimeSettings.mockReset();
});

afterEach(() => {
	invalidateAstropressAdminSlugCache();
});

const FAKE_LOCALS = {} as never;

describe("resolveAstropressAdminSlug", () => {
	it("returns the configured adminSlug from settings", async () => {
		mockedGetRuntimeSettings.mockResolvedValueOnce({
			adminSlug: "custom-admin",
		} as never);
		expect(await resolveAstropressAdminSlug(FAKE_LOCALS)).toBe("custom-admin");
	});

	it("falls back to ap-admin when adminSlug is empty string", async () => {
		mockedGetRuntimeSettings.mockResolvedValueOnce({ adminSlug: "" } as never);
		expect(await resolveAstropressAdminSlug(FAKE_LOCALS)).toBe("ap-admin");
	});

	it("falls back to ap-admin when adminSlug is undefined", async () => {
		mockedGetRuntimeSettings.mockResolvedValueOnce({} as never);
		expect(await resolveAstropressAdminSlug(FAKE_LOCALS)).toBe("ap-admin");
	});

	it("returns ap-admin when getRuntimeSettings throws", async () => {
		mockedGetRuntimeSettings.mockRejectedValueOnce(new Error("boom"));
		expect(await resolveAstropressAdminSlug(FAKE_LOCALS)).toBe("ap-admin");
	});

	it("caches the resolved slug across calls within TTL", async () => {
		mockedGetRuntimeSettings.mockResolvedValueOnce({
			adminSlug: "first",
		} as never);
		expect(await resolveAstropressAdminSlug(FAKE_LOCALS)).toBe("first");
		// Second call: settings would return "second" but cache should win.
		mockedGetRuntimeSettings.mockResolvedValueOnce({
			adminSlug: "second",
		} as never);
		expect(await resolveAstropressAdminSlug(FAKE_LOCALS)).toBe("first");
		expect(mockedGetRuntimeSettings).toHaveBeenCalledOnce();
	});

	it("re-fetches after the cache TTL elapses", async () => {
		vi.useFakeTimers();
		try {
			mockedGetRuntimeSettings.mockResolvedValueOnce({
				adminSlug: "first",
			} as never);
			expect(await resolveAstropressAdminSlug(FAKE_LOCALS)).toBe("first");

			// Advance just past the 60s TTL.
			vi.advanceTimersByTime(60_001);

			mockedGetRuntimeSettings.mockResolvedValueOnce({
				adminSlug: "second",
			} as never);
			expect(await resolveAstropressAdminSlug(FAKE_LOCALS)).toBe("second");
			expect(mockedGetRuntimeSettings).toHaveBeenCalledTimes(2);
		} finally {
			vi.useRealTimers();
		}
	});

	// Boundary: at EXACTLY TTL_MS the cache expires (strict <, not <=).
	// Pins the EqualityOperator mutation: now - cachedAt < TTL → <= TTL.
	// With the mutation, at exactly TTL the cache would still be served.
	it("re-fetches at exactly the TTL boundary (strict-less-than semantics)", async () => {
		vi.useFakeTimers();
		try {
			// Cache "first" at t=0.
			mockedGetRuntimeSettings.mockResolvedValueOnce({
				adminSlug: "first",
			} as never);
			expect(await resolveAstropressAdminSlug(FAKE_LOCALS)).toBe("first");
			// Within TTL: cache wins, no extra fetch.
			vi.advanceTimersByTime(59_999);
			expect(await resolveAstropressAdminSlug(FAKE_LOCALS)).toBe("first");
			expect(mockedGetRuntimeSettings).toHaveBeenCalledOnce();

			// Advance to exactly TTL: with strict-less-than, the cache is
			// stale and we re-fetch. With the < → <= mutation, the cache
			// would still be served and "second" would never be reached.
			vi.advanceTimersByTime(1);
			mockedGetRuntimeSettings.mockResolvedValueOnce({
				adminSlug: "second",
			} as never);
			expect(await resolveAstropressAdminSlug(FAKE_LOCALS)).toBe("second");
			expect(mockedGetRuntimeSettings).toHaveBeenCalledTimes(2);
		} finally {
			vi.useRealTimers();
		}
	});

	it("invalidate forces the next call to refetch", async () => {
		mockedGetRuntimeSettings.mockResolvedValueOnce({
			adminSlug: "first",
		} as never);
		await resolveAstropressAdminSlug(FAKE_LOCALS);
		invalidateAstropressAdminSlugCache();
		mockedGetRuntimeSettings.mockResolvedValueOnce({
			adminSlug: "second",
		} as never);
		expect(await resolveAstropressAdminSlug(FAKE_LOCALS)).toBe("second");
		expect(mockedGetRuntimeSettings).toHaveBeenCalledTimes(2);
	});
});

tests/content-repository-helpers.test.ts.source:
import { describe, expect, it } from "vitest";

import { mapContentState, normalizeAssignments } from "../src/content-repository-helpers.js";

const baseRecord = {
	id: "p1",
	kind: "post" as const,
	slug: "p1",
	status: "published" as const,
	title: "Original title",
	body: "Original body",
	seoTitle: "Original SEO",
	metaDescription: "Original meta",
	excerpt: "Original excerpt",
	authorIds: [99],
	categoryIds: [88],
	tagIds: [77],
};

const baseAssignments = {
	authorIds: [1],
	categoryIds: [2],
	tagIds: [3],
};

describe("normalizeAssignments", () => {
	it("returns [] when called with undefined", () => {
		expect(normalizeAssignments()).toEqual([]);
	});
	it("returns [] when called with empty array", () => {
		expect(normalizeAssignments([])).toEqual([]);
	});
	it("dedupes positive integer entries", () => {
		expect(normalizeAssignments([1, 2, 2, 3, 1])).toEqual([1, 2, 3]);
	});
	it("filters out non-integers (floats)", () => {
		expect(normalizeAssignments([1, 1.5, 2])).toEqual([1, 2]);
	});
	it("filters out zero and negatives (entry > 0 invariant)", () => {
		expect(normalizeAssignments([-1, 0, 1, 2])).toEqual([1, 2]);
	});
	it("preserves first-occurrence order under dedupe", () => {
		expect(normalizeAssignments([3, 1, 2, 1, 3])).toEqual([3, 1, 2]);
	});
});

describe("mapContentState", () => {
	it("uses record fields when override is null (everything from record)", () => {
		const out = mapContentState(baseRecord as never, null, baseAssignments);
		expect(out.title).toBe("Original title");
		expect(out.body).toBe("Original body");
		expect(out.seoTitle).toBe("Original SEO");
		expect(out.metaDescription).toBe("Original meta");
		expect(out.excerpt).toBe("Original excerpt");
		// Override-only fields default to undefined when no override supplied.
		expect(out.scheduledAt).toBeUndefined();
		expect(out.ogTitle).toBeUndefined();
	});

	it("uses record fields when override is undefined", () => {
		const out = mapContentState(baseRecord as never, undefined, baseAssignments);
		expect(out.title).toBe("Original title");
	});

	it("override values take precedence over record values", () => {
		const out = mapContentState(
			baseRecord as never,
			{
				title: "New title",
				status: "draft",
				body: "New body",
				seoTitle: "New SEO",
				metaDescription: "New meta",
				excerpt: "New excerpt",
				scheduledAt: "2026-12-31T00:00:00Z",
				ogTitle: "OG-T",
				ogDescription: "OG-D",
				ogImage: "OG-I",
				canonicalUrlOverride: "/canon",
				robotsDirective: "noindex",
			} as never,
			baseAssignments,
		);
		expect(out.title).toBe("New title");
		expect(out.status).toBe("draft");
		expect(out.body).toBe("New body");
		expect(out.seoTitle).toBe("New SEO");
		expect(out.metaDescription).toBe("New meta");
		expect(out.excerpt).toBe("New excerpt");
		expect(out.scheduledAt).toBe("2026-12-31T00:00:00Z");
		expect(out.ogTitle).toBe("OG-T");
		expect(out.ogDescription).toBe("OG-D");
		expect(out.ogImage).toBe("OG-I");
		expect(out.canonicalUrlOverride).toBe("/canon");
		expect(out.robotsDirective).toBe("noindex");
	});

	it("assignments completely replace record's authorIds/categoryIds/tagIds", () => {
		const out = mapContentState(baseRecord as never, null, baseAssignments);
		expect(out.authorIds).toEqual([1]);
		expect(out.categoryIds).toEqual([2]);
		expect(out.tagIds).toEqual([3]);
	});

	it("preserves an empty-string override.body (?? semantics, not || or &&)", () => {
		// Editor explicitly cleared the body. Original `??` returns "" (use override).
		// Mutant `&&` would return record.body since "" is falsy.
		const out = mapContentState(baseRecord as never, { body: "" } as never, baseAssignments);
		expect(out.body).toBe("");
	});

	it("preserves an empty-string override.seoTitle (?? semantics)", () => {
		const out = mapContentState(baseRecord as never, { seoTitle: "" } as never, baseAssignments);
		expect(out.seoTitle).toBe("");
	});

	it("preserves an empty-string override.metaDescription (?? semantics)", () => {
		const out = mapContentState(
			baseRecord as never,
			{ metaDescription: "" } as never,
			baseAssignments,
		);
		expect(out.metaDescription).toBe("");
	});

	it("preserves an empty-string override.excerpt (?? semantics)", () => {
		const out = mapContentState(baseRecord as never, { excerpt: "" } as never, baseAssignments);
		expect(out.excerpt).toBe("");
	});
});

tests/flash.test.ts.source:
// Behavioral + mutation-coverage tests for the sqlite flash store
// (src/sqlite-runtime/flash.ts). The flash store is the fix for the
// secret-in-URL class (#113/#115/#133): secrets are handed off via an opaque
// id and read exactly once, server-side. The single-use and expiry guarantees
// are what make putting only `flash=<id>` in the URL safe, so they are asserted
// directly here.
import { describe, expect, it, vi } from "vitest";

import { createFlashStore, FLASH_DEFAULT_TTL_MS, newFlashId } from "../src/sqlite-runtime/flash.js";
import { makeDb } from "./helpers/make-db.js";

function makeStore() {
	const db = makeDb();
	return { db, store: createFlashStore(db) };
}

describe("createFlashStore", () => {
	it("put returns an opaque, non-empty id and consume returns the payload once", async () => {
		const { store } = makeStore();
		const { id } = await store.put("super-secret-token");
		expect(id).toMatch(/^flash_[0-9a-f]{36}$/);

		const first = await store.consume(id);
		expect(first).toBe("super-secret-token");
	});

	it("consume is single-use: a second read of the same id returns null", async () => {
		const { store } = makeStore();
		const { id } = await store.put("once-only");

		expect(await store.consume(id)).toBe("once-only");
		expect(await store.consume(id)).toBeNull();
	});

	it("consume deletes the row even when the payload is read (no residue)", async () => {
		const { db, store } = makeStore();
		const { id } = await store.put("leave-no-trace");
		await store.consume(id);

		const row = db.prepare("SELECT id FROM admin_flash WHERE id = ?").get(id);
		expect(row).toBeUndefined();
	});

	it("consume returns null for an unknown id", async () => {
		const { store } = makeStore();
		expect(await store.consume("flash_does-not-exist")).toBeNull();
	});

	it("expired entries are treated as absent and are not readable", async () => {
		const { store } = makeStore();
		const { id } = await store.put("stale", -1);
		expect(await store.consume(id)).toBeNull();
	});

	it("consume of an expired id still deletes the row so it cannot be replayed", async () => {
		const { db, store } = makeStore();
		const { id } = await store.put("stale", -1);
		await store.consume(id);
		const row = db.prepare("SELECT id FROM admin_flash WHERE id = ?").get(id);
		expect(row).toBeUndefined();
	});

	it("put sweeps already-expired rows so the table does not grow unbounded", async () => {
		const { db, store } = makeStore();
		await store.put("old", -1);
		// A fresh put runs the sweep, removing the expired row above.
		await store.put("fresh");
		const remaining = db.prepare("SELECT payload FROM admin_flash").all() as Array<{
			payload: string;
		}>;
		expect(remaining.map((r) => r.payload)).toEqual(["fresh"]);
	});

	it("default TTL stores an entry that is still readable shortly after", async () => {
		const { db, store } = makeStore();
		const before = Date.now();
		const { id } = await store.put("ttl-default");
		const row = db.prepare("SELECT expires_at_ms FROM admin_flash WHERE id = ?").get(id) as {
			expires_at_ms: number;
		};
		expect(row.expires_at_ms).toBeGreaterThanOrEqual(before + FLASH_DEFAULT_TTL_MS);
		expect(await store.consume(id)).toBe("ttl-default");
	});

	it("two put calls yield distinct ids", async () => {
		const { store } = makeStore();
		const a = await store.put("a");
		const b = await store.put("b");
		expect(a.id).not.toBe(b.id);
	});

	it("newFlashId emits unique opaque ids", () => {
		expect(newFlashId()).not.toBe(newFlashId());
	});

	it("treats an entry whose expiry equals the current instant as expired (boundary: <=)", async () => {
		// Pin time so expires_at_ms === Date.now() exactly at consume. The guard
		// is `expires_at_ms <= now`: at the boundary the entry is expired. A
		// `<` mutant would (wrongly) return the payload — this asserts the `=`.
		const fixed = 1_700_000_000_000;
		const spy = vi.spyOn(Date, "now").mockReturnValue(fixed);
		try {
			const { db, store } = makeStore();
			const { id } = await store.put("edge", 0); // expires_at_ms = fixed + 0
			expect(await store.consume(id)).toBeNull();
			// Still consumed (deleted) so the boundary entry can't be replayed.
			expect(db.prepare("SELECT id FROM admin_flash WHERE id = ?").get(id)).toBeUndefined();
		} finally {
			spy.mockRestore();
		}
	});
});

