import { beforeEach, describe, expect, test, vi } from "vitest";
import type { AccessSnapshot } from "../src/access/d1-access-store";
import { getAccessContext } from "../src/access/request-context";

let mockD1Result: AccessSnapshot | null = null;

vi.mock("../src/access/d1-access-store", () => ({
	loadAccessSnapshotFromD1: vi.fn(async () => mockD1Result),
}));

function makeD1Locals(adminUser: { email: string; isAdmin: boolean; id?: string }) {
	const fakeDb = {
		prepare: () => ({ bind: () => ({ first: async () => null, all: async () => [] }) }),
	};
	return {
		adminUser,
		runtime: { env: { DB: fakeDb } },
	} as unknown as App.Locals;
}

describe("getAccessContext — D1 branch (kill NoCoverage mutants)", () => {
	beforeEach(() => {
		mockD1Result = null;
	});

	test("uses the D1 snapshot when loadAccessSnapshotFromD1 returns a non-null result", async () => {
		mockD1Result = {
			userId: "u-42",
			isAdmin: false,
			roles: ["editor"],
			attributes: { dept: "eng" },
			policies: [
				{
					id: "p1",
					effect: "allow",
					action: "media:upload",
					source: { kind: "direct" },
				},
			],
		};
		const ctx = await getAccessContext({
			locals: makeD1Locals({ email: "u@example.com", isAdmin: false }),
		});
		if (!ctx) throw new Error("expected ctx");
		expect(ctx.subject.id).toBe("u-42");
		expect(ctx.subject.roles).toEqual(["editor"]);
		expect(ctx.subject.attributes).toEqual({ dept: "eng" });
		expect(ctx.subject.isAdmin).toBe(false);
		expect(ctx.can("media:upload").decision).toBe("allow");
	});

	test("the D1 snapshot OR-combines with isAuthUserAdmin (auth flag wins over stale is_admin column)", async () => {
		mockD1Result = {
			userId: "u-1",
			isAdmin: false,
			roles: [],
			attributes: {},
			policies: [],
		};
		const ctx = await getAccessContext({
			locals: makeD1Locals({ email: "a@example.com", isAdmin: true }),
		});
		if (!ctx) throw new Error("expected ctx");
		expect(ctx.subject.isAdmin).toBe(true);
	});

	test("the D1 snapshot keeps isAdmin true when the DB already says is_admin = 1", async () => {
		mockD1Result = {
			userId: "u-2",
			isAdmin: true,
			roles: [],
			attributes: {},
			policies: [],
		};
		const ctx = await getAccessContext({
			locals: makeD1Locals({ email: "a@example.com", isAdmin: false }),
		});
		if (!ctx) throw new Error("expected ctx");
		expect(ctx.subject.isAdmin).toBe(true);
	});

	test("falls back to admin-only snapshot when D1 returns null (kills adminOnlySnapshot NoCoverage)", async () => {
		mockD1Result = null;
		const ctx = await getAccessContext({
			locals: makeD1Locals({ email: "missing@example.com", isAdmin: true }),
		});
		if (!ctx) throw new Error("expected ctx");
		expect(ctx.subject.id).toBe("email:missing@example.com");
		expect(ctx.subject.isAdmin).toBe(true);
		expect(ctx.subject.roles).toEqual([]);
		expect(ctx.subject.attributes).toEqual({});
	});

	test("admin-only fallback uses adminUser.id when present (pins ?? operand order)", async () => {
		mockD1Result = null;
		const locals = {
			adminUser: { id: "id-explicit", email: "x@example.com", isAdmin: true },
			runtime: { env: { DB: { prepare: () => ({}) } } },
		} as unknown as App.Locals;
		const ctx = await getAccessContext({ locals });
		if (!ctx) throw new Error("expected ctx");
		expect(ctx.subject.id).toBe("id-explicit");
	});

	test("admin-only fallback (non-admin user, D1 returns null) emits empty roles/policies", async () => {
		mockD1Result = null;
		const locals = {
			adminUser: { email: "editor@example.com", isAdmin: false },
			runtime: { env: { DB: { prepare: () => ({}) } } },
		} as unknown as App.Locals;
		const ctx = await getAccessContext({ locals });
		if (!ctx) throw new Error("expected ctx");
		expect(ctx.subject.isAdmin).toBe(false);
		// Non-admin with empty policies → can() denies arbitrary actions
		expect(ctx.can("media:upload").decision).toBe("deny");
	});
});

tests/deploy-and-sync.contract.test.ts.source:
import { mkdir, mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { describe, expect, it } from "vitest";
import { createAstropressCloudflarePagesDeployTarget } from "../src/deploy/cloudflare-pages.js";
import { createAstropressGitHubPagesDeployTarget } from "../src/deploy/github-pages.js";
import { createAstropressGitLabPagesDeployTarget } from "../src/deploy/gitlab-pages.js";
import { createAstropressNetlifyDeployTarget } from "../src/deploy/netlify.js";
import { createAstropressRenderDeployTarget } from "../src/deploy/render.js";
import { createAstropressVercelDeployTarget } from "../src/deploy/vercel.js";
import { createAstropressGitSyncAdapter } from "../src/sync/git.js";

describe("deploy and sync contracts", () => {
	it("deploys a build directory to the github pages target", async () => {
		const workspace = await mkdtemp(join(tmpdir(), "astropress-gh-pages-"));
		const buildDir = join(workspace, "dist");
		const outputDir = join(workspace, "deployments");
		await mkdir(buildDir, { recursive: true });
		await writeFile(join(buildDir, "index.html"), "<h1>Astropress</h1>");

		const target = createAstropressGitHubPagesDeployTarget({
			outputDir,
			baseUrl: "https://example.com/docs",
		});

		const result = await target.deploy({
			buildDir,
			projectName: "demo-site",
		});

		expect(result.url).toBe("https://example.com/docs/demo-site/");
		expect(await readFile(join(outputDir, "demo-site", "index.html"), "utf8")).toContain(
			"Astropress",
		);
		expect(
			await readFile(join(outputDir, "demo-site", ".astropress-deploy.json"), "utf8"),
		).toContain('"provider": "github-pages"');

		await rm(workspace, { recursive: true, force: true });
	});

	it("prepares build directories for the other app-host deploy targets", async () => {
		const workspace = await mkdtemp(join(tmpdir(), "astropress-host-deploys-"));
		const buildDir = join(workspace, "dist");
		await mkdir(buildDir, { recursive: true });
		await writeFile(join(buildDir, "index.html"), "<h1>Astropress</h1>");

		for (const [factory, provider] of [
			[createAstropressCloudflarePagesDeployTarget, "cloudflare-pages"],
			[createAstropressVercelDeployTarget, "vercel"],
			[createAstropressNetlifyDeployTarget, "netlify"],
			[createAstropressRenderDeployTarget, "render-web"],
			[createAstropressGitLabPagesDeployTarget, "gitlab-pages"],
		] as const) {
			const outputDir = join(workspace, provider);
			const target = factory({ outputDir } as never);
			const result = await target.deploy({
				buildDir,
				projectName: "demo-site",
			});

			expect(result.deploymentId).toContain("demo-site");
			expect(
				await readFile(join(outputDir, "demo-site", ".astropress-deploy.json"), "utf8"),
			).toContain(provider);
		}

		await rm(workspace, { recursive: true, force: true });
	});

	it("round-trips a project snapshot through git sync", async () => {
		const workspace = await mkdtemp(join(tmpdir(), "astropress-sync-"));
		const projectDir = join(workspace, "project");
		const snapshotDir = join(workspace, "snapshot");
		await mkdir(join(projectDir, "src"), { recursive: true });
		await writeFile(join(projectDir, "package.json"), '{"name":"demo"}');
		await writeFile(join(projectDir, "src", "index.ts"), "export const demo = true;");

		const sync = createAstropressGitSyncAdapter({ projectDir });
		const exported = await sync.exportSnapshot(snapshotDir);
		await writeFile(join(projectDir, "src", "index.ts"), "export const demo = false;");
		const imported = await sync.importSnapshot(snapshotDir);

		expect(exported.fileCount).toBeGreaterThan(0);
		expect(imported.fileCount).toBe(exported.fileCount);
		expect(await readFile(join(projectDir, "src", "index.ts"), "utf8")).toContain("demo = true");

		await rm(workspace, { recursive: true, force: true });
	});
});

tests/html-optimization.test.ts.source:
import { optimizeImageLoading } from "@astropress-diy/astropress";
import { describe, expect, it } from "vitest";

describe("optimizeImageLoading()", () => {
	it("adds loading='lazy' to images without a loading attribute", () => {
		const result = optimizeImageLoading(
			'<img src="/first.jpg" alt="First"><img src="/second.jpg" alt="Second">',
		);
		expect(result).toContain('loading="lazy"');
	});

	it("does not modify images that already have a loading attribute", () => {
		const html = '<img src="/photo.jpg" alt="Photo" loading="eager">';
		const result = optimizeImageLoading(html);
		expect(result).not.toContain('loading="lazy"');
		expect(result).toContain('loading="eager"');
	});

	it("skips the first image (likely hero/LCP) to avoid performance regression", () => {
		const html = '<img src="/hero.jpg" alt="Hero">';
		const result = optimizeImageLoading(html);
		expect(result).not.toContain('loading="lazy"');
	});

	it("adds loading='lazy' to second and subsequent images", () => {
		const html = [
			'<img src="/hero.jpg" alt="Hero">',
			'<img src="/second.jpg" alt="Second">',
			'<img src="/third.jpg" alt="Third">',
		].join("");
		const result = optimizeImageLoading(html);
		const lazyCount = (result.match(/loading="lazy"/g) ?? []).length;
		expect(lazyCount).toBe(2);
	});

	it("skips first image if it has fetchpriority attribute", () => {
		const html =
			'<img src="/hero.jpg" alt="Hero" fetchpriority="high"><img src="/next.jpg" alt="Next">';
		const result = optimizeImageLoading(html);
		expect(result).not.toMatch(/<img[^>]*fetchpriority="high"[^>]*loading="lazy"[^>]*>/);
	});

	it("returns HTML unchanged if there are no img tags", () => {
		const html = "<p>No images here.</p>";
		expect(optimizeImageLoading(html)).toBe(html);
	});

	it("never appends a second loading attr to an image that already has one (non-first position)", () => {
		// First img is the LCP candidate; second already has loading=eager.
		// The loading-check branch must short-circuit so the explicit
		// loading=eager image never gets a duplicate loading="lazy" appended.
		const html = '<img src="/hero.jpg"><img src="/explicit.jpg" loading="eager">';
		const result = optimizeImageLoading(html);
		// Exactly one `loading=` attribute on the second img, and it's "eager".
		const matches = result.match(/loading="[^"]*"/g) ?? [];
		expect(matches).toEqual(['loading="eager"']);
	});

	it("a leading explicit-loading image still consumes the firstImage slot (kills BooleanLiteral mutant in the loading branch)", () => {
		// If the loading branch did NOT set firstImage=false, the second img
		// would be treated as the LCP and skip lazy.
		const html = '<img src="/hero.jpg" loading="eager"><img src="/next.jpg">';
		const result = optimizeImageLoading(html);
		expect(result).toContain('<img src="/next.jpg" loading="lazy">');
	});

	it("never appends loading='lazy' to a non-first image that has fetchpriority", () => {
		// fetchpriority=high signals a non-LCP image we explicitly want to
		// keep eager (e.g. above-the-fold non-hero). Must short-circuit even
		// when not in the firstImage slot.
		const html = '<img src="/hero.jpg"><img src="/banner.jpg" fetchpriority="high">';
		const result = optimizeImageLoading(html);
		// The fetchpriority image must NOT have loading attribute appended.
		expect(result).not.toMatch(/fetchpriority="high"\s+loading=/);
	});

	it("a leading fetchpriority image still consumes the firstImage slot (kills BooleanLiteral mutant in the fetchpriority branch)", () => {
		// If the fetchpriority branch did NOT set firstImage=false, the
		// second img would be treated as the LCP and skip lazy.
		const html = '<img src="/banner.jpg" fetchpriority="high"><img src="/next.jpg">';
		const result = optimizeImageLoading(html);
		expect(result).toContain('<img src="/next.jpg" loading="lazy">');
	});
});

