import { readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { isRtlLocale, localeDirection } from "../src/admin-locale";

const REPO_ROOT = join(__dirname, "..");

describe("admin RTL plumbing", () => {
	it("AdminLocale union includes ar", () => {
		const src = readFileSync(join(REPO_ROOT, "src", "admin-labels.ts"), "utf8");
		expect(src).toMatch(/\|\s*"ar"/);
	});

	it("supported locale list contains ar", () => {
		const src = readFileSync(join(REPO_ROOT, "src", "admin-locale.ts"), "utf8");
		expect(src).toMatch(/"ar"/);
	});

	it("isRtlLocale returns true for ar", () => {
		expect(isRtlLocale("ar")).toBe(true);
	});

	it("isRtlLocale returns false for ltr locales", () => {
		expect(isRtlLocale("en")).toBe(false);
		expect(isRtlLocale("te")).toBe(false);
		expect(isRtlLocale("ja")).toBe(false);
	});

	it("localeDirection returns rtl for ar", () => {
		expect(localeDirection("ar")).toBe("rtl");
	});

	it("localeDirection returns ltr for ltr locales", () => {
		expect(localeDirection("en")).toBe("ltr");
		expect(localeDirection("hi")).toBe("ltr");
	});

	it("AdminLayout.astro emits dir on the html element", () => {
		const src = readFileSync(join(REPO_ROOT, "components", "AdminLayout.astro"), "utf8");
		expect(src).toMatch(/<html\s+lang=\{adminLocale\}\s+dir=\{adminDir\}/);
	});

	it.each([
		"pages/ap-admin/login.astro",
		"pages/ap-admin/accept-invite.astro",
		"pages/ap-admin/reset-password.astro",
	])("%s emits dir={adminDir} on the html element", (relPath) => {
		// Public admin entry pages don't use AdminLayout (they're pre-auth
		// shells), so they must thread `dir` themselves. The previous
		// regression — `<html lang={adminLocale}>` without `dir` — left
		// /ap-admin/login rendered LTR even after the operator picked
		// AR via the language selector.
		const src = readFileSync(join(REPO_ROOT, relPath), "utf8");
		expect(src).toMatch(/<html\s+lang=\{adminLocale\}\s+dir=\{adminDir\}/);
		expect(src).toContain("localeDirection");
	});

	it("admin.css uses logical properties for inline-axis spacing", () => {
		const src = readFileSync(join(REPO_ROOT, "public", "admin.css"), "utf8");
		expect(src).toContain("inset-inline-start:");
		expect(src).toContain("inset-inline-end:");
		expect(src).toContain("padding-inline-start:");
		expect(src).toContain("border-inline-end:");
		expect(src).toMatch(/text-align:\s*start/);
		// And we should not have any user-visible physical properties that would
		// flip wrong under RTL. A few centering tricks (left: 50% + translate)
		// are neutral and excluded by checking only directional spacing.
		expect(src).not.toMatch(/^\s*margin-left:/m);
		expect(src).not.toMatch(/^\s*margin-right:/m);
		expect(src).not.toMatch(/^\s*padding-left:/m);
		expect(src).not.toMatch(/^\s*padding-right:/m);
		expect(src).not.toMatch(/^\s*border-left:/m);
		expect(src).not.toMatch(/^\s*border-right:/m);
	});
});

tests/public-preview-link.test.ts.source:
import { describe, expect, it } from "vitest";
import { resolvePublicPreviewLink } from "../src/public-preview-link.js";

describe("resolvePublicPreviewLink (#181)", () => {
	const adminOnly = new URL("http://127.0.0.1:4325/ap-admin/pages"); // harness: siteUrl === own origin
	const prodAdmin = new URL("https://admin.example.com/ap-admin/pages");

	it("uses a same-origin link when the public renderer is present in this app (dev)", () => {
		expect(
			resolvePublicPreviewLink({
				baseUrl: prodAdmin,
				path: "/welcome",
				siteUrl: "https://example.com",
				publicRendererPresent: true,
			}),
		).toEqual({ href: "/welcome", available: true });
	});

	it("links to an absolute siteUrl when the public site is a different origin (production)", () => {
		expect(
			resolvePublicPreviewLink({
				baseUrl: prodAdmin,
				path: "/welcome",
				siteUrl: "https://example.com",
				publicRendererPresent: false,
			}),
		).toEqual({ href: "https://example.com/welcome", available: true });
	});

	it("is unavailable when no renderer is present and siteUrl is the admin's own origin (harness)", () => {
		expect(
			resolvePublicPreviewLink({
				baseUrl: adminOnly,
				path: "/welcome",
				siteUrl: "http://127.0.0.1:4325",
				publicRendererPresent: false,
			}),
		).toEqual({ href: null, available: false });
	});

	it("is unavailable when no renderer is present and no siteUrl is configured", () => {
		expect(
			resolvePublicPreviewLink({
				baseUrl: prodAdmin,
				path: "/welcome",
				siteUrl: "",
				publicRendererPresent: false,
			}),
		).toEqual({ href: null, available: false });
	});

	it("is unavailable when the row has no path", () => {
		expect(
			resolvePublicPreviewLink({
				baseUrl: prodAdmin,
				path: null,
				siteUrl: "https://example.com",
				publicRendererPresent: true,
			}),
		).toEqual({ href: null, available: false });
	});

	it("normalizes a path missing its leading slash", () => {
		expect(
			resolvePublicPreviewLink({
				baseUrl: prodAdmin,
				path: "welcome",
				siteUrl: "https://example.com",
				publicRendererPresent: false,
			}).href,
		).toBe("https://example.com/welcome");
	});

	it("normalizes a leading-slash-less path for the same-origin (renderer present) case too", () => {
		expect(
			resolvePublicPreviewLink({
				baseUrl: prodAdmin,
				path: "welcome",
				siteUrl: "",
				publicRendererPresent: true,
			}),
		).toEqual({ href: "/welcome", available: true });
	});

	it("treats an unparseable siteUrl as no distinct origin (falls back to disabled)", () => {
		// URL.parse resolves this relative to the admin base → same origin → disabled.
		expect(
			resolvePublicPreviewLink({
				baseUrl: prodAdmin,
				path: "/welcome",
				siteUrl: "not a url",
				publicRendererPresent: false,
			}),
		).toEqual({ href: null, available: false });
	});
});

