import { describe, expect, it } from "vitest";
import type { AstropressPlugin } from "../src/config.js";
import {
	dispatchPluginContentEvent,
	dispatchPluginMediaEvent,
	peekCmsConfig,
	registerCms,
} from "../src/config.js";

function makeMinimalConfig(plugins?: AstropressPlugin[]) {
	return {
		templateKeys: ["home"],
		siteUrl: "https://example.com",
		seedPages: [],
		archives: [],
		translationStatus: [],
		plugins,
	};
}

describe("AstropressPlugin API", () => {
	it("dispatchPluginContentEvent calls onContentSave on registered plugins", async () => {
		const events: string[] = [];
		const plugin: AstropressPlugin = {
			name: "test-plugin",
			onContentSave: ({ slug }) => {
				events.push(`save:${slug}`);
			},
		};
		registerCms(makeMinimalConfig([plugin]));

		await dispatchPluginContentEvent("onContentSave", {
			slug: "my-post",
			kind: "post",
			status: "draft",
			actor: "admin@example.com",
		});

		expect(events).toEqual(["save:my-post"]);
	});

	it("dispatchPluginContentEvent calls onContentPublish only for published status", async () => {
		const events: string[] = [];
		const plugin: AstropressPlugin = {
			name: "publish-plugin",
			onContentPublish: ({ slug }) => {
				events.push(`publish:${slug}`);
			},
		};
		registerCms(makeMinimalConfig([plugin]));

		await dispatchPluginContentEvent("onContentPublish", {
			slug: "my-post",
			kind: "post",
			status: "published",
			actor: "admin@example.com",
		});
		await dispatchPluginContentEvent("onContentSave", {
			slug: "draft-post",
			kind: "post",
			status: "draft",
			actor: "admin@example.com",
		});

		expect(events).toEqual(["publish:my-post"]);
	});

	it("dispatchPluginContentEvent catches errors thrown by plugin hooks", async () => {
		const errorPlugin: AstropressPlugin = {
			name: "broken-plugin",
			onContentSave: () => {
				throw new Error("plugin error");
			},
		};
		registerCms(makeMinimalConfig([errorPlugin]));

		// Should not throw
		await expect(
			dispatchPluginContentEvent("onContentSave", {
				slug: "post",
				kind: "post",
				status: "draft",
				actor: "admin@example.com",
			}),
		).resolves.toBeUndefined();
	});

	it("dispatchPluginContentEvent is a no-op when no plugins are registered", async () => {
		registerCms(makeMinimalConfig([]));
		await expect(
			dispatchPluginContentEvent("onContentSave", {
				slug: "post",
				kind: "post",
				status: "draft",
				actor: "admin@example.com",
			}),
		).resolves.toBeUndefined();
	});

	it("dispatchPluginMediaEvent calls onMediaUpload on registered plugins", async () => {
		const uploads: string[] = [];
		const plugin: AstropressPlugin = {
			name: "media-plugin",
			onMediaUpload: ({ id, mimeType }) => {
				uploads.push(`${id}:${mimeType}`);
			},
		};
		registerCms(makeMinimalConfig([plugin]));

		await dispatchPluginMediaEvent({
			id: "asset-1",
			filename: "photo.jpg",
			mimeType: "image/jpeg",
			size: 1024,
			actor: "admin@example.com",
		});

		expect(uploads).toEqual(["asset-1:image/jpeg"]);
	});

	it("dispatchPluginMediaEvent catches errors thrown by onMediaUpload hooks", async () => {
		const brokenPlugin: AstropressPlugin = {
			name: "broken-media-plugin",
			onMediaUpload: () => {
				throw new Error("media plugin error");
			},
		};
		registerCms(makeMinimalConfig([brokenPlugin]));

		await expect(
			dispatchPluginMediaEvent({
				id: "a",
				filename: "f.jpg",
				mimeType: "image/jpeg",
				size: 0,
				actor: "x@y.com",
			}),
		).resolves.toBeUndefined();
	});

	it("plugins with navItems expose them via getCmsConfig", () => {
		const navPlugin: AstropressPlugin = {
			name: "nav-plugin",
			navItems: [{ label: "My Tool", href: "/ap-admin/my-tool" }],
		};
		registerCms(makeMinimalConfig([navPlugin]));
		const config = peekCmsConfig();
		expect(config?.plugins?.[0]?.navItems?.[0]?.label).toBe("My Tool");
	});

	it("plugin adminRoutes are stored in config and accessible via peekCmsConfig", () => {
		const routePlugin: AstropressPlugin = {
			name: "route-plugin",
			adminRoutes: [
				{
					pattern: "/ap-admin/my-plugin",
					entrypoint: "./src/pages/my-plugin-admin.astro",
				},
				{
					pattern: "/ap-admin/my-plugin/settings",
					entrypoint: "./src/pages/my-plugin-settings.astro",
				},
			],
		};
		registerCms(makeMinimalConfig([routePlugin]));
		const config = peekCmsConfig();
		const routes = config?.plugins?.[0]?.adminRoutes;
		expect(routes).toHaveLength(2);
		expect(routes?.[0]?.pattern).toBe("/ap-admin/my-plugin");
		expect(routes?.[0]?.entrypoint).toBe("./src/pages/my-plugin-admin.astro");
		expect(routes?.[1]?.pattern).toBe("/ap-admin/my-plugin/settings");
	});

	it("plugin with no adminRoutes does not break config access", () => {
		const plainPlugin: AstropressPlugin = { name: "plain-plugin" };
		registerCms(makeMinimalConfig([plainPlugin]));
		const config = peekCmsConfig();
		expect(config?.plugins?.[0]?.adminRoutes).toBeUndefined();
	});
});

describe("createSitemapPlugin", () => {
	it("source file exists and exports createSitemapPlugin", async () => {
		const { createSitemapPlugin: fn } = await import("../src/plugins/sitemap-plugin.js");
		expect(typeof fn).toBe("function");
	});

	it("returned plugin has name 'astropress-sitemap' and onContentPublish hook", async () => {
		const { createSitemapPlugin: fn } = await import("../src/plugins/sitemap-plugin.js");
		const plugin = fn();
		expect(plugin.name).toBe("astropress-sitemap");
		expect(typeof plugin.onContentPublish).toBe("function");
	});

	it("onContentPublish calls onPublish callback with slug", async () => {
		const { createSitemapPlugin: fn } = await import("../src/plugins/sitemap-plugin.js");
		const slugs: string[] = [];
		const plugin = fn({
			onPublish: (slug: string) => {
				slugs.push(slug);
			},
		});
		await plugin.onContentPublish?.({
			slug: "my-post",
			kind: "post",
			status: "published",
			actor: "admin@example.com",
		});
		expect(slugs).toEqual(["my-post"]);
	});
});

tests/runtime-route-registry-dispatch.te.source:
import { afterEach, describe, expect, it, vi } from "vitest";

vi.mock("../src/local-runtime-modules", () => ({
	loadLocalCmsRegistry: vi.fn(),
}));

import { registerCms } from "../src/config";
import { loadLocalCmsRegistry } from "../src/local-runtime-modules";
import {
	loadSafeLocalCmsRegistry,
	localeFromPath,
	parseSettings,
	withSafeRouteRegistryFallback,
} from "../src/runtime-route-registry-dispatch";

const CMS_CONFIG_KEY = Symbol.for("astropress.cms-config");

afterEach(() => {
	(globalThis as typeof globalThis & { [CMS_CONFIG_KEY]?: unknown })[CMS_CONFIG_KEY] = null;
	vi.restoreAllMocks();
});

describe("loadSafeLocalCmsRegistry", () => {
	it("returns the registry when load succeeds", async () => {
		(loadLocalCmsRegistry as ReturnType<typeof vi.fn>).mockResolvedValueOnce({
			marker: "ok",
		});
		expect(await loadSafeLocalCmsRegistry()).toEqual({ marker: "ok" });
	});

	it("returns null when load throws", async () => {
		(loadLocalCmsRegistry as ReturnType<typeof vi.fn>).mockRejectedValueOnce(new Error("nope"));
		expect(await loadSafeLocalCmsRegistry()).toBeNull();
	});
});

describe("withSafeRouteRegistryFallback", () => {
	it("returns the operation result on success (no fallback invoked)", async () => {
		const fallback = vi.fn();
		const result = await withSafeRouteRegistryFallback(fallback, "default", async () => "ok");
		expect(result).toBe("ok");
		expect(fallback).not.toHaveBeenCalled();
	});

	it("invokes fallback with the local registry when operation throws and registry loads", async () => {
		(loadLocalCmsRegistry as ReturnType<typeof vi.fn>).mockResolvedValueOnce({
			marker: "local",
		});
		const fallback = vi.fn(async (local: { marker: string }) => `fb-${local.marker}`);
		const result = await withSafeRouteRegistryFallback(fallback, "default", async () => {
			throw new Error("boom");
		});
		expect(result).toBe("fb-local");
		expect(fallback).toHaveBeenCalledWith({ marker: "local" });
	});

	it("returns defaultValue when operation throws AND registry load fails", async () => {
		(loadLocalCmsRegistry as ReturnType<typeof vi.fn>).mockRejectedValueOnce(
			new Error("registry-also-broken"),
		);
		const fallback = vi.fn();
		const result = await withSafeRouteRegistryFallback(fallback, "default-value", async () => {
			throw new Error("boom");
		});
		expect(result).toBe("default-value");
		expect(fallback).not.toHaveBeenCalled();
	});

	it("returns defaultValue when operation throws AND registry load returns null/undefined", async () => {
		(loadLocalCmsRegistry as ReturnType<typeof vi.fn>).mockResolvedValueOnce(null);
		const result = await withSafeRouteRegistryFallback(vi.fn(), "def", async () => {
			throw new Error("boom");
		});
		expect(result).toBe("def");
	});
});

describe("parseSettings", () => {
	it("returns null for null input", () => {
		expect(parseSettings(null)).toBeNull();
	});

	it("returns null for empty string", () => {
		expect(parseSettings("")).toBeNull();
	});

	it("returns null when JSON.parse throws", () => {
		expect(parseSettings("{not-json}")).toBeNull();
	});

	it("returns null when parsed value is not an object (number)", () => {
		expect(parseSettings("42")).toBeNull();
	});

	it("returns null when parsed value is not an object (string)", () => {
		expect(parseSettings('"hello"')).toBeNull();
	});

	it("returns null when parsed value is JSON null", () => {
		expect(parseSettings("null")).toBeNull();
	});

	it("returns the object when parse succeeds", () => {
		expect(parseSettings('{"a":1}')).toEqual({ a: 1 });
	});

	it("returns arrays as objects too (typeof [] === 'object')", () => {
		expect(parseSettings("[1,2,3]")).toEqual([1, 2, 3]);
	});
});

describe("localeFromPath", () => {
	it("returns the matching locale when pathname has /es/ prefix", () => {
		registerCms({
			siteUrl: "https://example.org",
			templateKeys: ["content"],
			seedPages: [],
			archives: [],
			locales: ["en", "es"],
		} as never);
		expect(localeFromPath("/es/about")).toBe("es");
	});

	it("returns the first locale ('en') when no prefix matches", () => {
		registerCms({
			siteUrl: "https://example.org",
			templateKeys: ["content"],
			seedPages: [],
			archives: [],
			locales: ["en", "es"],
		} as never);
		expect(localeFromPath("/about")).toBe("en");
	});

	it("falls back to ['en','es'] when getCmsConfig throws (config not registered)", () => {
		// CMS config is unset → getCmsConfig throws → catch falls back to ['en','es'].
		expect(localeFromPath("/es/x")).toBe("es");
		expect(localeFromPath("/about")).toBe("en");
	});

	it("falls back to ['en','es'] when locales is missing on the config", () => {
		registerCms({
			siteUrl: "https://example.org",
			templateKeys: ["content"],
			seedPages: [],
			archives: [],
		} as never);
		expect(localeFromPath("/es/x")).toBe("es");
		expect(localeFromPath("/about")).toBe("en");
	});

	it("matches strictly on `/locale/` (not on suffix or substring)", () => {
		registerCms({
			siteUrl: "https://example.org",
			templateKeys: ["content"],
			seedPages: [],
			archives: [],
			locales: ["en", "es", "fr"],
		} as never);
		// "/escape" must not match "es" — leading-slash + trailing-slash anchored.
		expect(localeFromPath("/escape")).toBe("en");
	});

	it("returns 'en' fallback when locales array is empty", () => {
		// Pins `locales[0] ?? "en"`.
		registerCms({
			siteUrl: "https://example.org",
			templateKeys: ["content"],
			seedPages: [],
			archives: [],
			locales: [],
		} as never);
		expect(localeFromPath("/about")).toBe("en");
	});

	it("returns the first custom locale when no prefix matches", () => {
		registerCms({
			siteUrl: "https://example.org",
			templateKeys: ["content"],
			seedPages: [],
			archives: [],
			locales: ["fr", "de"],
		} as never);
		expect(localeFromPath("/about")).toBe("fr");
	});
});

tests/typescript-quality.test.ts.source:
/**
 * Tests for TypeScript quality features:
 * - Branded ID types (ContentId, MediaAssetId, AdminUserId, ApiTokenId, AuditEventId)
 * - ActionResult discriminated union
 */

import { describe, expect, it } from "vitest";
import type { AdminLabelKey, AdminLocale } from "../src/admin-ui.js";
import { adminLabels } from "../src/admin-ui.js";
import type {
	ActionResult,
	AdminUserId,
	ApiTokenId,
	AuditEventId,
	ContentId,
	MediaAssetId,
} from "../src/platform-contracts";

describe("Branded ID types", () => {
	it("ContentId is exported from platform-contracts", () => {
		// Type-level test: if this compiles, the type is exported and assignable
		const id = "record-123" as ContentId;
		expect(id).toBe("record-123");
	});

	it("MediaAssetId is exported from platform-contracts", () => {
		const id = "asset-456" as MediaAssetId;
		expect(id).toBe("asset-456");
	});

	it("AdminUserId is exported from platform-contracts", () => {
		const id = "user-789" as AdminUserId;
		expect(id).toBe("user-789");
	});

	it("ApiTokenId is exported from platform-contracts", () => {
		const id = "token-abc" as ApiTokenId;
		expect(id).toBe("token-abc");
	});

	it("AuditEventId is exported from platform-contracts", () => {
		const id = "event-def" as AuditEventId;
		expect(id).toBe("event-def");
	});

	it("branded string is still a string at runtime", () => {
		const id = "record-123" as ContentId;
		expect(typeof id).toBe("string");
		expect(String(id)).toBe("record-123");
	});
});

describe("ActionResult discriminated union", () => {
	it("ok result carries data", () => {
		const result: ActionResult<{ title: string }> = {
			ok: true,
			data: { title: "Hello" },
		};
		if (result.ok) {
			expect(result.data.title).toBe("Hello");
		}
		expect(result.ok).toBe(true);
	});

	it("error result carries error string", () => {
		const result: ActionResult<never> = {
			ok: false,
			error: "Not found",
			code: "not_found",
		};
		if (!result.ok) {
			expect(result.error).toBe("Not found");
			expect(result.code).toBe("not_found");
		}
		expect(result.ok).toBe(false);
	});

	it("error result code is optional", () => {
		const result: ActionResult<string> = {
			ok: false,
			error: "Validation failed",
		};
		if (!result.ok) {
			expect(result.code).toBeUndefined();
		}
	});

	it("discriminant narrows type correctly", () => {
		function getResult(succeed: boolean): ActionResult<number> {
			if (succeed) return { ok: true, data: 42 };
			return { ok: false, error: "Failed" };
		}

		const ok = getResult(true);
		const fail = getResult(false);

		expect(ok.ok).toBe(true);
		if (ok.ok) expect(ok.data).toBe(42);

		expect(fail.ok).toBe(false);
		if (!fail.ok) expect(fail.error).toBe("Failed");
	});
});

// ─── Admin i18n label map ─────────────────────────────────────────────────────

// Derive the locale set from the runtime keys of adminLabels — guarantees
// every locale defined in the source is exercised here. (Previously this
// was a hardcoded en/es/fr/de/pt/ja list which silently skipped te/hi/ny.)
const ALL_LOCALES = Object.keys(adminLabels) as AdminLocale[];

// English is the authoritative key source; every other locale must match.
const EXPECTED_KEYS = Object.keys(adminLabels.en) as AdminLabelKey[];

describe("admin i18n label map", () => {
	it("has at least 30 label keys", () => {
		expect(EXPECTED_KEYS.length).toBeGreaterThanOrEqual(30);
	});

	it("locale set covers every AdminLocale union member", () => {
		// If you add a new locale to the AdminLocale union, this assertion
		// will fail until you also add an entry to the adminLabels map.
		const expected: AdminLocale[] = ["en", "es", "fr", "de", "pt", "ja", "te", "hi", "ny"];
		for (const loc of expected) {
			expect(ALL_LOCALES, `AdminLocale '${loc}' missing from adminLabels`).toContain(loc);
		}
	});

	for (const locale of ALL_LOCALES) {
		it(`locale '${locale}' has all required keys`, () => {
			const localeKeys = new Set(Object.keys(adminLabels[locale]));
			// Report ALL missing keys, not just the first one — early failure
			// hid the true scope of the gap on previous runs (one error said
			// "missing navGroupSite", reality was 37 missing keys).
			const missing = EXPECTED_KEYS.filter((k) => !localeKeys.has(k));
			expect(
				missing,
				`locale '${locale}' missing ${missing.length} key(s): ${missing.join(", ")}`,
			).toEqual([]);
		});

		it(`locale '${locale}' has no empty string values`, () => {
			for (const [key, value] of Object.entries(adminLabels[locale])) {
				expect(value, `locale '${locale}' key '${key}' is empty`).not.toBe("");
			}
		});
	}

	it("required keys include navigation and content action labels", () => {
		const keys = new Set(EXPECTED_KEYS);
		expect(keys.has("navDashboard")).toBe(true);
		expect(keys.has("navPosts")).toBe(true);
		expect(keys.has("navMedia")).toBe(true);
		expect(keys.has("createPost")).toBe(true);
		expect(keys.has("changeLanguage")).toBe(true);
		expect(keys.has("confirmDelete")).toBe(true);
		expect(keys.has("approveComment")).toBe(true);
	});
});

tests/services-config.test.ts.source:
import { beforeEach, describe, expect, it } from "vitest";
import {
	type AstropressServiceConfig,
	clearAstropressServices,
	getAstropressService,
	getAstropressServices,
	registerAstropressService,
	registerTestimonialsServiceIfConfigured,
	unregisterAstropressService,
} from "../src/services-config";

const cmsService: AstropressServiceConfig = {
	provider: "cms",
	label: "Payload CMS",
	description: "Open-source TypeScript CMS.",
	proxyTarget: "http://localhost:3000",
	adminPath: "/ap-admin/services/cms",
};

const shopService: AstropressServiceConfig = {
	provider: "shop",
	label: "Medusa",
	description: "Open-source headless commerce.",
	proxyTarget: "http://localhost:9000",
	adminPath: "/ap-admin/services/shop",
};

beforeEach(() => {
	clearAstropressServices();
});

describe("registerAstropressService", () => {
	it("registers a service and makes it retrievable", () => {
		registerAstropressService(cmsService);
		expect(getAstropressService("cms")).toEqual(cmsService);
	});

	it("replaces an existing service with the same provider", () => {
		registerAstropressService(cmsService);
		const updated = { ...cmsService, label: "Payload v3" };
		registerAstropressService(updated);
		expect(getAstropressService("cms")?.label).toBe("Payload v3");
		expect(getAstropressServices()).toHaveLength(1);
	});

	it("registers multiple services independently", () => {
		registerAstropressService(cmsService);
		registerAstropressService(shopService);
		expect(getAstropressServices()).toHaveLength(2);
	});
});

describe("getAstropressServices", () => {
	it("returns an empty array when no services are registered", () => {
		expect(getAstropressServices()).toEqual([]);
	});

	it("returns a copy so callers cannot mutate the registry", () => {
		registerAstropressService(cmsService);
		const list = getAstropressServices();
		list.pop();
		expect(getAstropressServices()).toHaveLength(1);
	});

	it("preserves registration order", () => {
		registerAstropressService(cmsService);
		registerAstropressService(shopService);
		const [first, second] = getAstropressServices();
		expect(first.provider).toBe("cms");
		expect(second.provider).toBe("shop");
	});
});

describe("getAstropressService", () => {
	it("returns undefined for an unregistered provider", () => {
		expect(getAstropressService("email")).toBeUndefined();
	});

	it("finds a registered service by provider key", () => {
		registerAstropressService(shopService);
		expect(getAstropressService("shop")?.label).toBe("Medusa");
	});
});

describe("unregisterAstropressService", () => {
	it("removes a specific service", () => {
		registerAstropressService(cmsService);
		registerAstropressService(shopService);
		unregisterAstropressService("cms");
		expect(getAstropressService("cms")).toBeUndefined();
		expect(getAstropressService("shop")).toBeDefined();
	});

	it("is a no-op for a provider that was never registered", () => {
		expect(() => unregisterAstropressService("community")).not.toThrow();
	});
});

describe("clearAstropressServices", () => {
	it("removes all registered services", () => {
		registerAstropressService(cmsService);
		registerAstropressService(shopService);
		clearAstropressServices();
		expect(getAstropressServices()).toEqual([]);
	});
});

describe("registerTestimonialsServiceIfConfigured", () => {
	it("is a no-op when url is absent", () => {
		registerTestimonialsServiceIfConfigured({ type: "typebot" });
		expect(getAstropressService("testimonials")).toBeUndefined();
	});

	it("is a no-op when url is empty string", () => {
		registerTestimonialsServiceIfConfigured({ type: "typebot", url: "" });
		expect(getAstropressService("testimonials")).toBeUndefined();
	});

	it("registers a typebot service with the typebot label and description when url is set", () => {
		registerTestimonialsServiceIfConfigured({
			type: "typebot",
			url: "http://localhost:8080",
		});
		const svc = getAstropressService("testimonials");
		expect(svc?.label).toBe("Typebot");
		expect(svc?.description).toBe("Conversational testimonial and referral capture flows.");
		expect(svc?.proxyTarget).toBe("http://localhost:8080");
		expect(svc?.adminPath).toBe("/ap-admin/services/testimonials");
	});

	it("registers a non-typebot type with the Formbricks label and description", () => {
		registerTestimonialsServiceIfConfigured({
			type: "formbricks",
			url: "http://localhost:9000",
		});
		const svc = getAstropressService("testimonials");
		expect(svc?.label).toBe("Formbricks");
		expect(svc?.description).toBe("Survey and testimonial collection with referral support.");
	});

	it("uses the explicit label when provided, regardless of type", () => {
		registerTestimonialsServiceIfConfigured({
			type: "typebot",
			url: "http://localhost:8080",
			label: "My Custom Label",
		});
		expect(getAstropressService("testimonials")?.label).toBe("My Custom Label");
	});
});

