import { describe, expect, it } from "vitest";
import { collectMediaIds, selectTestimonialsForSection } from "../../src/sections/render-prep";
import type { Section, TestimonialsSection } from "../../src/sections/schema";

describe("collectMediaIds — coverage", () => {
	it("returns empty array for empty input", () => {
		expect(collectMediaIds([])).toEqual([]);
	});

	it("hero without mediaId yields no id", () => {
		const r = collectMediaIds([{ id: "h", kind: "hero", headline: "h", alignment: "start" }]);
		expect(r).toEqual([]);
	});

	it("image-text empty mediaId yields no id", () => {
		const r = collectMediaIds([
			{
				id: "i",
				kind: "image-text",
				heading: "H",
				body: "<p>b</p>",
				mediaId: "",
				imageSide: "start",
			},
		]);
		expect(r).toEqual([]);
	});

	it("preserves first-seen ordering across kinds", () => {
		const sections: Section[] = [
			{
				id: "1",
				kind: "hero",
				headline: "h",
				alignment: "start",
				mediaId: "m1",
			},
			{ id: "2", kind: "gallery", mediaIds: ["m2", "m1"], columns: 3 },
			{
				id: "3",
				kind: "image-text",
				heading: "x",
				body: "<p>x</p>",
				mediaId: "m3",
				imageSide: "start",
			},
		];
		expect(collectMediaIds(sections)).toEqual(["m1", "m2", "m3"]);
	});

	it("ignores other kinds (testimonials, faq, cta-banner, rich-text, feature-grid)", () => {
		const sections: Section[] = [
			{ id: "t", kind: "testimonials", source: "approved", layout: "grid" },
			{ id: "f", kind: "faq", items: [] },
			{
				id: "c",
				kind: "cta-banner",
				headline: "x",
				primaryCta: { label: "x", href: "/" },
				tone: "neutral",
			},
			{ id: "r", kind: "rich-text", html: "<p>x</p>" },
			{ id: "fg", kind: "feature-grid", heading: "h", columns: 3, items: [] },
		];
		expect(collectMediaIds(sections)).toEqual([]);
	});
});

describe("selectTestimonialsForSection — coverage", () => {
	const all = [
		{ id: "a", name: "A", quote: "q", featured: true, status: "approved" },
		{ id: "b", name: "B", quote: "q", featured: false, status: "approved" },
		{ id: "c", name: "C", quote: "q", featured: true, status: "pending" },
		{ id: "d", name: "D", quote: "q", featured: true }, // status undefined
	];

	it("featured: missing status defaults to 'approved' and is included", () => {
		const sec: TestimonialsSection = {
			id: "t",
			kind: "testimonials",
			source: "featured",
			layout: "grid",
		};
		const picked = selectTestimonialsForSection(sec, all);
		expect(picked.map((p) => p.id).sort()).toEqual(["a", "d"]);
	});

	it("featured: featured=false excluded even when approved", () => {
		const sec: TestimonialsSection = {
			id: "t",
			kind: "testimonials",
			source: "featured",
			layout: "grid",
		};
		const picked = selectTestimonialsForSection(sec, all);
		expect(picked.find((p) => p.id === "b")).toBeUndefined();
	});

	it("approved: includes 'd' (undefined status defaults to approved)", () => {
		const sec: TestimonialsSection = {
			id: "t",
			kind: "testimonials",
			source: "approved",
			layout: "grid",
		};
		const picked = selectTestimonialsForSection(sec, all);
		expect(picked.find((p) => p.id === "d")).toBeDefined();
	});

	it("approved: pending status excluded", () => {
		const sec: TestimonialsSection = {
			id: "t",
			kind: "testimonials",
			source: "approved",
			layout: "grid",
		};
		const picked = selectTestimonialsForSection(sec, all);
		expect(picked.find((p) => p.id === "c")).toBeUndefined();
	});

	it("ids without ids array falls through to approved-filter branch", () => {
		// The runtime logic checks `section.source === "ids" && section.ids`
		// so when ids array is missing it falls into the else (approved branch).
		const sec = {
			id: "t",
			kind: "testimonials",
			source: "ids",
			layout: "grid",
		} as TestimonialsSection;
		const picked = selectTestimonialsForSection(sec, all);
		// Falls through to the second `if (source === featured)` test (false),
		// then the final approved branch — so we get all approved ones.
		expect(picked.map((p) => p.id).sort()).toEqual(["a", "b", "d"]);
	});

	it("ids with empty list selects nothing", () => {
		const sec: TestimonialsSection = {
			id: "t",
			kind: "testimonials",
			source: "ids",
			layout: "grid",
			ids: [],
		};
		// Empty Set means filter excludes all — returns [].
		// But the runtime check `section.ids` is truthy for empty array,
		// so the ids branch IS taken.
		const picked = selectTestimonialsForSection(sec, all);
		expect(picked).toEqual([]);
	});

	it("ids does not match unknown id", () => {
		const sec: TestimonialsSection = {
			id: "t",
			kind: "testimonials",
			source: "ids",
			layout: "grid",
			ids: ["zzz"],
		};
		expect(selectTestimonialsForSection(sec, all)).toEqual([]);
	});
});

tests/sqlite-seed-helpers.test.ts.source:
import { describe, expect, it } from "vitest";

import {
	buildTableImportSql,
	buildTableImportStatements,
	guessMimeType,
	toSqlLiteral,
} from "../src/sqlite-seed-helpers";

describe("guessMimeType", () => {
	it("returns image/png for .png paths", () => {
		expect(guessMimeType("a.png")).toBe("image/png");
		expect(guessMimeType("/uploads/x.PNG")).toBe("image/png");
	});

	it("returns image/webp for .webp paths", () => {
		expect(guessMimeType("photo.webp")).toBe("image/webp");
	});

	it("returns image/gif for .gif paths", () => {
		expect(guessMimeType("anim.gif")).toBe("image/gif");
	});

	it("falls back to image/jpeg for unknown extensions", () => {
		expect(guessMimeType("file.jpg")).toBe("image/jpeg");
		expect(guessMimeType("file.jpeg")).toBe("image/jpeg");
		expect(guessMimeType("file.bin")).toBe("image/jpeg");
		expect(guessMimeType("file")).toBe("image/jpeg");
		expect(guessMimeType("")).toBe("image/jpeg");
	});

	it("matches case-insensitively (lowercases input first)", () => {
		expect(guessMimeType("X.WEBP")).toBe("image/webp");
		expect(guessMimeType("Y.GIF")).toBe("image/gif");
	});
});

describe("toSqlLiteral", () => {
	it("encodes null and undefined as NULL", () => {
		expect(toSqlLiteral(null)).toBe("NULL");
		expect(toSqlLiteral(undefined)).toBe("NULL");
	});

	it("renders numbers and bigints unquoted", () => {
		expect(toSqlLiteral(42)).toBe("42");
		expect(toSqlLiteral(0)).toBe("0");
		expect(toSqlLiteral(-7)).toBe("-7");
		expect(toSqlLiteral(BigInt(9007199254740993n))).toBe("9007199254740993");
	});

	it("renders booleans as 1 or 0 (sqlite convention)", () => {
		expect(toSqlLiteral(true)).toBe("1");
		expect(toSqlLiteral(false)).toBe("0");
	});

	it("renders Uint8Array as a hex blob literal", () => {
		expect(toSqlLiteral(new Uint8Array([0xde, 0xad, 0xbe, 0xef]))).toBe("X'deadbeef'");
		expect(toSqlLiteral(new Uint8Array([]))).toBe("X''");
	});

	it("quotes strings and escapes embedded single quotes", () => {
		expect(toSqlLiteral("hi")).toBe("'hi'");
		expect(toSqlLiteral("it's")).toBe("'it''s'");
		expect(toSqlLiteral("a'b'c")).toBe("'a''b''c'");
		expect(toSqlLiteral("")).toBe("''");
	});

	it("stringifies non-string non-special objects (Date, etc.) and quotes the result", () => {
		const date = new Date("2026-05-03T00:00:00Z");
		expect(toSqlLiteral(date)).toBe(`'${String(date)}'`);
	});
});

describe("buildTableImportStatements", () => {
	function makeDb(
		columnsByTable: Record<string, string[]>,
		rowsByTable: Record<string, Record<string, unknown>[]>,
	) {
		return {
			prepare(query: string) {
				if (query.startsWith("PRAGMA table_info")) {
					const m = query.match(/table_info\((\w+)\)/);
					const table = m?.[1] ?? "";
					const cols = columnsByTable[table] ?? [];
					return {
						all: () =>
							cols.map((name, idx) => ({
								cid: idx,
								name,
								type: "TEXT",
								notnull: 0,
								dflt_value: null,
								pk: 0,
							})),
					};
				}
				const m = query.match(/SELECT \* FROM (\w+)/);
				const table = m?.[1] ?? "";
				return {
					all: () => rowsByTable[table] ?? [],
				};
			},
		} as never;
	}

	it("returns an empty list when the table has no columns", () => {
		const db = makeDb({ posts: [] }, { posts: [{ a: 1 }] });
		expect(buildTableImportStatements(db, "posts")).toEqual([]);
	});

	it("emits DELETE then one INSERT per row, in column order", () => {
		const db = makeDb(
			{ posts: ["id", "title"] },
			{
				posts: [
					{ id: 1, title: "hi" },
					{ id: 2, title: "yo" },
				],
			},
		);
		const out = buildTableImportStatements(db, "posts");
		expect(out).toEqual([
			"DELETE FROM posts;",
			"INSERT INTO posts (id, title) VALUES (1, 'hi');",
			"INSERT INTO posts (id, title) VALUES (2, 'yo');",
		]);
	});

	it("renders each row's values via toSqlLiteral (quoting + null + bool)", () => {
		const db = makeDb(
			{ items: ["a", "b", "c", "d"] },
			{
				items: [{ a: null, b: true, c: 0, d: "hello" }],
			},
		);
		expect(buildTableImportStatements(db, "items")).toEqual([
			"DELETE FROM items;",
			"INSERT INTO items (a, b, c, d) VALUES (NULL, 1, 0, 'hello');",
		]);
	});
});

describe("buildTableImportSql", () => {
	it("joins the statements with newlines", () => {
		const db = {
			prepare(query: string) {
				if (query.startsWith("PRAGMA table_info")) {
					return {
						all: () => [{ cid: 0, name: "id", type: "INTEGER" }],
					};
				}
				return { all: () => [{ id: 7 }] };
			},
		} as never;
		expect(buildTableImportSql(db, "x")).toBe("DELETE FROM x;\nINSERT INTO x (id) VALUES (7);");
	});
});

