import { describe, expect, it, vi } from "vitest";

vi.mock("../src/vite-runtime-alias", () => {
	return {
		createAstropressLocalRuntimeModulePlugin: vi.fn((path: string) => ({
			name: "local-runtime",
			__path: path,
		})),
		createAstropressPackageResolverPlugin: vi.fn((root: string) => ({
			name: "package-resolver",
			__root: root,
		})),
		createAstropressViteAliases: vi.fn((options) => [
			{ find: "alias", replacement: String(options?.localRuntimeModulesPath) },
		]),
	};
});

import { createAstropressViteIntegration } from "../src/vite-integration";
import {
	createAstropressLocalRuntimeModulePlugin,
	createAstropressPackageResolverPlugin,
	createAstropressViteAliases,
} from "../src/vite-runtime-alias";

describe("createAstropressViteIntegration", () => {
	it("returns the local-runtime plugin and aliases when astropressPackageRoot is unset", () => {
		const r = createAstropressViteIntegration({
			localRuntimeModulesPath: "/runtime.ts",
		} as never);
		expect(r.plugins).toHaveLength(1);
		expect((r.plugins[0] as { name: string }).name).toBe("local-runtime");
		expect((r.plugins[0] as { __path: string }).__path).toBe("/runtime.ts");
		expect(createAstropressLocalRuntimeModulePlugin).toHaveBeenCalledWith("/runtime.ts");
		expect(createAstropressPackageResolverPlugin).not.toHaveBeenCalled();
	});

	it("appends the package-resolver plugin when astropressPackageRoot is set", () => {
		const r = createAstropressViteIntegration({
			localRuntimeModulesPath: "/runtime.ts",
			astropressPackageRoot: "/pkg",
		} as never);
		expect(r.plugins).toHaveLength(2);
		expect((r.plugins[1] as { name: string }).name).toBe("package-resolver");
		expect((r.plugins[1] as { __root: string }).__root).toBe("/pkg");
		expect(createAstropressPackageResolverPlugin).toHaveBeenCalledWith("/pkg");
	});

	it("returns aliases produced by createAstropressViteAliases verbatim", () => {
		const r = createAstropressViteIntegration({
			localRuntimeModulesPath: "/x.ts",
		} as never);
		expect(r.aliases).toEqual([{ find: "alias", replacement: "/x.ts" }]);
		expect(createAstropressViteAliases).toHaveBeenCalledWith({
			localRuntimeModulesPath: "/x.ts",
		});
	});

	it("plugins array order: local-runtime first, package-resolver second", () => {
		const r = createAstropressViteIntegration({
			localRuntimeModulesPath: "/r.ts",
			astropressPackageRoot: "/pkg",
		} as never);
		expect((r.plugins[0] as { name: string }).name).toBe("local-runtime");
		expect((r.plugins[1] as { name: string }).name).toBe("package-resolver");
	});

	it("does not invoke package-resolver when astropressPackageRoot is empty string (falsy)", () => {
		// Pins ConditionalExpression on `if (options.astropressPackageRoot)`.
		(createAstropressPackageResolverPlugin as { mockClear?: () => void }).mockClear?.();
		const r = createAstropressViteIntegration({
			localRuntimeModulesPath: "/r.ts",
			astropressPackageRoot: "",
		} as never);
		expect(r.plugins).toHaveLength(1);
		expect(createAstropressPackageResolverPlugin).not.toHaveBeenCalled();
	});
});

tests/translation-repository-factory.tes.source:
import { describe, expect, it, vi } from "vitest";
import type { Actor } from "../src/persistence-types";
import { createAstropressTranslationRepository } from "../src/translation-repository-factory";

const actor: Actor = {
	email: "editor@example.com",
	role: "editor",
	name: "Editor Example",
};

describe("createAstropressTranslationRepository", () => {
	it("rejects invalid translation states", () => {
		const repository = createAstropressTranslationRepository({
			readTranslationState: vi.fn(),
			persistTranslationState: vi.fn(),
			recordTranslationAudit: vi.fn(),
		});

		expect(repository.updateTranslationState("/about", "wrong", actor)).toEqual({
			ok: false,
			error:
				"Invalid translation state. Must be one of: not_started, partial, fallback_en, translated, reviewed, published",
		});
	});

	it("persists a valid translation state and records audit data", () => {
		const persistTranslationState = vi.fn();
		const recordTranslationAudit = vi.fn();
		const repository = createAstropressTranslationRepository({
			readTranslationState: vi.fn(),
			persistTranslationState,
			recordTranslationAudit,
		});

		expect(repository.updateTranslationState("/about", "published", actor)).toEqual({ ok: true });
		expect(persistTranslationState).toHaveBeenCalledWith("/about", "published", actor);
		expect(recordTranslationAudit).toHaveBeenCalledWith({
			actor,
			route: "/about",
			state: "published",
		});
	});

	it("falls back when no translation override exists", () => {
		const repository = createAstropressTranslationRepository({
			readTranslationState: vi.fn(() => null),
			persistTranslationState: vi.fn(),
			recordTranslationAudit: vi.fn(),
		});

		expect(repository.getEffectiveTranslationState("/about", "reviewed")).toBe("reviewed");
	});

	it("normalizes the stored translation state", () => {
		const repository = createAstropressTranslationRepository({
			readTranslationState: vi.fn(() => "PUBLISHED"),
			persistTranslationState: vi.fn(),
			recordTranslationAudit: vi.fn(),
		});

		expect(repository.getEffectiveTranslationState("/about")).toBe("published");
	});

	it("uses 'not_started' as the default fallback when caller omits the fallback arg", () => {
		// Pins the default-arg StringLiteral: omit fallback, ensure stored value
		// missing → returns "not_started".
		const repository = createAstropressTranslationRepository({
			readTranslationState: vi.fn(() => null),
			persistTranslationState: vi.fn(),
			recordTranslationAudit: vi.fn(),
		});
		expect(repository.getEffectiveTranslationState("/about")).toBe("not_started");
	});
});

tests/canonical-origin.test.ts.source:
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { resolveCanonicalOrigin } from "../src/canonical-origin";
import * as configModule from "../src/config";
import { peekCmsConfig, registerCms } from "../src/config";

// Capture and restore whatever config the suite started with so we don't leak
// a registered config into sibling test files sharing the module singleton.
let savedConfig: ReturnType<typeof peekCmsConfig>;

function baseConfig(siteUrl: string) {
	return {
		siteName: "Test",
		siteUrl,
		locales: ["en"],
		defaultLocale: "en",
	} as unknown as Parameters<typeof registerCms>[0];
}

describe("resolveCanonicalOrigin (#124)", () => {
	beforeEach(() => {
		savedConfig = peekCmsConfig();
	});
	afterEach(() => {
		if (savedConfig) registerCms(savedConfig);
	});

	it("uses the configured siteUrl origin, ignoring the request host", () => {
		registerCms(baseConfig("https://canonical.example.com"));
		const origin = resolveCanonicalOrigin({
			url: "https://attacker-proxy.evil/sitemap.xml",
		});
		expect(origin).toBe("https://canonical.example.com");
	});

	it("strips path/query from a configured siteUrl down to the origin", () => {
		registerCms(baseConfig("https://canonical.example.com/base/path?x=1"));
		expect(resolveCanonicalOrigin({ url: "https://whatever.test/robots.txt" })).toBe(
			"https://canonical.example.com",
		);
	});

	it("falls back to the request origin when siteUrl is malformed", () => {
		registerCms(baseConfig("not a url"));
		expect(resolveCanonicalOrigin({ url: "https://request-host.test/llms.txt" })).toBe(
			"https://request-host.test",
		);
	});

	it("falls back to the request origin when siteUrl is empty", () => {
		registerCms(baseConfig(""));
		expect(resolveCanonicalOrigin({ url: "https://request-host.test/sitemap.xml" })).toBe(
			"https://request-host.test",
		);
	});

	it("falls back to the request origin when no CMS config is registered (peekCmsConfig() undefined)", () => {
		// The `?.` in `peekCmsConfig()?.siteUrl` matters here: with no config at
		// all, dropping the optional chain would throw on `.siteUrl`. The route
		// must still resolve to the request-derived origin in zero-config setups.
		const spy = vi.spyOn(configModule, "peekCmsConfig").mockReturnValue(undefined);
		try {
			expect(resolveCanonicalOrigin({ url: "https://request-host.test/robots.txt" })).toBe(
				"https://request-host.test",
			);
		} finally {
			spy.mockRestore();
		}
	});
});

tests/integrations/webhooks/registry.tes.source:
import { afterEach, describe, expect, it } from "vitest";

import {
	_resetInboundWebhookRegistryForTests,
	getInboundWebhookProvider,
	InboundWebhookRegistryError,
	listInboundWebhookProviders,
	registerInboundWebhookProvider,
} from "../../../src/integrations/webhooks/registry";

const GITHUB = {
	id: "github",
	label: "GitHub",
	signatureHeader: "X-Hub-Signature-256",
	algorithm: "hmac-sha256" as const,
	eventHeader: "X-GitHub-Event",
};

afterEach(() => _resetInboundWebhookRegistryForTests());

describe("registerInboundWebhookProvider", () => {
	it("registers a provider and returns the same definition", () => {
		expect(registerInboundWebhookProvider({ ...GITHUB })).toEqual(GITHUB);
	});

	it("getInboundWebhookProvider returns the registered provider", () => {
		registerInboundWebhookProvider({ ...GITHUB });
		expect(getInboundWebhookProvider("github")).toEqual(GITHUB);
	});

	it("getInboundWebhookProvider returns undefined for an unregistered id", () => {
		expect(getInboundWebhookProvider("github")).toBeUndefined();
	});

	it("rejects duplicate ids with DUPLICATE_PROVIDER", () => {
		registerInboundWebhookProvider({ ...GITHUB });
		let caught: unknown;
		try {
			registerInboundWebhookProvider({ ...GITHUB });
		} catch (e) {
			caught = e;
		}
		expect(caught).toBeInstanceOf(InboundWebhookRegistryError);
		const err = caught as InboundWebhookRegistryError;
		expect(err.name).toBe("InboundWebhookRegistryError");
		expect(err.code).toBe("DUPLICATE_PROVIDER");
		expect(err.message).toContain("github");
		expect(err.message).toContain("already registered");
	});

	it("listInboundWebhookProviders returns all registered providers", () => {
		registerInboundWebhookProvider({ ...GITHUB });
		registerInboundWebhookProvider({ ...GITHUB, id: "stripe" });
		const ids = listInboundWebhookProviders()
			.map((p) => p.id)
			.sort();
		expect(ids).toEqual(["github", "stripe"]);
	});

	it("listInboundWebhookProviders returns an empty array when none registered", () => {
		expect(listInboundWebhookProviders()).toEqual([]);
	});
});

